    test "render: a span in an unknown file does not poison a known file's lines" {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag = diag.Bag.init(arena);
        _ = try bag.addFile("top.va", "a\nb\n");
        const f1 = try bag.addFile("f1.vh", "x\ny\nz\n");

        // Sorted first (start 3), in a file nobody registered.
        var a = bag.build(.preprocess, .E0101, .{ .start = 3, .end = 4 });
        a.inFile(@fromBackingInt(@intCast(7)));
        try a.emit();
        // Offset 4 of "x\ny\nz\n" is the `z` that starts line 3.
        var b = bag.build(.preprocess, .E0102, .{ .start = 4, .end = 5 });
        b.inFile(f1);
        try b.emit();

        const out = try renderToString(&bag, .{ .explain_hint = false, .summary = false });
        try std.testing.expect(std.mem.find(u8, out, " --> f1.vh:3:1\n") != null);

        var aw: std.Io.Writer.Allocating = .init(arena);
        try diag.renderJson(&bag, &aw.writer);
        try std.testing.expect(std.mem.find(u8, aw.writer.buffered(), "\"file\":\"f1.vh\",\"line\":3,\"col\":1,") != null);
    }

    test "render: a label in another file gets its own header" {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        var bag = diag.Bag.init(arena_state.allocator());
        _ = try bag.addFile("top.va", "aaa\nbbb\nccc\n");
        const f1 = try bag.addFile("inc.vh", "xxx\nyyy\n");
        // Preprocessed text: top.va's 12 bytes, then inc.vh from offset 12.
        bag.map = .{ .segs = &[_]diag.Segment{
            .{ .out_start = 0, .in_start = 0, .file = .root, .kind = .verbatim },
            .{ .out_start = 12, .in_start = 0, .file = f1, .kind = .verbatim },
        } };

        var b = bag.build(.lower, .E0313, .{ .start = 4, .end = 7 });
        b.label(.{ .start = 16, .end = 19 }, "declared here", .{});
        try b.emit();

        try std.testing.expectEqualStrings(
            "error[E0313]: unknown variable\n" ++
                " --> top.va:2:1\n" ++
                "  |\n" ++
                "2 | bbb\n" ++
                "  | ^^^\n" ++
                "  |\n" ++
                " ::: inc.vh:2:1\n" ++
                "  |\n" ++
                "2 | yyy\n" ++
                "  | --- declared here\n" ++
                "  |\n" ++
                "  = note: LRM 6.8\n" ++
                "\n",
            try renderToString(&bag, .{ .explain_hint = false, .summary = false }),
        );
    }

    test "render: columns are measured in the original text, before stripping" {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag = diag.Bag.init(arena);
        // Stripped "def" is 6..9; in the original it is 12..15, column 13.
        _ = try bag.addFile("m.va", "abc /* c */ def\n");
        bag.setStrippedText(.root, "abc   def\n", &.{.{ .out = 5, .src = 11 }});
        try bag.add(.parse, .E0207, .{ .start = 6, .end = 9 }, "", .{});

        const out = try renderToString(&bag, .{ .explain_hint = false, .summary = false });
        try std.testing.expect(std.mem.find(u8, out, " --> m.va:1:13\n  |\n1 | abc /* c */ def\n  |             ^^^\n") != null);

        var aw: std.Io.Writer.Allocating = .init(arena);
        try diag.renderJson(&bag, &aw.writer);
        try std.testing.expect(std.mem.find(u8, aw.writer.buffered(), "\"line\":1,\"col\":13,\"byte_start\":6,\"byte_end\":9}") != null);
    }

    test "render: output depends on the diagnostics, not their emission order" {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const src = "module m;\n  x = 1;\n  y = 2;\nendmodule\n";

        var forward = diag.Bag.init(arena);
        try forward.setSingleFile("o.va", src);
        try forward.add(.lower, .E0313, .{ .start = 12, .end = 13 }, "x", .{});
        try forward.add(.proof, .W0650, .{ .start = 21, .end = 22 }, "y", .{});

        var backward = diag.Bag.init(arena);
        try backward.setSingleFile("o.va", src);
        try backward.add(.proof, .W0650, .{ .start = 21, .end = 22 }, "y", .{});
        try backward.add(.lower, .E0313, .{ .start = 12, .end = 13 }, "x", .{});

        const once = try renderToString(&forward, .{});
        try std.testing.expectEqualStrings(once, try renderToString(&backward, .{}));
        // And rendering is repeatable: a second render of the same bag agrees.
        try std.testing.expectEqualStrings(once, try renderToString(&forward, .{}));
    }

    test "json: every line parses, and every string round-trips" {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag = diag.Bag.init(arena);
        try bag.setSingleFile("j.va", "analog x;\n");

        const msg = "q\" b\\ n\n t\t c\x01 µ";
        var b = bag.build(.lower, .E0313, .{ .start = 7, .end = 8 });
        b.msg("{s}", .{msg});
        b.label(.{ .start = 0, .end = 6 }, "in {s}", .{"analog"});
        b.suggest(.{ .span = .{ .start = 7, .end = 8 }, .replacement = "y" }, "rename", .{});
        try b.emit();
        try bag.add(.proof, .W0650, diag.Span.none, "", .{});

        var aw: std.Io.Writer.Allocating = .init(arena);
        try diag.renderJson(&bag, &aw.writer);
        const out = aw.writer.buffered();
        // One line per diagnostic: the message's '\n' is escaped, not written.
        try std.testing.expectEqual(@as(usize, 2), std.mem.countScalar(u8, out, '\n'));

        var lines = std.mem.splitScalar(u8, out[0 .. out.len - 1], '\n');
        // Sorted: the span-less warning (start 0) first.
        const first = try std.json.parseFromSlice(std.json.Value, arena, lines.next().?, .{});
        const warning = first.value.object;
        try std.testing.expectEqualStrings("W0650", warning.get("code").?.string);
        try std.testing.expectEqualStrings("warning", warning.get("level").?.string);
        try std.testing.expect(warning.get("span").? == .null);

        const second = try std.json.parseFromSlice(std.json.Value, arena, lines.next().?, .{});
        const e = second.value.object;
        try std.testing.expectEqualStrings(msg, e.get("message").?.string);
        try std.testing.expectEqualStrings("lower", e.get("stage").?.string);
        try std.testing.expectEqualStrings("6.8", e.get("lrm").?.string);
        try std.testing.expectEqualStrings("unknown variable", e.get("title").?.string);
        const span = e.get("span").?.object;
        try std.testing.expectEqualStrings("j.va", span.get("file").?.string);
        try std.testing.expectEqual(@as(i64, 1), span.get("line").?.integer);
        try std.testing.expectEqual(@as(i64, 8), span.get("col").?.integer);
        try std.testing.expectEqual(@as(i64, 7), span.get("byte_start").?.integer);
        try std.testing.expectEqual(@as(i64, 8), span.get("byte_end").?.integer);
        const labels = e.get("labels").?.array.items;
        try std.testing.expectEqual(@as(usize, 1), labels.len);
        try std.testing.expectEqualStrings("in analog", labels[0].object.get("text").?.string);
        const notes = e.get("notes").?.array.items;
        try std.testing.expectEqual(@as(usize, 1), notes.len);
        try std.testing.expectEqualStrings("help", notes[0].object.get("kind").?.string);
        try std.testing.expectEqualStrings("y", notes[0].object.get("fix").?.object.get("replacement").?.string);
    }

    test "explain: a code with no citation prints no LRM line" {
        const gpa = std.testing.allocator;
        var aw: std.Io.Writer.Allocating = .init(gpa);
        defer aw.deinit();
        try diag.explain(.E1015, &aw.writer, .off);
        const out = aw.writer.buffered();
        try std.testing.expect(std.mem.startsWith(u8, out, "E1015: more nets and unknowns than a 32-bit row index holds\n\nNot a language rule"));
        try std.testing.expect(std.mem.find(u8, out, "\nLRM ") == null);

        var aw2: std.Io.Writer.Allocating = .init(gpa);
        defer aw2.deinit();
        try diag.explain(.E0207, &aw2.writer, .off);
        try std.testing.expect(std.mem.startsWith(u8, aw2.writer.buffered(), "E0207: unexpected token\nLRM annex A.1.2\n\n"));
    }

    /// Arbitrary text, arbitrary (inverted, past-the-end) spans, labels and
    /// fixes: rendering never panics, prints one headline per kept row, and the
    /// JSON line and column of each primary span match a byte-by-byte count.
    fn renderAnyOne(_: void, s: *std.testing.Smith) anyerror!void {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        var text_buf: [256]u8 = undefined;
        const text = text_buf[0..s.slice(&text_buf)];
        var bag = diag.Bag.init(arena);
        try bag.setSingleFile("f.va", text);

        // Now and then out to maxInt(u32): a span no stage should make, which
        // must still render rather than overflow.
        const hi: u32 = if (s.boolWeighted(7, 1)) @intCast(text.len + 4) else std.math.maxInt(u32);
        var n: usize = 0;
        while (n < 80 and !s.eos()) : (n += 1) {
            const a = s.valueRangeAtMost(u32, 0, hi);
            const z = s.valueRangeAtMost(u32, 0, hi);
            var b = bag.build(.parse, .E0207, .{ .start = a, .end = z });
            if (s.boolWeighted(1, 1)) b.point("p", .{});
            if (s.boolWeighted(1, 1)) {
                const ls = s.valueRangeAtMost(u32, 0, hi);
                b.label(.{ .start = ls, .end = s.valueRangeAtMost(u32, 0, hi) }, "l", .{});
            }
            if (s.boolWeighted(1, 1)) {
                const fs = s.valueRangeAtMost(u32, 0, hi);
                b.suggest(.{ .span = .{ .start = fs, .end = s.valueRangeAtMost(u32, 0, hi) }, .replacement = "r\tµ" }, "h", .{});
            }
            try b.emit();
        }

        var text_out: std.Io.Writer.Allocating = .init(arena);
        try diag.render(&bag, &text_out.writer, .{});
        try std.testing.expectEqual(bag.count(), std.mem.count(u8, text_out.writer.buffered(), "error[E0207]"));

        var json_out: std.Io.Writer.Allocating = .init(arena);
        try diag.renderJson(&bag, &json_out.writer);
        const json = json_out.writer.buffered();
        try std.testing.expectEqual(bag.count(), std.mem.countScalar(u8, json, '\n'));

        var lines = std.mem.splitScalar(u8, json, '\n');
        for (0..bag.count()) |i| {
            const line = lines.next().?;
            const span = bag.at(i).span;
            if (span.isNone()) {
                try std.testing.expect(std.mem.find(u8, line, "\"span\":null") != null);
                continue;
            }
            const upto = @min(span.start, text.len);
            const want_line = std.mem.countScalar(u8, text[0..upto], '\n') + 1;
            const line_start = if (std.mem.findScalarLast(u8, text[0..upto], '\n')) |nl| nl + 1 else 0;
            const want = try arena.print("\"span\":{{\"file\":\"f.va\",\"line\":{d},\"col\":{d},\"byte_start\":{d},", .{
                want_line, span.start - line_start + 1, span.start,
            });
            try std.testing.expect(std.mem.find(u8, line, want) != null);
        }
    }

    test "render never panics on any span over any text" {
        try std.testing.fuzz({}, renderAnyOne, .{ .corpus = &.{ "ab\r\ncd", "\t\tµ\n", "x" } });
    }

    // ---------------------------------------------------------------------------
    // The catalogue
    // ---------------------------------------------------------------------------

    test "every catalogue citation is a clause, an annex, or an IEEE 1364-2005 clause" {
        // `annexWord` reads the first byte; this pins what it may see. Code values
        // are dense (the catalogue's comptime check), so a runtime loop covers all.
        for (0..@typeInfo(diag.Code).@"enum".field_names.len) |i| {
            const lrm = diag.info(@fromBackingInt(@intCast(i))).lrm;
            if (lrm.len == 0) continue;
            const ok = (lrm[0] >= '0' and lrm[0] <= '9') or
                (lrm[0] >= 'A' and lrm[0] <= 'H') or
                std.mem.startsWith(u8, lrm, "IEEE 1364-2005 ");
            try std.testing.expect(ok);
        }
    }

    test "render: a span out to maxInt(u32) over stripped text clamps, never overflows" {
        // Offsets come from every stage; one bad end must cost a wide caret, not
        // an integer-overflow panic in the strip map (`toSourceOffset`).
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag = diag.Bag.init(arena);
        _ = try bag.addFile("m.va", "abc /* c */ def\n");
        bag.setStrippedText(.root, "abc   def\n", &.{.{ .out = 5, .src = 11 }});

        const max = std.math.maxInt(u32);
        var b = bag.build(.lower, .E0313, .{ .start = 6, .end = max });
        b.suggest(.{ .span = .{ .start = 6, .end = max }, .replacement = "x" }, "h", .{});
        try b.emit();
        try bag.add(.lower, .E0207, .{ .start = max - 1, .end = max }, "", .{});
        // No trailing newline: the last line has text past any offset.
        const f1 = try bag.addFile("n.va", "xy");
        var c = bag.build(.preprocess, .E0101, .{ .start = max - 1, .end = max });
        c.inFile(f1);
        try c.emit();

        const out = try renderToString(&bag, .{ .explain_hint = false, .summary = false });
        try std.testing.expect(std.mem.find(u8, out, " --> m.va:1:13\n") != null);
        var aw: std.Io.Writer.Allocating = .init(arena);
        try diag.renderJson(&bag, &aw.writer);
        try std.testing.expectEqual(@as(usize, 3), std.mem.countScalar(u8, aw.writer.buffered(), '\n'));
    }

    test "every code an explanation cites exists" {
        // A cross-reference ("see E0572") is the reader's next `--explain`; a
        // typo or a dropped code would send them nowhere.
        for (0..@typeInfo(diag.Code).@"enum".field_names.len) |i| {
            const text = diag.info(@fromBackingInt(@intCast(i))).explain;
            for (0..text.len -| 4) |k| {
                if (text[k] != 'E' and text[k] != 'W') continue;
                if (k > 0 and std.ascii.isAlphanumeric(text[k - 1])) continue;
                const word = text[k..][0..5];
                if (!std.ascii.isDigit(word[1]) or !std.ascii.isDigit(word[4])) continue;
                if (k + 5 < text.len and std.ascii.isAlphanumeric(text[k + 5])) continue;
                if (std.meta.stringToEnum(diag.Code, word) == null) {
                    std.debug.print("{s} cites {s}\n", .{ diag.Code.name(@fromBackingInt(@intCast(i))), word });
                    return error.TestUnexpectedResult;
                }
            }
        }
    }

    test "render: the summary counts the errors the cap dropped, and one fails the bag" {
        var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // A full bag of warnings, then an error past the cap: the compilation
        // still failed, and the summary says so.
        var bag = diag.Bag.init(arena);
        for (0..diag.max_entries) |i| try bag.add(.proof, .W0650, .at(@intCast(i + 1)), "", .{});
        try bag.add(.lower, .E0313, .at(1000), "", .{});
        try bag.add(.run, .E1157, .at(1001), "", .{}); // a run error, dropped: no compile error
        try bag.add(.proof, .W0651, .at(1002), "", .{});
        try std.testing.expect(bag.failed());
        try std.testing.expect(std.mem.endsWith(u8, try renderToString(&bag, .{ .explain_hint = false }),
            \\warning: 3 further diagnostic(s) not shown (limit 64)
            \\error: could not compile due to 1 previous error(s); 65 warning(s) emitted
            \\
        ));

        // Every error counts, kept or dropped.
        var errs = diag.Bag.init(arena);
        for (0..diag.max_entries + 2) |i| try errs.add(.lower, .E0313, .at(@intCast(i + 1)), "", .{});
        try std.testing.expect(std.mem.endsWith(u8, try renderToString(&errs, .{ .explain_hint = false }), "\nerror: could not compile due to 66 previous error(s)\n"));
    }
};

pub const preprocessor_tests = struct {
    //! Preprocessor tests: source in, expanded text, directive events and
    //! diagnostics checked out. Also the vector-scan differential tests, the
    //! comment-stripping and line-contract properties, the allocation-failure
    //! sweep and the prelude snapshot equivalence tests.
    //! LRM §2.2, §2.4, §2.6.2, §2.7, §2.8, §9.15, §10; IEEE 1364 §13.4.1, §19.

    const std = @import("std");
    const Preprocessor = @import("frontend").Preprocessor;
    const Allocator = std.mem.Allocator;
    const diag = @import("diag");
    const Lexer = @import("frontend").Lexer;
    const token = @import("frontend").token;
    const Parser = @import("frontend").Parser;
    const DefaultDiscipline = Preprocessor.DefaultDiscipline;
    const DefaultTransition = Preprocessor.DefaultTransition;
    const Timescale = Preprocessor.Timescale;
    const NetType = Preprocessor.NetType;
    const NetTypeRegion = Preprocessor.NetTypeRegion;
    const CellRegion = Preprocessor.CellRegion;
    const Drive = Preprocessor.Drive;
    const DriveRegion = Preprocessor.DriveRegion;
    const predefined_macros = Preprocessor.predefined_macros;
    const process = Preprocessor.process;
    const Pp = Preprocessor.Pp;
    const scan_stops = Preprocessor.scan_stops;
    const findStop = Preprocessor.findStop;
    const Qualifier = Preprocessor.Qualifier;

    // ---------------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------------

    pub const testing = std.testing;

    /// Preprocess without the std-def prelude, on an arena backed by the testing
    /// allocator; the result is duped so the arena can be torn down (leak-checked).
    /// Caller owns the returned text and must free it with `testing.allocator`.
    fn runTest(src: []const u8) ![]u8 {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        var bag: diag.Bag = .init(arena_state.allocator());
        const text = (try process(arena_state.allocator(), src, .{ .std_defs = false, .bag = &bag })).text;
        return testing.allocator.dupe(u8, text);
    }

    /// Expects `src`, preprocessed without the prelude, to be exactly `expected`.
    fn expectPp(expected: []const u8, src: []const u8) !void {
        const got = try runTest(src);
        defer testing.allocator.free(got);
        try testing.expectEqualStrings(expected, got);
    }

    /// Expects `src` to keep its newline count through preprocessing, and the
    /// output to contain every `present` string and no `absent` one.
    fn expectPreserved(src: []const u8, present: []const []const u8, absent: []const []const u8) !void {
        const got = try runTest(src);
        defer testing.allocator.free(got);
        try testing.expectEqual(
            std.mem.countScalar(u8, src, '\n'),
            std.mem.countScalar(u8, got, '\n'),
        );
        for (present) |s| try testing.expect(std.mem.find(u8, got, s) != null);
        for (absent) |s| try testing.expect(std.mem.find(u8, got, s) == null);
    }

    /// Expects `src` to fail with exactly one `code` diagnostic whose span lies
    /// inside the file it names.
    fn expectFail(src: []const u8, code: diag.Code) !void {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        var bag: diag.Bag = .init(arena_state.allocator());
        try testing.expectError(error.PreprocessFailed, process(
            arena_state.allocator(),
            src,
            .{ .std_defs = false, .bag = &bag },
        ));
        try testing.expectEqual(@as(usize, 1), bag.count());
        const e = bag.at(0);
        try testing.expectEqual(code, e.code);
        try testing.expect(bag.failed());
        // A preprocess span is file-local: it must index the file it names.
        try testing.expect(e.file != null);
        try testing.expect(e.span.end <= bag.fileText(e.file.?).len);
        // The title carries the condition; the message may not repeat it.
        try testing.expect(std.mem.find(u8, e.message, "LRM") == null);
    }

    test "findStop agrees with the scalar loop it replaced, at every tail boundary" {
        // The one-byte-at-a-time reference `findStop`'s vector block must match.
        const scalar = struct {
            fn find(text: []const u8, from: usize, comptime stops: []const u8) usize {
                var i = from;
                while (i < text.len) : (i += 1) {
                    for (stops) |s| if (text[i] == s) return i;
                }
                return i;
            }
        }.find;

        const lanes = std.simd.suggestVectorLength(u8) orelse 16;
        var prng: std.Random.DefaultPrng = .init(0x5eed);
        const rand = prng.random();
        // Every length from the empty slice through three full vectors, so both
        // tail boundaries and the no-vector-iteration case are covered.
        var buf: [3 * 64 + 1]u8 = undefined;
        for (0..3 * lanes + 1) |len| {
            for (0..64) |_| {
                // A byte set that hits the stops often enough to land one in every
                // lane position, and rarely enough to leave long ordinary runs.
                for (buf[0..len]) |*b| b.* = switch (rand.uintLessThan(u8, 10)) {
                    0 => '"',
                    1 => '\\',
                    2 => '`',
                    3 => '/',
                    4 => '\n',
                    else => 'a' + rand.uintLessThan(u8, 26),
                };
                const text = buf[0..len];
                // Sweep `from` too: `scan` never calls this at offset 0 only.
                for (0..len + 1) |from| {
                    try testing.expectEqual(scalar(text, from, scan_stops), findStop(text, from, scan_stops));
                    try testing.expectEqual(scalar(text, from, "\"\\/"), findStop(text, from, "\"\\/"));
                }
            }
        }
    }

    test "putNewlines emits exactly the newlines the byte loop it replaced did" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);

        var prng: std.Random.DefaultPrng = .init(0xf00d);
        const rand = prng.random();
        var buf: [200]u8 = undefined;
        for (0..buf.len + 1) |len| {
            for (buf[0..len]) |*b| b.* = if (rand.uintLessThan(u8, 4) == 0) '\n' else 'x';
            const span = buf[0..len];

            // The reference: `for (span) |c| if (c == '\n') append('\n');`
            var want: usize = 0;
            for (span) |c| want += @intFromBool(c == '\n');

            var pp: Pp = .{ .arena = arena, .scratch = arena, .opts = .{ .bag = &bag } };
            try pp.putNewlines(span);
            try testing.expectEqual(want, pp.out.items.len);
            for (pp.out.items) |c| try testing.expectEqual(@as(u8, '\n'), c);
        }
    }

    test "§2.4 comments vanish, newlines do not — but the separator survives" {
        try expectPp("a\n\nb\n", "a// gone\n/* two\n   lines */b\n");
        try expectPp("\"// not a comment\"\n", "\"// not a comment\"\n");
        // §2.4 block comments do not nest: the first `*/` closes it.
        try expectPp("x   y\n", "x /* a /* b */ y\n");
        try expectFail("x\n/* never closed\n", .E0102);

        // §2.2 makes a comment a token separator, so a comment with no newline in
        // it leaves one space; otherwise these lex as `12` and `<=`.
        try expectPp("1 2", "1/*c*/2");
        try expectPp("a < = b", "a </*c*/= b");
        // A multi-line comment already separates via its newlines; it must not gain
        // a spurious extra space.
        try expectPp("1\n2", "1/*\n*/2");
    }

    test "§10.4 object-like and function-like macros" {
        try expectPp("\n3.0*v", "`define GAIN 3.0\n`GAIN*v");
        try expectPp("\n((v)*(v))", "`define SQ(x) ((x)*(x))\n`SQ(v)");
        // Nested expansion (fixture ch10 07_nested_macros).
        try expectPp(
            "\n\n(((v)*(v)) + (v))",
            "`define I(x) ((x)*(x))\n`define O(x) (`I(x) + (x))\n`O(v)",
        );
        // Multi-line macro text (fixture ch10 06_define_multiline).
        try expectPp("\n\n(1 + 2)", "`define P (1 + \\\n2)\n`P");
        // A formal is only substituted as a whole identifier, and never inside a
        // string or after a '`'.
        try expectPp("\n\"x\" ax 1", "`define M(x) \"x\" ax x\n`M(1)");
        // Commas inside nested parens do not split arguments.
        try expectPp("\n(max(a,b))+(c)", "`define A(p,q) (p)+(q)\n`A(max(a,b), c)");
        try expectFail("`define SQ(x) x\n`SQ\n", .E0116);
        try expectFail("`define SQ(x) x\n`SQ(1,2)\n", .E0117);
        // A formal spelled inside a §2.8.1 escaped identifier is part of that
        // identifier, not a use of the formal.
        try expectPp("\nreal \\sig-x ;", "`define M(x) real \\sig-x ;\n`M(1)");
    }

    test "§10.4 macro argument brackets must match their openers" {
        // Matched nesting of all three bracket kinds is opaque to the comma split.
        try expectPp("\n{[(a)],b}", "`define SQ(x) x\n`SQ({[(a)],b})");
        // A closer that does not match its opener is E0120: the `(` it abandons
        // is unterminated.
        try expectFail("`define SQ(x) x\n`SQ(2.0]\n", .E0120);
        try expectFail("`define SQ(x) x\n`SQ({a)}\n", .E0120);
        try expectFail("`define SQ(x) x\n`SQ([1,2)]\n", .E0120);
    }

    test "§10.4 a nested invocation in an actual argument is not recursion" {
        // IEEE 1364's recursion rule is about the macro's text referring to
        // itself. `MAX`'s text refers only to its formals; the nested use sits in
        // the call, and arguments are fully expanded before substitution (fixture
        // ch10 49).
        try expectPp(
            "\n((((1.0)>(2.0)?(1.0):(2.0)))>(3.0)?(((1.0)>(2.0)?(1.0):(2.0))):(3.0))",
            "`define MAX(a,b) ((a)>(b)?(a):(b))\n`MAX(`MAX(1.0,2.0),3.0)",
        );
        // An object-like use inside an argument expands there too, and a
        // function-like macro nested in another macro's argument keeps working.
        try expectPp(
            "\n\n((7.0)>(2.0)?(7.0):(2.0))",
            "`define A 7.0\n`define MAX(a,b) ((a)>(b)?(a):(b))\n`MAX(`A,2.0)",
        );
        // Self-reference in the text is still E0118:
        // object-like, function-like, and mutual (indirect).
        try expectFail("`define R `R\n`R\n", .E0118);
        try expectFail("`define F(x) `F(x)\n`F(1)\n", .E0118);
        try expectFail("`define A(x) `B(x)\n`define B(y) `A(y)\n`A(1)\n", .E0118);

        // E0150: a macro that doubles its text 40 times expands to 2^40 tokens,
        // past what u32 offsets address. It is refused by name when the text
        // passes the bound; `text_limit` brings the bound to 1 MiB here so the
        // test does not build 4 GiB first.
        {
            var dbl: std.ArrayList(u8) = .empty;
            defer dbl.deinit(testing.allocator);
            try dbl.appendSlice(testing.allocator, "`define D0 x\n");
            for (1..41) |i| try dbl.print(testing.allocator, "`define D{d} `D{d} `D{d}\n", .{ i, i - 1, i - 1 });
            try dbl.appendSlice(testing.allocator, "`D40\n");
            var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
            defer arena_state.deinit();
            var bag: diag.Bag = .init(arena_state.allocator());
            try testing.expectError(error.PreprocessFailed, process(arena_state.allocator(), dbl.items, .{ .std_defs = false, .bag = &bag, .text_limit = 1 << 20 }));
            try testing.expectEqual(diag.Code.E0150, bag.at(0).code);
            // The same doubling 17 times is 2^17 `x`s, under the bound: expanded.
            var ok_bag: diag.Bag = .init(arena_state.allocator());
            const ok_src = try std.mem.replaceOwned(u8, arena_state.allocator(), dbl.items, "`D40\n", "`D17\n");
            const out = try process(arena_state.allocator(), ok_src, .{ .std_defs = false, .bag = &ok_bag, .text_limit = 1 << 20 });
            try testing.expectEqual(@as(usize, 1 << 17), std.mem.countScalar(u8, out.text, 'x'));
        }
    }

    test "macro nesting has no depth bound: 100,000 nested uses and a 100,000-macro chain" {
        // `M(x)` is `(x)`, so n nested uses expand to n parentheses around 1 and
        // need n live expansions, argument pre-expansion included. 129 was one
        // past the old 128-level cap (E0119); 10,000 crosses many stack segments
        // (`Preprocessor.segment_levels`). Each level copies the text inside it,
        // so the text built is quadratic: 10,000 levels is 50 MB of it.
        for ([_]usize{ 129, 10_000 }) |n| {
            var src: std.ArrayList(u8) = .empty;
            defer src.deinit(testing.allocator);
            var want: std.ArrayList(u8) = .empty;
            defer want.deinit(testing.allocator);
            try src.appendSlice(testing.allocator, "`define M(x) (x)\n");
            try want.append(testing.allocator, '\n');
            for (0..n) |_| try src.appendSlice(testing.allocator, "`M(");
            try want.appendNTimes(testing.allocator, '(', n);
            try src.append(testing.allocator, '1');
            try want.append(testing.allocator, '1');
            try src.appendNTimes(testing.allocator, ')', n);
            try want.appendNTimes(testing.allocator, ')', n);
            try expectPp(want.items, src.items);
        }
        // A chain: M<k> expands to M<k-1>, so the body rescan nests n deep with
        // n distinct names on the cycle guard.
        {
            const n = 100_000;
            var src: std.ArrayList(u8) = .empty;
            defer src.deinit(testing.allocator);
            try src.appendSlice(testing.allocator, "`define M0 end\n");
            for (1..n) |k| try src.print(testing.allocator, "`define M{d} `M{d}\n", .{ k, k - 1 });
            try src.print(testing.allocator, "`M{d}\n", .{n - 1});
            const got = try runTest(src.items);
            defer testing.allocator.free(got);
            try testing.expect(std.mem.endsWith(u8, got, "end\n"));
        }
        // A cycle is still E0118, at any depth.
        try expectFail("`define A `B\n`define B `A\n`A\n", .E0118);
    }

    test "escaped identifiers reach `undef, the conditionals and `default_discipline" {
        // Syntax 10-3 / A.9.3: every directive whose operand is an `identifier`
        // takes the §2.8.1 spelling, not just `define (fixture ch10 50).
        try expectPreserved("`define \\M-X 1\n`ifdef \\M-X\nyes\n`else\nno\n`endif\n", &.{"yes"}, &.{"no"});
        try expectPreserved("`define \\M-X 1\n`undef \\M-X\n`ifndef \\M-X\nyes\n`endif\n", &.{"yes"}, &.{});
        try expectPreserved("`define \\M-X 1\n`ifdef NOPE\na\n`elsif \\M-X\nb\n`else\nc\n`endif\n", &.{"b"}, &.{ "a", "c" });

        // §10.2: annex D.1's `discipline \logic ;` is only nameable this way, and
        // §2.8.1 makes the recorded name the bare bytes between `\` and the space.
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        var bag: diag.Bag = .init(arena_state.allocator());
        const defs = (try process(arena_state.allocator(), "`default_discipline \\logic\n", .{
            .std_defs = false,
            .bag = &bag,
        })).directives.disciplines;
        try testing.expectEqual(@as(usize, 1), defs.len);
        try testing.expectEqualStrings("logic", defs[0].discipline);
    }

    test "IEEE 1364 §19.5: only white space or a comment follows an `include" {
        try expectFail("`include \"constants.vams\" x\n", .E0144);
        // The clause's own legal form: a comment after the name, either kind.
        testing.allocator.free(try runTest("`include \"constants.vams\" // why\n`include \"constants.vams\" /* why */\n"));
    }

    test "§2.8: a macro name does not start with $" {
        try expectFail("`define $X 1\n", .E0109);
        // Escaped, it is an identifier (§2.8.1) and a legal name.
        try expectPreserved("`define \\$X 1\n`\\$X \n", &.{"1"}, &.{});
    }

    test "IEEE 1364 §19.3.1: macro text does not split a string" {
        try expectFail("`define first_half \"start of string\n", .E0145);
        // A closed string, an escaped quote inside one, and a `"` inside an
        // escaped identifier are all whole tokens.
        try expectPreserved("`define S \"a \\\" b\"\n`S\n", &.{"b"}, &.{});
        try expectPreserved("`define E \\q\"x \n`E\n", &.{"q\"x"}, &.{});
    }

    test "IEEE 1364 §19.3.1: a compiler directive is not a macro name" {
        try expectFail("`define include 1\n", .E0143);
        try expectFail("`define __LINE__ 7\n", .E0143);
        try expectFail("`define resetall\n", .E0143);
        // A name that merely contains one is an ordinary macro.
        try expectPreserved("`define includes 1\n`includes\n", &.{"1"}, &.{});
    }

    test "§10.4 undef, and IEEE 1364 conditionals" {
        try expectPreserved(
            "`define A\n`undef A\n`ifdef A\ntaken\n`else\nother\n`endif\n",
            &.{"other"},
            &.{"taken"},
        );
        try expectPreserved(
            "`define S\n`ifdef F\n1\n`elsif S\n2\n`else\n3\n`endif\n",
            &.{"2"},
            &.{ "1", "3" },
        );
        try expectPreserved(
            "`define O\n`define I\n`ifdef O\n`ifdef I\nsix\n`else\ntwo\n`endif\n`else\none\n`endif\n",
            &.{"six"},
            &.{ "two", "one" },
        );
        try expectPreserved("`ifndef NOPE\nyes\n`else\nno\n`endif\n", &.{"yes"}, &.{"no"});
        // An undefined macro inside a dead arm is not an error.
        try expectPreserved("`ifdef NOPE\n`MISSING\n`endif\n", &.{}, &.{"MISSING"});
        try expectFail("`ifdef A\nx\n", .E0101);
        try expectFail("`endif\n", .E0108);
        try expectFail("`ifdef A\n`else\n`else\n`endif\n", .E0106);
    }

    test "§10.5 predefined macros survive undef and resetall" {
        try expectPreserved("`ifdef __VAMS_ENABLE__\nyes\n`endif\n", &.{"yes"}, &.{});
        try expectPreserved(
            "`undef __VAMS_ENABLE__\n`ifdef __VAMS_ENABLE__\nyes\n`endif\n",
            &.{"yes"},
            &.{},
        );
        // ... and so do user macros: IEEE 1364 §19.3 "The text macro facility is
        // not affected by the compiler directive `resetall" (fixture ch10
        // audit_macro_resetall_preserves_user).
        try expectPreserved("`define V 2.0\n`resetall\n`V\n", &.{"2.0"}, &.{});
        try expectPreserved("`resetall\n`ifdef __VAMS_ENABLE__\nyes\n`endif\n", &.{"yes"}, &.{});
    }

    test "§9.15 Table 9-27 reads `timescale back, in seconds" {
        const T = struct {
            /// The published timescale for `src`, which is the whole §9.15 surface:
            /// it contributes nothing to the output text (the first row pins that).
            fn ts(src: []const u8) !?Timescale {
                var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
                defer arena_state.deinit();
                var bag: diag.Bag = .init(arena_state.allocator());
                return (try process(arena_state.allocator(), src, .{
                    .std_defs = false,
                    .bag = &bag,
                })).directives.timescale();
            }
        };
        // Table 9-27's units column is "s", not ticks.
        const t = (try T.ts("`timescale 1ns/1ps\n")).?;
        try testing.expectEqual(@as(f64, 1e-9), t.unit);
        try testing.expectEqual(@as(f64, 1e-12), t.precision);
        // Every magnitude on IEEE 1364 Table 19-1's grid, and the coarsest unit.
        const t2 = (try T.ts("`timescale 100us / 10 ns\n")).?;
        try testing.expectEqual(@as(f64, 100e-6), t2.unit);
        try testing.expectEqual(@as(f64, 10e-9), t2.precision);
        // No directive is not a default: §9.15 says "as specified in `timescale",
        // and with nothing specified the parameter is not known (E0811).
        try testing.expectEqual(@as(?Timescale, null), try T.ts("module m; endmodule\n"));
        // §19.6 `resetall returns it to that state.
        try testing.expectEqual(@as(?Timescale, null), try T.ts("`timescale 1ns/1ps\n`resetall\n"));
        // Off Table 19-1 in each of the three ways, plus §19.8's ordering rule and
        // the two ways of writing the wrong number of operands: all E0142.
        for ([_][]const u8{
            "`timescale 2ns/1ps\n", // magnitude
            "`timescale 1sec/1ps\n", // unit name
            "`timescale 1ns 1ps\n", // no slash
            "`timescale 1ps/1ns\n", // precision coarser than the unit
            "`timescale 1ns/1ps junk\n", // §19.8 takes two operands and no more
            "`timescale\n", // and they are not optional
        }) |src| try expectFail(src, .E0142);
        // The last one in the stream is the one in force (one elaborated module).
        try testing.expectEqual(@as(f64, 1e-3), (try T.ts("`timescale 1ns/1ps\n`timescale 1ms/1us\n")).?.unit);
    }

    test "directives that contribute no text, and rejected ones" {
        try expectPp(
            "\n\n\n",
            "`timescale 1ns/1ps\n`celldefine\n`pragma f harmless\n",
        );
        // IEEE 1364 §19.2/§19.9: applied here, and the word alone passed through
        // for the parser to refuse inside a module.
        try expectPp("`default_nettype\n`unconnected_drive\n", "`default_nettype wire\n`unconnected_drive pull1\n");
        try expectFail("`pragma\n", .E0147);
        try expectFail("`line 3 \"f.v\" 0 // no\n", .E0128);
        // §10.3's word is passed through too (§10.3: only outside module
        // definitions), so the parser can refuse it there.
        try expectPp("\n`default_transition\n", "`default_discipline electrical\n`default_transition 1n\n");
        // §10.6 is the exception: passed through verbatim for the parser, which is
        // the only stage that knows where a design element starts.
        try expectPp(
            "`begin_keywords \"VAMS-2023\"\n`end_keywords\n",
            "`begin_keywords \"VAMS-2023\"\n`end_keywords\n",
        );
        // ... but still dies with an inactive `ifdef arm, like any other directive.
        try expectPp("\n\n\n", "`ifdef NOPE\n`begin_keywords \"VAMS-2.3\"\n`endif\n");
        try expectFail("`MISSING\n", .E0115); // fixture ch10 23
        try expectFail("`nosuchdirective_or_macro\n", .E0115);
        try expectFail("`define R `R\n`R\n", .E0118); // cycle guard
    }

    // ---------------------------------------------------------------------------
    // The three IEEE 1364 directives that scope forward: §19.2 `default_nettype,
    // §19.1 `celldefine, §19.9 `unconnected_drive. §10.1's scope sentence is the
    // shared rule; `Region.inForce` is the shared reader.
    // ---------------------------------------------------------------------------

    /// Preprocess `src` and hand back the three region lists, which is the whole of
    /// what these directives contribute to a compilation.
    fn regionsOf(arena: Allocator, src: []const u8) !struct {
        nettypes: []const NetTypeRegion,
        cells: []const CellRegion,
        drives: []const DriveRegion,
    } {
        var bag: diag.Bag = .init(arena);
        const d = (try process(arena, src, .{ .std_defs = false, .bag = &bag })).directives;
        return .{ .nettypes = d.nettypes, .cells = d.cells, .drives = d.drives };
    }

    test "IEEE 1364 §19.2 `default_nettype publishes a region per directive" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // Every value on §19.2's closed list parses, `none` included. Eleven
        // directives, eleven events, in text-stream order.
        const all = try regionsOf(arena,
            \\`default_nettype wire
            \\`default_nettype tri
            \\`default_nettype tri0
            \\`default_nettype tri1
            \\`default_nettype wand
            \\`default_nettype triand
            \\`default_nettype wor
            \\`default_nettype trior
            \\`default_nettype trireg
            \\`default_nettype uwire
            \\`default_nettype none
            \\
        );
        try testing.expectEqual(@as(usize, 11), all.nettypes.len);
        try testing.expectEqual(NetType.wire, all.nettypes[0].value);
        try testing.expectEqual(NetType.uwire, all.nettypes[9].value);
        try testing.expectEqual(NetType.none, all.nettypes[10].value);

        // Syntax 19-2 has no line break between the word and its operand, so a
        // word alone on its line takes the next one, and the line count survives.
        const next = try regionsOf(arena, "`default_nettype\n\n  none\n`unconnected_drive\npull1\n");
        try testing.expectEqual(NetType.none, next.nettypes[0].value);
        try testing.expectEqual(Drive.pull1, next.drives[0].value);
        try expectPp("`default_nettype\n\n\n`unconnected_drive\n\n", "`default_nettype\n\n  none\n`unconnected_drive\npull1\n");

        // §19.2's list is closed, and it is not §10.2's: `reg`, `real` and
        // `supply0` are `default_discipline qualifiers and not net types.
        for ([_][]const u8{
            "`default_nettype reg\n",
            "`default_nettype real\n",
            "`default_nettype supply0\n",
            "`default_nettype wires\n", // a typo, not a twelfth type
            "`default_nettype\n", // no brackets in §19.2: mandatory
            "`default_nettype wire tri\n", // and exactly one
        }) |src| try expectFail(src, .E0140);

        // §10.1: a region runs from the directive to the next one. Before the first
        // there is no region, and §19.2 names the state there: wire.
        const r = try regionsOf(arena, "module a; endmodule\n`default_nettype none\nmodule b; endmodule\n");
        try testing.expectEqual(@as(usize, 1), r.nettypes.len);
        try testing.expectEqual(NetType.wire, NetTypeRegion.inForce(r.nettypes, 0, .default));
        try testing.expectEqual(NetType.none, NetTypeRegion.inForce(r.nettypes, r.nettypes[0].at, .default));
        try testing.expectEqual(NetType.none, NetTypeRegion.inForce(r.nettypes, r.nettypes[0].at + 1, .default));

        // IEEE 1364 §19.6, said twice: `resetall returns it to `wire`, and that is
        // an event and not an erasure: the region above the reset keeps its value.
        const reset = try regionsOf(arena, "`default_nettype none\n`resetall\n");
        try testing.expectEqual(@as(usize, 2), reset.nettypes.len);
        try testing.expectEqual(NetType.none, reset.nettypes[0].value);
        try testing.expectEqual(NetType.wire, reset.nettypes[1].value);
        try testing.expectEqual(NetType.none, NetTypeRegion.inForce(reset.nettypes, reset.nettypes[0].at, .default));
    }

    test "IEEE 1364 §19.1 `celldefine tags the modules between the pair" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // The tag is a region, so what a consumer asks is "was this offset inside
        // one". Three modules, one of them a cell.
        const src =
            \\module outside_before; endmodule
            \\`celldefine
            \\module the_cell; endmodule
            \\`endcelldefine
            \\module outside_after; endmodule
            \\
        ;
        const r = try regionsOf(arena, src);
        try testing.expectEqual(@as(usize, 2), r.cells.len);
        try testing.expect(r.cells[0].value);
        try testing.expect(!r.cells[1].value);
        // Before the pair, inside it, after it.
        try testing.expect(!CellRegion.inForce(r.cells, 0, false));
        try testing.expect(CellRegion.inForce(r.cells, r.cells[0].at, false));
        try testing.expect(!CellRegion.inForce(r.cells, r.cells[1].at, false));

        // §19.6 again: the reset closes an open `celldefine.
        const reset = try regionsOf(arena, "`celldefine\n`resetall\n");
        try testing.expectEqual(@as(usize, 2), reset.cells.len);
        try testing.expect(!reset.cells[1].value);
    }

    test "IEEE 1364 §19.9 `unconnected_drive publishes pull0/pull1 regions" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        const r = try regionsOf(arena,
            \\module before_any_directive; endmodule
            \\`unconnected_drive pull1
            \\`nounconnected_drive
            \\`unconnected_drive pull0
            \\
        );
        try testing.expectEqual(@as(usize, 3), r.drives.len);
        try testing.expectEqual(Drive.pull1, r.drives[0].value);
        try testing.expectEqual(Drive.float, r.drives[1].value);
        try testing.expectEqual(Drive.pull0, r.drives[2].value);
        // Above the first directive there is no region, and §19.9's state there is
        // "not pulled". A query at a directive's offset is inside its region (the
        // offset is where the directive's own collapsed text ends), which is what
        // makes a module declared on the next line the subject of it.
        try testing.expectEqual(Drive.float, DriveRegion.inForce(r.drives, 0, .default));
        try testing.expectEqual(Drive.pull1, DriveRegion.inForce(r.drives, r.drives[0].at, .default));

        // §19.9's operand is a two-way alternation and it is not optional: the
        // form that takes none is the separate directive `nounconnected_drive.
        for ([_][]const u8{
            "`unconnected_drive\n",
            "`unconnected_drive pull2\n",
            "`unconnected_drive float\n", // `.float` is the other directive's value
            "`unconnected_drive pull1 pull0\n",
        }) |src| try expectFail(src, .E0141);
        // The operand-less directives do not police their line: `nounconnected_drive
        // pull1` is accepted and the trailing word collapses with the directive,
        // exactly as it does after `celldefine` and (necessarily) after `pragma`.
        // ponytail: one more handler would catch the typo of writing the closing
        // directive with the opening one's operand. Worth it the day a model does.
        try testing.expectEqual(Drive.float, (try regionsOf(arena, "`nounconnected_drive pull1\n")).drives[0].value);

        const reset = try regionsOf(arena, "`unconnected_drive pull1\n`resetall\n");
        try testing.expectEqual(Drive.float, reset.drives[1].value);
    }

    test "§10.1 scopes a directive across a source file boundary" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // §10.1: "The scope of compiler directives extends from the point where it
        // is processed, across all files processed, to the point where another
        // compiler directive supersedes it or the processing completes." So an
        // `include neither opens nor closes a region. The annex D files are the
        // only ones this test can include without a filesystem, and they are enough
        // because what is being checked is that the boundary changes nothing.
        var bag: diag.Bag = .init(arena);
        const d = (try process(arena,
            \\`default_nettype none
            \\`celldefine
            \\`include "constants.vams"
            \\module after_the_include; endmodule
            \\
        , .{ .std_defs = false, .bag = &bag })).directives;
        const nettypes = d.nettypes;
        const cells = d.cells;

        // One event each (the included file wrote none), and both still in force
        // at the end of the stream, which is the far side of the boundary.
        try testing.expectEqual(@as(usize, 1), nettypes.len);
        try testing.expectEqual(@as(usize, 1), cells.len);
        const eof = std.math.maxInt(u32);
        try testing.expectEqual(NetType.none, NetTypeRegion.inForce(nettypes, eof, .default));
        try testing.expect(CellRegion.inForce(cells, eof, false));
    }

    test "§10.7 `__FILE__ and `__LINE__" {
        // fixtures ch10 21, 22. The default `Options.file_name` is "<source>".
        try expectPp("\"<source>\"\n", "`__FILE__\n");
        // physical lines, counted through the comment the stripper deleted and
        // through a directive that collapsed to its newline.
        try expectPp("\n\n\n4 4\n", "// c\n`define X 1\n\n`__LINE__ `__LINE__\n");
        // fixture ch10 44: IEEE 1364 §19.7 numbers the line after the directive.
        try expectPp("\n100\n101\n", "`line 100 \"virtual.va\" 0\n`__LINE__\n`__LINE__\n");
        try expectPp("\n\"virtual.va\"\n", "`line 100 \"virtual.va\" 0\n`__FILE__\n");
        try expectFail("`line\n", .E0128);
        try expectFail("`line nope\n", .E0128);
        // IEEE 1364 §19.7: "All parameters in the `line directive are required",
        // the number is positive, the level is 0, 1 or 2, and nothing follows.
        try expectFail("`line 5\n", .E0128);
        try expectFail("`line 5 \"f.va\"\n", .E0128);
        try expectFail("`line 0 \"f.va\" 0\n", .E0128);
        try expectFail("`line 5 \"f.va\" 3\n", .E0128);
        try expectFail("`line 5 \"f.va\" 1 x\n", .E0128);
        try expectPp("\n6\n", "`line 6 \"f.va\" 2\n`__LINE__\n");
    }

    test "§10.2 `default_discipline Syntax 10-1" {
        try expectPp("\n\n\n", "`default_discipline\n`default_discipline electrical\n`default_discipline electrical wire\n");
        // fixture ch10 45: a discipline name is not one of the fifteen qualifiers.
        try expectFail("`default_discipline electrical electrical\n", .E0127);
        try expectFail("`default_discipline electrical wire junk\n", .E0127);
    }

    test "§10.3 `default_transition Syntax 10-2" {
        // The published §10.3 events for `src`, which is the whole surface §4.5.8
        // consumes: the value, and the output offset it takes effect from.
        const T = struct {
            fn ev(src: []const u8) ![]const DefaultTransition {
                var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
                defer arena_state.deinit();
                var bag: diag.Bag = .init(arena_state.allocator());
                const out = (try process(arena_state.allocator(), src, .{
                    .std_defs = false,
                    .bag = &bag,
                })).directives.transitions;
                return testing.allocator.dupe(DefaultTransition, out);
            }
        };

        const one = try T.ev("`default_transition 4n\n");
        defer testing.allocator.free(one);
        try testing.expectEqual(@as(usize, 1), one.len);
        try testing.expectEqual(@as(f64, 4e-9), one[0].value.?);

        // §10.3's supersession sentence: both are published, in text order, so the
        // consumer can pick "the directive which immediately precedes" a call
        // rather than being handed one latched value.
        const two = try T.ev("`default_transition 8n\n`default_transition 4n\n");
        defer testing.allocator.free(two);
        try testing.expectEqual(@as(usize, 2), two.len);
        try testing.expectEqual(@as(f64, 8e-9), two[0].value.?);
        try testing.expectEqual(@as(f64, 4e-9), two[1].value.?);
        try testing.expect(two[0].at < two[1].at);

        // Every §2.6.2 spelling of the same time, since the operand is read in a
        // text stage and not by the number lexer proper.
        for ([_][]const u8{ "4n\n", "4e-9\n", "0.000000004\n", "4_000p\n" }) |t| {
            const src = try testing.allocator.print("`default_transition {s}", .{t});
            defer testing.allocator.free(src);
            const e = try T.ev(src);
            defer testing.allocator.free(e);
            try testing.expectEqual(@as(f64, 4e-9), e[0].value.?);
        }

        // IEEE 1364 §19.6: `resetall returns the directive to its default, which
        // §10.3 leaves to the simulator: a null event after the 4n.
        const reset = try T.ev("`default_transition 4n\n`resetall\n");
        defer testing.allocator.free(reset);
        try testing.expectEqual(@as(usize, 2), reset.len);
        try testing.expectEqual(@as(?f64, null), reset[1].value);

        // fixture ch10 48: the operand is not bracketed in Syntax 10-2, so it is
        // mandatory, and the bare form is not a request for the simulator default.
        try expectFail("`default_transition\n", .E0129);
        try expectFail("`default_transition    \n", .E0129);
        try expectFail("`default_transition electrical\n", .E0129);
        try expectFail("`default_transition -4n\n", .E0129);
        try expectFail("`default_transition 4n junk\n", .E0129);
    }

    test "`include resolves the built-in annex D files" {
        // fixture ch10 18_include_constants
        const got = try runTest("`include \"constants.vams\"\n`P_CELSIUS0 `P_K\n");
        defer testing.allocator.free(got);
        try testing.expect(std.mem.find(u8, got, "273.15") != null);
        try testing.expect(std.mem.find(u8, got, "1.3806503e-23") != null);
        try expectFail("`include \"no_such_file.vams\"\n", .E0126);
        try expectFail("`include nonsense\n", .E0122);
        try expectFail("`include <constants.vams>\n", .E0122);

        // annex D.3 is shipped too, and is not preloaded: it has to be asked for.
        const d3 = try runTest("`include \"driver_access.vams\"\n`DRIVER_WAND\n");
        defer testing.allocator.free(d3);
        try testing.expect(std.mem.find(u8, d3, "32'b10000000000") != null);
    }

    test "IEEE 1364 §19.5 `include opens a full path name as written" {
        // A path is machine-specific, so no fixture can spell one; the file is
        // written here, and no include dir is given to join it onto.
        const io = testing.io;
        var tmp = testing.tmpDir(.{});
        defer tmp.cleanup();
        try tmp.dir.writeFile(io, .{ .sub_path = "abs.vh", .data = "`define ABS_OK 7\n" });
        const abs = try tmp.dir.realPathFileAlloc(io, "abs.vh", testing.allocator);
        defer testing.allocator.free(abs);
        const src = try testing.allocator.print("`include \"{s}\"\n`ABS_OK\n", .{abs});
        defer testing.allocator.free(src);
        const got = try runTest(src);
        defer testing.allocator.free(got);
        try testing.expect(std.mem.find(u8, got, "7") != null);
    }

    test "§10.4 the NAME may be escaped and the TEXT may not begin with __VAMS_" {
        // Syntax 10-3: text_macro_identifier ::= identifier, and A.9.3 makes that
        // simple OR escaped. §2.8.1 drops the `\` and the terminating white space,
        // so the definition and the use key on the same bytes.
        try expectPp("\n3.0 *v", "`define \\MY-GAIN 3.0\n`\\MY-GAIN *v");
        // An escaped name can only be object-like, and that falls out of the two
        // rules rather than being a restriction of its own: §2.8.1 ends the name at
        // the first white space, while §10.4 requires the formal list's `(` to
        // touch the name, so `\SQ!(x)` is one nine-character name, not a call.
        try expectPp("\n1", "`define \\SQ!(x) 1\n`\\SQ!(x)");
        // §10.4: the macro text shall not begin with __VAMS_ ...
        try expectFail("`define MY_ENABLE __VAMS_ENABLE__\n", .E0139);
        // ... and the name is unrestricted, which is the other half of the pair.
        try expectPp("\n7.0", "`define __VAMS_USER 7.0\n`__VAMS_USER");
    }

    test "annex D prelude is deterministic and self-guarded" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const src = "`include \"disciplines.vams\"\nmodule m; endmodule\n";
        // One bag per run: the compilation unit must be the first file registered.
        var bag1: diag.Bag = .init(arena);
        var bag2: diag.Bag = .init(arena);
        const out_a = try process(arena, src, .{ .bag = &bag1 });
        const out_b = try process(arena, src, .{ .bag = &bag2 });
        const a = out_a.text;
        const b = out_b.text;
        try testing.expectEqualStrings(a, b);

        // annex D.1 reached the output exactly once, annex D.2 defined its macros.
        try testing.expectEqual(
            @as(usize, 1),
            std.mem.count(u8, a, "discipline electrical;"),
        );
        // The replayed prelude is the snapshot's text, byte for byte.
        const n1 = (try Preprocessor.preludeSnapshot()).text.len;
        try testing.expect(std.mem.find(u8, a[0..n1], "nature Voltage;") != null);
        // The re-`include collapses to just the newlines it consumed (line numbers
        // inside an included file are preserved even when its guard empties it).
        try testing.expectEqualStrings(
            "module m; endmodule\n",
            std.mem.trimStart(u8, a[n1..], "\n"),
        );
    }

    // The snapshot's correctness condition: replaying it must leave `Pp` in the
    // state `runStdDefs` leaves it in. Compares everything `Prelude` carries, so a
    // prelude write `Prelude` does not capture fails here.
    test "the prelude snapshot replays exactly what running annex D.2/D.1/E.1 produces" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // Same starting state `process` and `buildPrelude` both establish.
        var bag: diag.Bag = .init(arena);
        var pp: Pp = .{ .arena = arena, .scratch = arena, .opts = .{ .bag = &bag } };
        _ = try bag.addFile("<source>", "");
        for (predefined_macros) |name| {
            try pp.macros.put(arena, name, .{ .body = "1", .predefined = true });
        }
        try pp.runStdDefs();

        const p = try Preprocessor.preludeSnapshot();
        try testing.expectEqualStrings(pp.out.items, p.text);
        try testing.expectEqual(pp.segs.items.len, p.segs.len);
        for (pp.segs.items, p.segs) |a, b| {
            try testing.expectEqual(a.out_start, b.out_start);
            try testing.expectEqual(a.in_start, b.in_start);
            try testing.expectEqual(a.file, b.file);
        }
        // The macro sets agree, both ways. The difference is exactly §10.5's
        // predefined set, which the snapshot deliberately does not carry. Taken
        // from the array rather than written as a number, so adding one is not a
        // test edit.
        try testing.expectEqual(pp.macros.count(), p.macros.len + predefined_macros.len);
        for (p.macros) |d| {
            const live = pp.macros.get(d.name) orelse return error.MissingMacro;
            try testing.expectEqualStrings(live.body, d.macro.body);
            try testing.expectEqual(live.is_func, d.macro.is_func);
            try testing.expectEqual(live.params.len, d.macro.params.len);
        }
        // And the three file registrations the segments index by position, their
        // strip marks included, or a replayed file renders columns differently
        // from a freshly run one.
        for (p.files, 1..) |f, id| {
            try testing.expectEqualStrings(f.name, bag.fileName(@fromBackingInt(@intCast(id))));
            try testing.expectEqualStrings(f.stripped, bag.fileText(@fromBackingInt(@intCast(id))));
            try testing.expectEqualSlices(diag.StripMark, f.marks, bag.fileMarks(@fromBackingInt(@intCast(id))));
        }
    }

    // The token snapshot's correctness condition: lexing the whole text from
    // offset 0, with no snapshot, matches the seeded result token for token.
    // Two inputs, because with an annex E.2 netlist the prelude is followed by
    // synthesized modules and the seed must still cover only the std-defs prefix.
    test "the prelude token snapshot lexes exactly what lexing the whole text produces" {
        const cases = [_][]const u8{ "", ".MODEL nn npn\n.SUBCKT amp in out\nR1 in out 1k\n.ENDS\n" };
        for (cases) |netlist| {
            var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
            defer arena_state.deinit();
            const arena = arena_state.allocator();

            var bag: diag.Bag = .init(arena);
            const text = (try process(arena,
                \\module res(p, n);
                \\  inout p, n;
                \\  electrical p, n;
                \\  parameter real r = 1000.0 from (0.0:inf);
                \\  analog I(p, n) <+ V(p, n) / r;
                \\endmodule
            , .{ .bag = &bag, .spice_netlist = netlist })).text;

            // The long way: no seed, one scan of the whole buffer.
            const long = try Lexer.Lexer.tokenize(arena, text);
            const seeded = try Lexer.Lexer.tokenizeSeeded(arena, text, try Preprocessor.preludeTokens(true));

            try testing.expectEqual(long.len, seeded.len);
            try testing.expectEqualSlices(token.Tag, long.items(.tag), seeded.items(.tag));
            try testing.expectEqualSlices(u32, long.items(.start), seeded.items(.start));

            // The premise the seam rests on, checked rather than asserted in prose:
            // the snapshot's bytes are a prefix of the text, at offset 0.
            const p = try Preprocessor.preludeSnapshot();
            try testing.expect(std.mem.startsWith(u8, text, p.text));
            // ...and the snapshot stops one token short of `.eof`, which belongs to
            // whatever buffer is actually being lexed.
            try testing.expect(p.tags.len != 0 and p.tags[p.tags.len - 1] != .eof);
        }
    }

    test "`--no-std-defs` gets no seed, and lexes the same either way" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const text = (try process(arena, "module m; endmodule\n", .{ .std_defs = false, .bag = &bag })).text;

        try testing.expectEqual(@as(?Lexer.Lexer.Seed, null), try Preprocessor.preludeTokens(false));
        try testing.expectEqual(@as(?*const Parser.Parser.Seed, null), try Preprocessor.preludeAst(false));
        const long = try Lexer.Lexer.tokenize(arena, text);
        const seeded = try Lexer.Lexer.tokenizeSeeded(arena, text, try Preprocessor.preludeTokens(false));
        try testing.expectEqualSlices(token.Tag, long.items(.tag), seeded.items(.tag));
        try testing.expectEqualSlices(u32, long.items(.start), seeded.items(.start));
    }

    /// Expects `a` and `b` to be structurally equal, by reflection so a new AST
    /// field is compared without a test edit. `[]u8` compares by content: the
    /// snapshot's names and a fresh parse's borrow different copies of the text.
    fn expectDeepEqual(comptime T: type, a: T, b: T) !void {
        switch (@typeInfo(T)) {
            .pointer => |p| {
                if (p.size == .one) return expectDeepEqual(p.child, a.*, b.*);
                comptime std.debug.assert(p.size == .slice);
                if (p.child == u8) return testing.expectEqualStrings(a, b);
                try testing.expectEqual(a.len, b.len);
                for (a, b) |x, y| try expectDeepEqual(p.child, x, y);
            },
            .@"struct" => |s| inline for (s.field_names, s.field_types) |name, F| {
                try expectDeepEqual(F, @field(a, name), @field(b, name));
            },
            .@"union" => |u| {
                const Tag = u.tag_type.?;
                try testing.expectEqual(@as(Tag, a), @as(Tag, b));
                inline for (u.field_names, u.field_types) |name, F| {
                    if (@as(Tag, a) == @field(Tag, name))
                        try expectDeepEqual(F, @field(a, name), @field(b, name));
                }
            },
            .optional => |o| {
                try testing.expectEqual(a == null, b == null);
                if (a) |x| try expectDeepEqual(o.child, x, b.?);
            },
            else => try testing.expectEqual(a, b),
        }
    }

    // The AST snapshot's correctness condition. The determinism test cannot grade
    // it, since both of its runs take the cached path. So this parses the whole
    // text from token 0 with no seed and compares against the seeded parse in
    // full: the interner (contents, ids, map), every `ExprStore` column, the
    // statement pool, all four declaration arrays, and the parser state outside
    // `SourceFile` (`access_names`, `pos`, `gen_construct`). Two inputs, as for
    // the token test.
    test "the prelude AST snapshot parses exactly what parsing the whole text produces" {
        const cases = [_][]const u8{ "", ".MODEL nn npn\n.SUBCKT amp in out\nR1 in out 1k\n.ENDS\n" };
        for (cases) |netlist| {
            var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
            defer arena_state.deinit();
            const arena = arena_state.allocator();

            var bag: diag.Bag = .init(arena);
            const text = (try process(arena,
                \\nature Pressure;
                \\  units = "Pa"; access = Pr; abstol = 1e-6;
                \\endnature
                \\discipline fluid; potential Pressure; enddiscipline
                \\module res(p, n);
                \\  inout p, n;
                \\  electrical p, n;
                \\  parameter real r = 1000.0 from (0.0:inf);
                \\  real acc[0:2];
                \\  analog begin : body
                \\    integer k;
                \\    for (k = 0; k < 3; k = k + 1) acc[k] = k * 2.0;
                \\    I(p, n) <+ V(p, n) / r + acc[1];
                \\  end
                \\endmodule
            , .{ .bag = &bag, .spice_netlist = netlist })).text;

            var toks = try Lexer.Lexer.tokenize(arena, text);
            const tags = toks.items(.tag);
            const starts = toks.items(.start);

            // The long way: no seed, one parse of every token from 0.
            var lbag: diag.Bag = .init(arena);
            var lp = Parser.Parser.init(arena, text, tags, starts, &lbag);
            const long = try lp.parseSourceFile();

            var sbag: diag.Bag = .init(arena);
            const seed = (try Preprocessor.preludeAst(true)).?;
            var sp = try Parser.Parser.initSeeded(arena, text, tags, starts, &sbag, seed);
            // The seed is doing something: the resumed parse starts deep in the file.
            try testing.expect(sp.pos > 2000 and sp.pos < tags.len - 1);
            const seeded = try sp.parseSourceFile();

            // --- the interner: same strings, at the same ids, and the same map ---
            try testing.expectEqual(long.strings.strings.items.len, seeded.strings.strings.items.len);
            try testing.expectEqual(long.strings.map.size, seeded.strings.map.size);
            for (long.strings.strings.items, seeded.strings.strings.items, 0..) |x, y, i| {
                try testing.expectEqualStrings(x, y);
                // The id is the claim, not just the membership: everything below the
                // parser addresses a name by its `StrId`.
                const id = seeded.strings.find(y) orelse return error.NameNotInMap;
                try testing.expectEqual(i, @backingInt(id));
            }

            // --- the expression store: every column of every row, and the three
            // side tables the rows index ---
            try testing.expectEqual(long.exprs.nodes.len, seeded.exprs.nodes.len);
            for (0..long.exprs.nodes.len) |i| {
                try expectDeepEqual(
                    @TypeOf(long.exprs.nodes.get(0)),
                    long.exprs.nodes.get(i),
                    seeded.exprs.nodes.get(i),
                );
            }
            try testing.expectEqualSlices(u32, long.exprs.pool.items, seeded.exprs.pool.items);
            try testing.expectEqualSlices(f64, long.exprs.reals.items, seeded.exprs.reals.items);
            try testing.expectEqualDeep(long.exprs.ints.items, seeded.exprs.ints.items);

            // --- statements ---
            try testing.expectEqualSlices(u32, long.stmt_toks.items, seeded.stmt_toks.items);
            try expectDeepEqual(@TypeOf(long.stmts.items), long.stmts.items, seeded.stmts.items);
            try expectDeepEqual(@TypeOf(long.attributes.items), long.attributes.items, seeded.attributes.items);

            // --- all four declaration arrays, to their leaves ---
            try expectDeepEqual(@TypeOf(long.modules), long.modules, seeded.modules);
            try expectDeepEqual(@TypeOf(long.disciplines), long.disciplines, seeded.disciplines);
            try expectDeepEqual(@TypeOf(long.natures), long.natures, seeded.natures);
            try expectDeepEqual(@TypeOf(long.paramsets), long.paramsets, seeded.paramsets);

            // --- the parser state that is not in the SourceFile ---
            // A dropped access name turns a §4.4.1 branch probe into a §4.7 function
            // call silently, so the set is compared both ways.
            try testing.expectEqual(lp.access_names.size, sp.access_names.size);
            var it = lp.access_names.keyIterator();
            while (it.next()) |k| try testing.expect(sp.access_names.contains(k.*));
            try testing.expectEqual(lp.pos, sp.pos);
            try testing.expectEqual(lp.gen_construct, sp.gen_construct);
            try testing.expectEqual(lp.failed, sp.failed);
            try testing.expectEqual(@as(usize, 0), lbag.count() + sbag.count());
        }
    }

    test "an ABSTOL override reaches annex D.1" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        var bag: diag.Bag = .init(arena_state.allocator());
        const text = (try process(
            arena_state.allocator(),
            "`define CURRENT_ABSTOL 1e-15\n`include \"disciplines.vams\"\n",
            .{ .std_defs = false, .bag = &bag },
        )).text;
        try testing.expect(std.mem.find(u8, text, "abstol      = 1e-15;") != null);
        try testing.expect(std.mem.find(u8, text, "abstol      = 1e-12;") == null);
    }

    test "a span inside an `include resolves to the included file's own line" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        var bag: diag.Bag = .init(arena);
        const src = "module m;\n`include \"disciplines.vams\"\nendmodule\n";
        const out = (try process(arena, src, .{ .std_defs = false, .bag = &bag })).text;

        // A byte that came from the included file.
        const needle = "discipline electrical;";
        const at: u32 = @intCast(std.mem.find(u8, out, needle).?);
        const r = bag.map.resolve(at);
        try testing.expectEqualStrings("disciplines.vams", bag.fileName(r.file));
        try testing.expect(r.file != .root);

        // ... at its line number, not one measured in the preprocessed text.
        const want = std.mem.countScalar(
            u8,
            Preprocessor.disciplines_vams[0..std.mem.find(u8, Preprocessor.disciplines_vams, needle).?],
            '\n',
        ) + 1;
        const idx = try diag.LineIndex.build(arena, bag.fileText(r.file));
        try testing.expectEqual(@as(u32, @intCast(want)), idx.loc(r.offset).line);
        try testing.expectEqualStrings(
            needle,
            bag.fileText(r.file)[r.offset..][0..needle.len],
        );

        // ... while the top-level file still resolves to itself, at line 1.
        const top = bag.map.resolve(@intCast(std.mem.find(u8, out, "module m;").?));
        try testing.expectEqual(diag.FileId.root, top.file);
        try testing.expectEqual(@as(u32, 0), top.offset);
        // ... and so does what follows the `include, despite the splice.
        const after = bag.map.resolve(@intCast(std.mem.find(u8, out, "endmodule").?));
        try testing.expectEqual(diag.FileId.root, after.file);
        try testing.expectEqualStrings("endmodule\n", src[after.offset..]);
    }

    test "a diagnostic after a comment renders the ORIGINAL line at the ORIGINAL column" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);

        // The error token sits after a block comment on its line. Its span indexes
        // the stripped text (the '`' is at stripped column 3); the strip marks put
        // the caret on the line the user wrote, at column 25.
        const src = "/* a leading comment */ `NOPE\n";
        try testing.expectError(
            error.PreprocessFailed,
            process(arena, src, .{ .std_defs = false, .bag = &bag }),
        );
        try testing.expectEqual(@as(usize, 1), bag.count());
        try testing.expectEqual(diag.Code.E0115, bag.at(0).code);

        var buf: std.ArrayList(u8) = .empty;
        var aw: std.Io.Writer.Allocating = .fromArrayList(arena, &buf);
        defer buf = aw.toArrayList();
        try diag.render(&bag, &aw.writer, .{ .explain_hint = false, .summary = false });
        const out = aw.writer.buffered();

        // The line drawn is the user's, comment included ...
        try testing.expect(std.mem.find(u8, out, "| /* a leading comment */ `NOPE") != null);
        // ... the column is measured in it: the '`' is byte 24, column 25 ...
        try testing.expect(std.mem.find(u8, out, ":1:25") != null);
        // ... and the caret row is indented to match: 24 spaces, then the span.
        try testing.expect(std.mem.find(u8, out, "|                         ^^^^^") != null);
    }

    test "a span inside a macro expansion resolves to the invocation site" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        var bag: diag.Bag = .init(arena);
        const src = "`define SQ(x) ((x)*(x))\ny = `SQ(v) + 1;\n";
        const out = (try process(arena, src, .{ .std_defs = false, .bag = &bag })).text;

        // Bytes that exist only in the expansion have no counterpart in the file;
        // the honest answer is the `SQ that produced them.
        const inside: u32 = @intCast(std.mem.findScalar(u8, out, '*').?);
        const r = bag.map.resolve(inside);
        try testing.expectEqual(diag.FileId.root, r.file);
        try testing.expect(std.mem.startsWith(u8, src[r.offset..], "`SQ(v)"));
        try testing.expectEqualStrings("SQ", bag.map.segs[r.seg].macro);

        // ... and the text after the expansion is verbatim again.
        const after = bag.map.resolve(@intCast(std.mem.find(u8, out, "+ 1").?));
        try testing.expectEqualStrings("+ 1;\n", src[after.offset..]);
    }

    test "IEEE 1364 §19.3.1: an escaped-identifier actual keeps its terminator" {
        // §2.8.1: white space ends an escaped identifier. `macroArgs` trims the
        // actual, so substitution puts one space back after it.
        try expectPreserved("`define ID(A) (A)\n`ID(\\a.b )\n", &.{"(\\a.b )"}, &.{});
        // A string's escape sequence is not an escaped identifier.
        try expectPreserved("`define ID(A) (A)\n`ID(\"x\\n\")\n", &.{"(\"x\\n\")"}, &.{});
    }

    test "§2.9 attribute owners survive a seeded parse and later attribute lists" {
        var state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer state.deinit();
        const arena = state.allocator();
        const prefix = "(* module_attr = 3 *) module first; (* item_attr *) integer x; endmodule\n";
        const source = prefix ++ "(* module_attr = 4 *) module second; analog (* stmt_attr *) begin end endmodule\n";
        var pt = try Lexer.Lexer.tokenize(arena, prefix);
        var pb: diag.Bag = .init(arena);
        var pp = Parser.Parser.init(arena, prefix, pt.items(.tag), pt.items(.start), &pb);
        const seed: Parser.Parser.Seed = .{
            .file = try pp.parseSourceFile(),
            .access_names = &.{},
            .pos = pp.pos,
            .gen_construct = pp.gen_construct,
        };
        var tokens = try Lexer.Lexer.tokenize(arena, source);
        var sb: diag.Bag = .init(arena);
        var sp = try Parser.Parser.initSeeded(arena, source, tokens.items(.tag), tokens.items(.start), &sb, &seed);
        const resumed = try sp.parseSourceFile();
        var lb: diag.Bag = .init(arena);
        var lp = Parser.Parser.init(arena, source, tokens.items(.tag), tokens.items(.start), &lb);
        const whole = try lp.parseSourceFile();
        try testing.expect(!pp.failed and !sp.failed and !lp.failed);
        try testing.expect(whole.attributes.items.len > seed.file.attributes.items.len);
        try expectDeepEqual(@TypeOf(whole.attributes.items), whole.attributes.items, resumed.attributes.items);
        try expectDeepEqual(@TypeOf(whole.modules), whole.modules, resumed.modules);
    }

    // ---------------------------------------------------------------------------
    // Unit test plan. Each bug class, the oracle that sees it, and where it runs.
    //
    //   text wrong but plausible (a formal substituted into a string or a number,
    //   a comment surviving, an arm taken that should not be)
    //       -> the expected text derived by hand from the clause (`expectPp`)
    //   line contract broken (output newlines != input newlines)
    //       -> the newline counts compared, on hand cases and on every input of
    //          the snippet generator ("every successful run keeps ...")
    //   provenance corrupt (segments out of order, a span naming the wrong file)
    //       -> segments sorted by `out_start`; every preprocess span inside the
    //          file it names (`expectFail`, `expectSortedMap`)
    //   strip marks wrong (a caret in the wrong column)
    //       -> every kept byte equals the raw byte its mark maps to; stripping a
    //          stripped text changes nothing (seeded property)
    //   a refusal missing or spurious
    //       -> one case per named code, each with a legal neighbour
    //   a limit off by one (E0119, E0125)
    //       -> the case at the limit and the case one past it
    //   vector scan differs from scalar -> the scalar loop (differential, above)
    //   region lookup wrong -> a forward scan, exhaustive over small lists
    //   allocation failure swallowed or leaked -> `checkAllAllocationFailures`
    //
    // The generators are seeded `DefaultPrng` loops, so `zig build test` runs
    // them in full and a failure replays.
    // ---------------------------------------------------------------------------

    /// Expects the source map's segments in `out_start` order, which
    /// `SourceMap.resolve`'s binary search requires.
    fn expectSortedMap(bag: *const diag.Bag) !void {
        const segs = bag.map.segs;
        for (segs[0..segs.len -| 1], segs[@min(1, segs.len)..]) |a, b| {
            try testing.expect(a.out_start <= b.out_start);
        }
    }

    /// Expects every published event list in text-stream order and inside `text`.
    fn expectSortedEvents(d: Preprocessor.Directives, text: []const u8) !void {
        inline for (@typeInfo(Preprocessor.Directives).@"struct".field_names) |name| {
            const list = @field(d, name);
            for (list, 0..) |e, k| {
                try testing.expect(e.at <= text.len);
                if (k > 0) try testing.expect(list[k - 1].at <= e.at);
            }
        }
    }

    /// The `timescale in force at the end of `src`, preprocessed without the prelude.
    fn timescaleOf(src: []const u8) !?Timescale {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        var bag: diag.Bag = .init(arena_state.allocator());
        return (try process(arena_state.allocator(), src, .{ .std_defs = false, .bag = &bag })).directives.timescale();
    }

    test "§2.4 comment corners: end of file, `/*/`, and markers inside opaque tokens" {
        // A `//` comment may end the file.
        try expectPp("a", "a// x");
        // `/*/` opens a comment and does not close it: the `*` a close needs is
        // the opener's own (§2.4: "begin with /* and end with */").
        try expectFail("/*/", .E0102);
        // The shortest block comment is four bytes and leaves its separator (§2.2).
        try expectPp("a b", "a/**/b");
        // §2.8.1: an escaped identifier runs to white space, so a `//` inside one
        // is part of the name.
        try expectPp("\\a//b c", "\\a//b c");
        // §2.7: an escaped quote does not end a string, so the `//` after it is
        // still inside the literal.
        try expectPp("\"a\\\"//b\"", "\"a\\\"//b\"");
        // A `//` comment runs to the LF, so the CR of a CRLF line goes with it.
        try expectPp("a\nb", "a//c\r\nb");
        // An unterminated string ends at its line (the lexer reports it), and the
        // comment on the next line is still stripped.
        try expectPp("\"abc\n\nx", "\"abc\n// c\nx");
        // IEEE 1364 §19.3.1: a `//` comment in macro text is dropped, but the `\`
        // ending it still continues the macro. Outside a `define the `\` goes with
        // the comment.
        try expectPp("\n\na b\n", "`define M a // c \\\n  b\n`M\n");
        try expectPp("\n\n\na b\n", "`define M \\\n  a // c \\\n  b\n`M\n");
        try expectPp("a \nb", "a // c \\\nb");
    }

    test "stripComments: every kept byte maps back to itself, and stripping twice changes nothing" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // By hand first. `ab/*c*/d`: the comment becomes one space at stripped
        // offset 2, and from stripped offset 3 the texts run in lockstep with the
        // raw text from offset 7, which is one mark. `x//c\ny`: the line comment
        // leaves nothing, and stripped 1 (the LF) is raw 4.
        {
            var bag: diag.Bag = .init(arena);
            var pp: Pp = .{ .arena = arena, .scratch = arena, .opts = .{ .bag = &bag } };
            _ = try bag.addFile("<source>", "ab/*c*/d");
            const s = try Preprocessor.stripComments(&pp, "ab/*c*/d");
            try testing.expectEqualStrings("ab d", s.text);
            try testing.expectEqualSlices(diag.StripMark, &.{.{ .out = 3, .src = 7 }}, s.marks);
            const l = try Preprocessor.stripComments(&pp, "x//c\ny");
            try testing.expectEqualStrings("x\ny", l.text);
            try testing.expectEqualSlices(diag.StripMark, &.{.{ .out = 1, .src = 4 }}, l.marks);
        }

        // Then every short text over the bytes the stripper branches on.
        var prng: std.Random.DefaultPrng = .init(0xc0ffee);
        const rand = prng.random();
        const alphabet = "a /*\n\"\\";
        var buf: [48]u8 = undefined;
        for (0..4000) |_| {
            const raw = buf[0..rand.uintAtMost(usize, buf.len)];
            for (raw) |*b| b.* = alphabet[rand.uintLessThan(usize, alphabet.len)];

            var bag: diag.Bag = .init(arena);
            var pp: Pp = .{ .arena = arena, .scratch = arena, .opts = .{ .bag = &bag } };
            const id = try bag.addFile("<source>", raw);
            const s = Preprocessor.stripComments(&pp, raw) catch |e| switch (e) {
                error.PreprocessFailed => continue, // E0102, an unclosed `/*`
                error.OutOfMemory => return e,
            };
            bag.setStrippedText(id, s.text, s.marks);

            // §2.4 keeps a comment's newlines, and nothing grows.
            try testing.expectEqual(std.mem.countScalar(u8, raw, '\n'), std.mem.countScalar(u8, s.text, '\n'));
            try testing.expect(s.text.len <= raw.len);
            // A comment's replacement is a space or newlines; every other byte is a
            // verbatim copy, found where the marks say.
            for (s.text, 0..) |c, k| {
                if (c == ' ' or c == '\n') continue;
                try testing.expectEqual(c, raw[bag.toSourceOffset(id, @intCast(k))]);
            }
            // No comment survives, and none is made: a kept `/` was not followed by
            // `/` or `*` (it would have opened a comment), and a replacement is
            // white space.
            var bag2: diag.Bag = .init(arena);
            var pp2: Pp = .{ .arena = arena, .scratch = arena, .opts = .{ .bag = &bag2 } };
            _ = try bag2.addFile("<source>", s.text);
            const again = try Preprocessor.stripComments(&pp2, s.text);
            try testing.expectEqualStrings(s.text, again.text);
            try testing.expectEqual(@as(usize, 0), again.marks.len);
        }
    }

    test "§2.7 strings and §2.8.1 escaped identifiers are opaque to the scan" {
        // A live unterminated string is the lexer's to report; the preprocessor
        // passes it through.
        try expectPp("\"abc\nx", "\"abc\nx");
        // A backtick inside either is not a macro use.
        try expectPp("\"`NOPE\" \\a`b c", "\"`NOPE\" \\a`b c");
        // IEEE 1364 §19.4: an ignored group still follows the lexical rules, so an
        // unterminated string inside one is E0138 ...
        try expectFail("`ifdef N\n\"abc\n`endif\n", .E0138);
        // ... and a string continued with `\`+newline is one token, whose newline
        // the dead arm keeps.
        try expectPreserved("`ifdef N\n\"a\\\nb\"\n`endif\n", &.{}, &.{ "a", "b" });
    }

    test "a grave accent needs a name, except inside an inactive arm" {
        try expectFail("`\n", .E0103);
        try expectFail("` x\n", .E0103);
        // A backslash with no body is no escaped name either (§2.8.1).
        try expectFail("`\\ x\n", .E0103);
        try expectPp("\n\n\n", "`ifdef N\n` x\n`endif\n");
    }

    test "IEEE 1364 §19.4: the first true arm wins, a dead parent kills every arm, and text may follow the operand" {
        try expectPreserved("`define A\n`define B\n`ifdef A\na\n`elsif B\nb\n`else\nc\n`endif\n", &.{"a"}, &.{ "b", "c" });
        try expectPreserved("`ifdef N\n`ifdef M\nx\n`else\ny\n`endif\n`endif\n", &.{}, &.{ "x", "y" });
        try expectPreserved("`ifdef N\n`elsif N\nx\n`elsif __VERA__\ny\n`endif\n", &.{"y"}, &.{"x"});
        // Syntax 19-5 ends a conditional directive with its operand; the rest of
        // the line is source in the arm it opens.
        try expectPp("\n x\n\n", "`define A\n`ifdef A x\n`endif\n");
        // `else takes no operand, so the rest of its line is source.
        try expectPreserved("`ifdef N\n`else junk\n`endif\n", &.{"junk"}, &.{});
        try expectFail("`else\n", .E0105);
        try expectFail("`elsif A\n", .E0105);
        try expectFail("`ifdef A\n`elsif\n`endif\n", .E0107);
        try expectFail("`ifdef A\n`else\n`elsif B\n`endif\n", .E0106);
        try expectFail("`ifndef\n", .E0104);
        // A `define in a dead arm defines nothing.
        try expectPreserved("`ifdef N\n`define X\n`endif\n`ifdef X\nyes\n`endif\n", &.{}, &.{"yes"});
    }

    test "E0101 points at the end of the file and labels the `ifdef it leaves open" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const src = "x\n`ifdef A\ny\n";
        try testing.expectError(error.PreprocessFailed, process(arena, src, .{ .std_defs = false, .bag = &bag }));
        const e = bag.at(0);
        try testing.expectEqual(diag.Code.E0101, e.code);
        try testing.expectEqual(@as(u32, src.len), e.span.start);
        var buf: [diag.max_children]diag.Label = undefined;
        const labels = bag.labels(e, &buf);
        try testing.expectEqual(@as(usize, 1), labels.len);
        try testing.expectEqualStrings("`ifdef", src[labels[0].span.start..labels[0].span.end]);
    }

    test "two directives with no text between them publish at one offset, and the later is in force" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const r = try regionsOf(arena_state.allocator(), "`celldefine`endcelldefine\n");
        try testing.expectEqual(@as(usize, 2), r.cells.len);
        try testing.expectEqual(r.cells[0].at, r.cells[1].at);
        try testing.expect(!CellRegion.inForce(r.cells, r.cells[0].at, false));
    }

    test "§10.4 definitions: redefinition, empty text, empty lists and the formal list's grammar" {
        // §10.4: a redefinition replaces.
        try expectPp("\n\n2", "`define A 1\n`define A 2\n`A");
        try expectPp("\n[]", "`define E\n[`E]");
        // `Z()` has a formal list with nothing in it: `Z()` uses it, `Z` and
        // `Z(1)` do not.
        try expectPp("\nz", "`define Z() z\n`Z()");
        try expectFail("`define Z() z\n`Z\n", .E0116);
        try expectFail("`define Z() z\n`Z(1)\n", .E0117);
        // One formal, one empty actual.
        try expectPp("\n[]", "`define I(x) [x]\n`I()");
        // Syntax 10-3's list_of_formal_arguments, one code per way to break it.
        try expectFail("`define M(\n", .E0110);
        try expectFail("`define M(1) x\n", .E0110);
        try expectFail("`define M(a\n", .E0111);
        try expectFail("`define M(a b) x\n", .E0112);
        // formal_argument_identifier is a simple_identifier, whose first character
        // is not `$` (§2.8), and `{ , formal_argument_identifier }` needs a formal
        // after every comma.
        try expectFail("`define M($x) $x\n", .E0110);
        try expectFail("`define M(a,) a\n", .E0110);
        try expectFail("`define M(,a) a\n", .E0110);
        // The text continues across `\`+newline as one space, the continuation's
        // indentation and a CR before the newline included.
        try expectPp("\n\na b", "`define P a \\\n   b\n`P");
        try expectPp("\n\na b", "`define P a\\\r\nb\n`P");
        // `undef of a name never defined is not an error: §10.4 sets no rule.
        try expectPp("\nx", "`undef NOPE\nx");
        try expectFail("`undef\n", .E0113);
        try expectFail("`define\n", .E0109);
    }

    test "IEEE 1364 §19.3.1 substitution: what a formal is not" {
        // The name after a '`' is a macro use, never a formal.
        try expectPp("\n\n9", "`define x 9\n`define M(x) `x\n`M(1)");
        // A number is one token, so its exponent letter is no formal.
        try expectPp("\n1e-3+2", "`define M(e) 1e-3+e\n`M(2)");
        // A comma or parenthesis inside a string actual does not split it.
        try expectPp("\n\"a,b)\"|c", "`define A(p,q) p|q\n`A(\"a,b)\", c)");
        // A directive in macro text runs when the text is rescanned.
        try expectPp("\n\n7\n", "`define D `define X 7\n`D\n`X\n");
    }

    test "IEEE 1364 §19.3.1: an actual that spans lines keeps the output's line count" {
        // The invocation re-emits the newlines of its whole span after the
        // expansion, so a newline inside an actual is white space between tokens
        // (a space), or it would be emitted twice.
        try expectPp("\n[a +b]\n\nz\n", "`define M(x) [x]\n`M(a\n+b)\nz\n");
        // The same through a nested use, whose span is inside the outer one's.
        try expectPp("\n\n[1+2]\n\n", "`define N(a,b) a+b\n`define M(x) [x]\n`M(`N(1,\n2))\n");
    }

    test "§10.7 `__LINE__ in macro text and arguments is the invocation's line, `__FILE__ a string literal" {
        try expectPp("\n\n3\n", "`define L `__LINE__\n\n`L\n");
        try expectPp("\n2\n\n", "`define I(x) x\n`I(\n`__LINE__)\n");
        // Neither name is in the macro table, so `undef changes nothing.
        try expectPp("\n2", "`undef __LINE__\n`__LINE__");
        // §2.7 escapes the two bytes a file name may hold that a string literal
        // cannot hold bare.
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const out = try process(arena, "`__FILE__", .{ .std_defs = false, .bag = &bag, .file_name = "a\"b\\c.va" });
        try testing.expectEqualStrings("\"a\\\"b\\\\c.va\"", out.text);
    }

    test "IEEE 1364 §19.7: only white space shares a `line directive's line" {
        // "However, only white space may appear on the same line as the `line
        // directive. Comments are not allowed on the same line as a `line
        // directive." Legal: indentation before it, comments on the lines around.
        try expectPp("  \n3\n", "  `line 3 \"f\" 0\n`__LINE__\n");
        try expectPp("\n\n3\n", "// c\n`line 3 \"f\" 0\n`__LINE__\n");
        try expectPp("\n\n\n3\n", "/* a\n b */\n`line 3 \"f\" 0\n`__LINE__\n");
        // Refused: a comment that ends where the line starts, one that opens
        // after the level and runs on, and other text before the directive.
        try expectFail("/* a\n*/`line 3 \"f\" 0\n", .E0128);
        try expectFail("`line 3 \"f\" 0 /* a\nb */\n", .E0128);
        try expectFail("x `line 3 \"f\" 0\n", .E0128);
        // The number is a positive integer that fits, and the name is closed.
        try expectFail("`line 4294967296 \"f\" 0\n", .E0128);
        try expectFail("`line 3 \"f 0\n", .E0128);
    }

    test "IEEE 1364 §19.5 `include operand errors, and the annex D files by basename" {
        try expectFail("`include\n", .E0121);
        try expectFail("`include \"abc\n", .E0123);
        try expectFail("`include \"\"\n", .E0124);
        // VD-091: a built-in is found by its basename wherever the name points.
        const got = try runTest("`include \"no/such/dir/constants.vams\"\n`M_PI\n");
        defer testing.allocator.free(got);
        try testing.expect(std.mem.find(u8, got, "3.14159265358979323846") != null);

        // VD-096: only annex D.1, under either name, is the source asking for
        // annex D's natures.
        const cases = [_]struct { name: []const u8, d1: bool }{
            .{ .name = "disciplines.vams", .d1 = true },
            .{ .name = "discipline.h", .d1 = true },
            .{ .name = "constants.vams", .d1 = false },
            .{ .name = "constants.h", .d1 = false },
        };
        for (cases) |c| {
            var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
            defer arena_state.deinit();
            const arena = arena_state.allocator();
            var bag: diag.Bag = .init(arena);
            const src = try arena.print("`include \"{s}\"\n", .{c.name});
            const out = try process(arena, src, .{ .std_defs = false, .bag = &bag });
            try testing.expectEqual(c.d1, out.annex_d_included);
        }
    }

    test "IEEE 1364 §19.5: include nesting is unbounded; only a repeating cycle is E0125" {
        // A chain of 40 files (past the old cap of 32), each including the
        // next; then one file including itself under a guard that defines one
        // more macro each time, 301 deep, which a cap on the path alone would
        // call a cycle; then a file including itself unchanged, the one nesting
        // that never ends.
        const io = testing.io;
        var tmp = testing.tmpDir(.{});
        defer tmp.cleanup();
        var name_buf: [16]u8 = undefined;
        var data_buf: [32]u8 = undefined;
        const chain = 40;
        for (0..chain) |k| {
            const name = try std.mem.print(&name_buf, "a{d}.vh", .{k});
            const data = if (k + 1 == chain) "deepest\n" else try std.mem.print(&data_buf, "`include \"a{d}.vh\"\n", .{k + 1});
            try tmp.dir.writeFile(io, .{ .sub_path = name, .data = data });
        }
        var guard: std.ArrayList(u8) = .empty;
        defer guard.deinit(testing.allocator);
        const depth = 300;
        for (0..depth) |k| try guard.print(testing.allocator, "`ifndef L{d}\n`define L{d}\n`else\n", .{ k, k });
        try guard.appendSlice(testing.allocator, "bottom\n`define DONE\n");
        for (0..depth) |_| try guard.appendSlice(testing.allocator, "`endif\n");
        try guard.appendSlice(testing.allocator, "`ifndef DONE\n`include \"self.vh\"\n`endif\n");
        try tmp.dir.writeFile(io, .{ .sub_path = "self.vh", .data = guard.items });
        try tmp.dir.writeFile(io, .{ .sub_path = "loop.vh", .data = "x\n`include \"loop.vh\"\n" });
        try tmp.dir.writeFile(io, .{ .sub_path = "p.vh", .data = "`include \"q.vh\"\n" });
        try tmp.dir.writeFile(io, .{ .sub_path = "q.vh", .data = "`include \"p.vh\"\n" });
        const first = try tmp.dir.realPathFileAlloc(io, "a0.vh", testing.allocator);
        defer testing.allocator.free(first);
        const dirs: []const []const u8 = &.{std.fs.path.dirname(first).?};

        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var ok_bag: diag.Bag = .init(arena);
        const out = try process(arena, "`include \"a0.vh\"\n", .{ .std_defs = false, .bag = &ok_bag, .include_dirs = dirs });
        try testing.expect(std.mem.find(u8, out.text, "deepest") != null);
        var self_bag: diag.Bag = .init(arena);
        const self_out = try process(arena, "`include \"self.vh\"\n", .{ .std_defs = false, .bag = &self_bag, .include_dirs = dirs });
        try testing.expectEqual(@as(usize, 1), std.mem.count(u8, self_out.text, "bottom"));

        for ([_][]const u8{ "loop.vh", "p.vh" }) |f| {
            var bag: diag.Bag = .init(arena);
            const src = try arena.print("`include \"{s}\"\n", .{f});
            try testing.expectError(error.PreprocessFailed, process(arena, src, .{ .std_defs = false, .bag = &bag, .include_dirs = dirs }));
            try testing.expectEqual(@as(usize, 1), bag.count());
            try testing.expectEqual(diag.Code.E0125, bag.at(0).code);
        }
    }

    test "IEEE 1364 §19.5: an `include past the u32 text bound is E1013, known from the file's size" {
        // A sparse file one byte past `max_text_bytes`: its size is read, not
        // its bytes, so the test allocates nothing large. NTFS would allocate
        // the 4 GiB, so Windows skips it.
        if (@import("builtin").os.tag == .windows) return error.SkipZigTest; // os: a test skip; every target builds it
        const io = testing.io;
        var tmp = testing.tmpDir(.{});
        defer tmp.cleanup();
        {
            var f = try tmp.dir.createFile(io, "huge.vh", .{});
            defer f.close(io);
            try f.setLength(io, Preprocessor.max_text_bytes + 1);
        }
        try tmp.dir.writeFile(io, .{ .sub_path = "big.vh", .data = "" });
        const any = try tmp.dir.realPathFileAlloc(io, "big.vh", testing.allocator);
        defer testing.allocator.free(any);
        const dirs: []const []const u8 = &.{std.fs.path.dirname(any).?};
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        var bag: diag.Bag = .init(arena_state.allocator());
        try testing.expectError(error.PreprocessFailed, process(arena_state.allocator(), "`include \"huge.vh\"\n", .{ .std_defs = false, .bag = &bag, .include_dirs = dirs }));
        try testing.expectEqual(diag.Code.E1013, bag.at(0).code);
        // 17 MiB, past the old 16 MiB `include cap, reads.
        {
            var f = try tmp.dir.createFile(io, "big.vh", .{});
            defer f.close(io);
            try f.setLength(io, 17 << 20);
        }
        var ok_bag: diag.Bag = .init(arena_state.allocator());
        const out = try process(arena_state.allocator(), "`include \"big.vh\"\n", .{ .std_defs = false, .bag = &ok_bag, .include_dirs = dirs });
        try testing.expect(out.text.len >= 17 << 20);
    }

    test "§10.7: a file included through a macro numbers its own lines and owns its diagnostics" {
        const io = testing.io;
        var tmp = testing.tmpDir(.{});
        defer tmp.cleanup();
        try tmp.dir.writeFile(io, .{ .sub_path = "lines.vh", .data = "`define FROM_INC 5\n\n`__LINE__\n" });
        try tmp.dir.writeFile(io, .{ .sub_path = "bad.vh", .data = "\n\n`NOPE\n" });
        try tmp.dir.writeFile(io, .{ .sub_path = "word.vh", .data = "wire_from_inc\n" });
        const any = try tmp.dir.realPathFileAlloc(io, "lines.vh", testing.allocator);
        defer testing.allocator.free(any);
        const dirs: []const []const u8 = &.{std.fs.path.dirname(any).?};

        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        // "An `include directive changes the expansions of `__FILE__ and `__LINE__
        // to correspond to the included file": the `__LINE__ on line 3 of
        // lines.vh is 3, wherever the `include was written.
        {
            var bag: diag.Bag = .init(arena);
            const out = try process(arena, "`define INC `include \"lines.vh\"\n`INC\n`FROM_INC\n", .{ .std_defs = false, .bag = &bag, .include_dirs = dirs });
            try testing.expectEqualStrings("\n\n\n3\n\n5\n", out.text);
            try expectSortedMap(&bag);
        }
        // A diagnostic raised inside that file is in that file, on its own line.
        {
            var bag: diag.Bag = .init(arena);
            try testing.expectError(error.PreprocessFailed, process(arena, "`define INC `include \"bad.vh\"\n`INC\n", .{ .std_defs = false, .bag = &bag, .include_dirs = dirs }));
            const e = bag.at(0);
            try testing.expectEqual(diag.Code.E0115, e.code);
            try testing.expectEqualStrings("bad.vh", std.fs.path.basename(bag.fileName(e.file.?)));
            const text = bag.fileText(e.file.?);
            try testing.expect(e.span.end <= text.len);
            try testing.expectEqualStrings("`NOPE", text[e.span.start..e.span.end]);
        }
        // Through an actual, the included text is part of the expansion: it maps
        // to the invocation like every other expanded byte, and the map stays
        // sorted.
        {
            var bag: diag.Bag = .init(arena);
            const src = "`define INC `include \"word.vh\"\n`define ID(x) x\n`ID(`INC) tail\n";
            const out = try process(arena, src, .{ .std_defs = false, .bag = &bag, .include_dirs = dirs });
            try expectSortedMap(&bag);
            const r = bag.map.resolve(@intCast(std.mem.find(u8, out.text, "wire_from_inc").?));
            try testing.expectEqual(diag.FileId.root, r.file);
            try testing.expect(std.mem.startsWith(u8, src[r.offset..], "`ID("));
            const tail = bag.map.resolve(@intCast(std.mem.find(u8, out.text, "tail").?));
            try testing.expectEqualStrings("tail\n", src[tail.offset..]);
        }
    }

    test "every successful run keeps the line count and leaves sorted provenance" {
        // Swarm-style: random sequences of whole-line snippets. Sequences that
        // break a rule (an `else with no `ifdef, an unclosed string actual) fail
        // with a diagnostic and are skipped. Every one that succeeds must give the
        // output exactly the newlines of the files it read (the unit and each
        // `include, a re-read one again) and publish sorted segments and events.
        const snippets = [_][]const u8{
            "`define A 1\n",
            "`define F(x) [x]\n",
            "`define G(y) `F(y)\n",
            "`define B \\\n 2\n",
            "`A\n",
            "`B\n",
            "`F(a)\n",
            "`F(a\nb)\n",
            "`G(b\nc)\n",
            "`F(`A\n)\n",
            "`F(`F(\nz))\n",
            "`F(\"s\n",
            "/* c\n */\n",
            "// c\n",
            "x y\n",
            "\"s\"\n",
            "`ifdef A\n",
            "`ifndef A\n",
            "`else\n",
            "`endif\n",
            "`undef A\n",
            "`timescale 1ns/1ps\n",
            "`celldefine\n",
            "`endcelldefine\n",
            "`default_nettype none\n",
            "`resetall\n",
            "`__LINE__\n",
            "`include \"constants.vams\"\n",
        };
        var prng: std.Random.DefaultPrng = .init(0x11e5);
        const rand = prng.random();
        var src: std.ArrayList(u8) = .empty;
        defer src.deinit(testing.allocator);
        for (0..3000) |_| {
            src.clearRetainingCapacity();
            for (0..rand.uintAtMost(usize, 12)) |_| {
                try src.appendSlice(testing.allocator, snippets[rand.uintLessThan(usize, snippets.len)]);
            }
            var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
            defer arena_state.deinit();
            const arena = arena_state.allocator();
            var bag: diag.Bag = .init(arena);
            const out = process(arena, src.items, .{ .std_defs = false, .bag = &bag }) catch |e| switch (e) {
                error.PreprocessFailed => continue,
                error.OutOfMemory => return e,
            };
            var want: usize = 0;
            for (bag.files.items) |f| want += std.mem.countScalar(u8, f.text, '\n');
            try testing.expectEqual(want, std.mem.countScalar(u8, out.text, '\n'));
            try expectSortedMap(&bag);
            try expectSortedEvents(out.directives, out.text);
        }
    }

    test "IEEE 1364 §19.3.1: every directive name is refused as a macro name, escaped or not" {
        // §2.8.1: `\include` is the identifier `include`.
        for (Preprocessor.directive_map.keys()) |name| {
            for ([_][]const u8{ "", "\\" }) |prefix| {
                const src = try testing.allocator.print("`define {s}{s} 1\n", .{ prefix, name });
                defer testing.allocator.free(src);
                try expectFail(src, .E0143);
            }
        }
    }

    test "IEEE 1364 §19.8 Table 19-1: every magnitude and unit reads back as its exact decimal" {
        // The oracle is the literal `1e<n>` read by `std.fmt.parseFloat`, which
        // rounds correctly; the code under test reads a table instead.
        const mags = [_]struct { text: []const u8, exp: i32 }{
            .{ .text = "1", .exp = 0 },
            .{ .text = "10", .exp = 1 },
            .{ .text = "100", .exp = 2 },
        };
        const units = [_]struct { text: []const u8, exp: i32 }{
            .{ .text = "s", .exp = 0 },
            .{ .text = "ms", .exp = -3 },
            .{ .text = "us", .exp = -6 },
            .{ .text = "ns", .exp = -9 },
            .{ .text = "ps", .exp = -12 },
            .{ .text = "fs", .exp = -15 },
        };
        var buf: [16]u8 = undefined;
        for (mags) |m| {
            for (units) |u| {
                const want = try std.fmt.parseFloat(f64, try std.mem.print(&buf, "1e{d}", .{m.exp + u.exp}));
                // 1 fs is the finest precision, so it is never coarser than the unit.
                const src = try testing.allocator.print("`timescale {s}{s}/1fs\n", .{ m.text, u.text });
                defer testing.allocator.free(src);
                const t = (try timescaleOf(src)).?;
                try testing.expectEqual(want, t.unit);
                try testing.expectEqual(@as(f64, 1e-15), t.precision);
            }
        }
        // Equal unit and precision is "at least as precise".
        try testing.expectEqual(@as(f64, 1e-9), (try timescaleOf("`timescale 1ns/1ns\n")).?.precision);
        // A leading zero is not on the grid.
        try expectFail("`timescale 01ns/1ps\n", .E0142);
    }

    test "E0142's notes cite IEEE 1364-2005 §19.8, the `timescale clause" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        for ([_][]const u8{ "`timescale 2ns/1ps\n", "`timescale 1ps/1ns\n" }) |src| {
            var bag: diag.Bag = .init(arena);
            try testing.expectError(error.PreprocessFailed, process(arena, src, .{ .std_defs = false, .bag = &bag }));
            var buf: [diag.max_children]diag.Note = undefined;
            const notes = bag.notes(bag.at(0), &buf);
            try testing.expect(notes.len != 0);
            try testing.expect(std.mem.find(u8, notes[0].text, "§19.8") != null);
            for (notes) |n| try testing.expect(std.mem.find(u8, n.text, "§19.9") == null);
        }
    }

    test "§10.2 `default_discipline publishes its name and qualifier, and `resetall withdraws it" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const d = (try process(arena, "`default_discipline \\logic wreal\n`default_discipline\n`resetall\n", .{
            .std_defs = false,
            .bag = &bag,
        })).directives.disciplines;
        try testing.expectEqual(@as(usize, 3), d.len);
        try testing.expectEqualStrings("logic", d[0].discipline);
        try testing.expectEqual(@as(?Qualifier, .wreal), d[0].qualifier);
        try testing.expectEqualStrings("", d[1].discipline);
        try testing.expectEqual(@as(?Qualifier, null), d[1].qualifier);
        try testing.expectEqualStrings("", d[2].discipline);
        // Each at the output offset where its directive's text ended: the two
        // collapsed lines leave one newline each before the next.
        try testing.expectEqual(@as(u32, 0), d[0].at);
        try testing.expectEqual(@as(u32, 1), d[1].at);
        try testing.expectEqual(@as(u32, 2), d[2].at);
    }

    test "IEEE 1364 §19.6: `resetall writes one default event to every list" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const out = try process(arena, "`resetall\n", .{ .std_defs = false, .bag = &bag });
        // The word itself is passed through for the parser (§19.6 refuses it
        // inside a module).
        try testing.expectEqualStrings("`resetall\n", out.text);
        const d = out.directives;
        inline for (@typeInfo(Preprocessor.Directives).@"struct".field_names) |name| {
            try testing.expectEqual(@as(usize, 1), @field(d, name).len);
        }
        try testing.expectEqual(NetType.wire, d.nettypes[0].value);
        try testing.expect(!d.cells[0].value);
        try testing.expectEqual(Drive.float, d.drives[0].value);
        try testing.expectEqual(@as(?f64, null), d.transitions[0].value);
        try testing.expectEqual(@as(?Timescale, null), d.timescales[0].value);
        try testing.expectEqualStrings("", d.disciplines[0].discipline);
    }

    test "§10.3: zero is a transition time, infinity and NaN are not" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const t = (try process(arena, "`default_transition 0\n", .{ .std_defs = false, .bag = &bag })).directives.transitions;
        try testing.expectEqual(@as(?f64, 0.0), t[0].value);
        try expectFail("`default_transition 1e400\n", .E0129);
        try expectFail("`default_transition inf\n", .E0129);
        try expectFail("`default_transition nan\n", .E0129);
        // §2.6: the operand is one Verilog number. `std.fmt.parseFloat` also
        // reads C's hex floats and a point with no digit after it (§2.6.2 wants
        // one on each side), and drops a leading `_` (§2.6.1 forbids it first).
        for ([_][]const u8{ "0x10", "1.", ".5", "_1", "1e", "-", "4n4" }) |op| {
            const src = try testing.allocator.print("`default_transition {s}\n", .{op});
            defer testing.allocator.free(src);
            try expectFail(src, .E0129);
        }
        // A sign is a unary operator on the number, so `+4n` is a time.
        const plus = (try process(arena, "`default_transition +4n\n", .{ .std_defs = false, .bag = &bag })).directives.transitions;
        try testing.expectEqual(@as(?f64, 4e-9), plus[0].value);
    }

    test "IEEE 1364-2005 §13.4.1: files given together are one text stream" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        // A macro and an open `ifdef cross into the next file, `__FILE__ names
        // that file, and a newline keeps `a` and `2` two tokens.
        const out = try process(arena, "`define W 2\n`ifdef W\na", .{
            .std_defs = false,
            .bag = &bag,
            .more = &.{.{ .name = "b.v", .text = "`W `__FILE__\n`endif\n" }},
        });
        try testing.expectEqualStrings("\n\na\n2 \"b.v\"\n\n", out.text);
        try testing.expectEqualSlices(u32, &.{4}, out.more_starts);
    }

    test "E0115 suggests the nearest defined macro, backtick restored" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        const src = "`define GAIN 1\n`GAN\n";
        try testing.expectError(error.PreprocessFailed, process(arena, src, .{ .std_defs = false, .bag = &bag }));
        var buf: [diag.max_children]diag.Note = undefined;
        const notes = bag.notes(bag.at(0), &buf);
        try testing.expectEqual(@as(usize, 1), notes.len);
        const fix = notes[0].fix.?;
        try testing.expectEqualStrings("`GAIN", fix.replacement);
        try testing.expectEqualStrings("`GAN", src[fix.span.start..fix.span.end]);
    }

    /// Preprocesses `src` with every allocation on `gpa`, for
    /// `checkAllAllocationFailures`.
    fn preprocessAll(gpa: Allocator, src: []const u8) !void {
        var arena_state: std.heap.ArenaAllocator = .init(gpa);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        _ = try process(arena, src, .{ .std_defs = false, .bag = &bag });
    }

    test "process reports every allocation failure as OutOfMemory and leaks nothing" {
        // One source through every allocating path: a function-like macro with a
        // pre-expanded actual, a built-in `include, a conditional, two event
        // lists, a comment's strip mark, `__LINE__ and `__FILE__.
        try testing.checkAllAllocationFailures(testing.allocator, preprocessAll, .{
            "`define F(x) [x]\n`include \"constants.vams\"\n`ifdef M_PI\n`F(`M_PI)\n`endif\n" ++
                "`timescale 1ns/1ps\n`default_discipline electrical\n/* c */ `__LINE__ `__FILE__\n",
        });
    }

    test "isIdentStart admits exactly §2.8's letters, `_`, and `$`" {
        for (0..256) |c| {
            const b: u8 = @intCast(c);
            const want = (b >= 'a' and b <= 'z') or (b >= 'A' and b <= 'Z') or b == '_' or b == '$';
            try testing.expectEqual(want, Preprocessor.isIdentStart(b));
        }
    }

    test "stringStop ends at the closing quote, an unescaped newline, or the end" {
        const cases = [_]struct { text: []const u8, want: usize }{
            .{ .text = "\"ab\"x", .want = 3 },
            .{ .text = "\"a\\\"b\"", .want = 5 },
            .{ .text = "\"ab\ncd\"", .want = 3 },
            .{ .text = "\"ab", .want = 3 },
            .{ .text = "\"a\\", .want = 3 },
            .{ .text = "\"a\\\nb\"", .want = 5 },
        };
        for (cases) |c| try testing.expectEqual(c.want, Preprocessor.stringStop(c.text, 0));

        // Oracle: the per-byte loop `stringStop` replaced, on random text dense in
        // the three bytes it branches on, from the empty body past three vectors.
        const scalar = struct {
            fn stop(text: []const u8, start: usize) usize {
                var i = start + 1;
                while (i < text.len and text[i] != '"' and text[i] != '\n') {
                    if (text[i] == '\\' and i + 1 < text.len) i += 1;
                    i += 1;
                }
                return i;
            }
        }.stop;
        var prng: std.Random.DefaultPrng = .init(0x57a1);
        const rand = prng.random();
        var buf: [200]u8 = undefined;
        for (1..buf.len + 1) |len| {
            for (0..32) |_| {
                for (buf[0..len]) |*b| b.* = switch (rand.uintLessThan(u8, 40)) {
                    0 => '"',
                    1, 2 => '\\',
                    3 => '\n',
                    else => 'a',
                };
                for (0..@min(len, 4)) |start| {
                    buf[start] = '"';
                    try testing.expectEqual(scalar(buf[0..len], start), Preprocessor.stringStop(buf[0..len], start));
                }
            }
        }
    }

    test "Rest reads identifiers and escaped identifiers where the lexer splits them" {
        var r: Preprocessor.Rest = .{ .s = "  a$1_ \\b-c d" };
        try testing.expectEqualStrings("a$1_", r.ident().?);
        // A backslash starts no simple identifier, and a letter no escaped one.
        try testing.expect(r.ident() == null);
        try testing.expectEqualStrings("b-c", r.escapedIdent().?);
        try testing.expect(r.escapedIdent() == null);
        try testing.expectEqualStrings("d", r.ident().?);
        try testing.expect(r.peek() == null);
    }

    test "joinChain spells an include or expansion chain" {
        var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        var bag: diag.Bag = .init(arena);
        var pp: Pp = .{ .arena = arena, .scratch = arena, .opts = .{ .bag = &bag } };
        try testing.expectEqualStrings("A -> B -> C", try pp.joinChain(&.{ "A", "B" }, "C"));
        try testing.expectEqualStrings("C", try pp.joinChain(&.{}, "C"));
    }
};

pub const sim_digital_tests = struct {
    //! Corner cases of the interpreter files no single sibling's tests reach:
    //! §4.8.2 conversions at the i32/i64 edges, §17 byte-packing at word
    //! boundaries, a run's arena under repeated timing-check conditions, and
    //! allocation failure through the system tasks. No LRM clause of its own:
    //! each test cites the clause it checks.
    const std = @import("std");
    const diag = @import("diag");
    const root = @import("sim").digital;
    const system = root.system;
    const filled = root.for_emitter.net.filled;
    const expectRun = root.expectRun;

    test "§17.8 $rtoi takes -2^31 exactly and refuses one past it as x" {
        try expectRun(
            \\module m; integer i, j, k;
            \\initial begin i = $rtoi(-2147483648.0); j = $rtoi(-2147483648.9); k = $rtoi(-2147483649.0);
            \\$display("%0d %0d %b", i, j, k); end endmodule
        , "-2147483648 -2147483648 xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\n");
    }

    test "§4.8.2 a real rounds into a 64-bit integer down to -2^63, and NaN is x" {
        try expectRun(
            \\module m; reg signed [63:0] a, b; real n;
            \\initial begin a = -9223372036854775808.0; n = 0.0 / 0.0; b = n;
            \\$display("%0d %b", a, b[0]); end endmodule
        , "-9223372036854775808 x\n");
    }

    test "§17.1.1.7 text reads bytes across a word boundary, top byte partial" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        // 76 bits: a partial top byte 0x5 (bits 72..75), then 9 bytes, the
        // eighth of which (bits 56..63) ends word 0.
        const v = try filled(a, 76, false, .zero);
        v.values()[0] = 0x4847_4645_4443_4241;
        v.values()[1] = 0x549;
        try std.testing.expectEqualStrings("\x05IHGFEDCBA", (try system.text(a, v)).?);
    }

    test "§17.2.3 a string longer than a word packs into the value and reads back" {
        try expectRun(
            \\module m; reg [8*12:1] s;
            \\initial begin $sformat(s, "%s", "abcdefghijkl"); $display("%s|%h", s, s[72:65]); end endmodule
        , "abcdefghijkl|64\n");
    }

    test "§17.2.4.4 readWord spans words big-endian and drops bits above the width" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const a = arena.allocator();
        const File = struct {
            var data: []const u8 = "";
            var pos: usize = 0;
            fn getc(_: i64) i64 {
                if (pos == data.len) return -1;
                pos += 1;
                return data[pos - 1];
            }
            fn none(_: i64) i64 {
                return 0;
            }
        };
        const io: @import("contract").FileIo = .{ .open = undefined, .close = File.none, .put = undefined, .getc = File.getc, .ungetc = undefined, .tell = File.none, .seek = undefined, .eof = File.none };
        // 70 bits = 9 bytes, 0xff first: only its low 6 bits survive.
        File.data = "\xff\x01\x02\x03\x04\x05\x06\x07\x08";
        File.pos = 0;
        const w = try system.readWord(a, io, 1, 70);
        try std.testing.expectEqual(@as(i64, 9), w.n);
        try std.testing.expectEqual(@as(u64, 0x0102030405060708), w.value.?.values()[0]);
        try std.testing.expectEqual(@as(u64, 0x3f), w.value.?.values()[1]);
        try std.testing.expectEqual(@as(u64, 0), w.value.?.unknowns()[1]);
    }

    test "§15.6 a conditioned timing check judged every tick stops growing the run arena" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        var bag = diag.Bag.init(arena.allocator());
        var output = std.Io.Writer.Allocating.init(arena.allocator());
        var r = try root.elaborate(arena.allocator(),
            \\`timescale 1ns/1ns
            \\module c(clk, en); input clk, en; reg n;
            \\specify $period(posedge clk &&& en, 1, n); endspecify endmodule
            \\module t; reg clk, en; c u(clk, en);
            \\initial begin clk = 0; en = 1; end always #1 clk = ~clk; endmodule
        , .{}, &bag, &output.writer);
        var at_warm: usize = 0;
        for (1..2001) |k| {
            _ = try r.runUntil(k);
            if (k == 200) at_warm = arena.queryCapacity();
        }
        try std.testing.expectEqual(at_warm, arena.queryCapacity());
    }

    test "§5.2.1 an indexed part-select descending from a base below the vector" {
        // v[1 -: 4] of [7:0] selects bits 1 down to -2: 1 and 0 exist, -1 and
        // -2 do not (x), and a write there lands only in bits 1 and 0.
        try expectRun(
            \\module m; reg [7:0] v;
            \\initial begin v = 8'b0000_0010; $display("%b", v[1 -: 4]); v[1 -: 4] = 4'b0111; $display("%b", v); end endmodule
        , "10xx\n00000001\n");
    }

    fn runSystemTasks(gpa: std.mem.Allocator) !void {
        var arena = std.heap.ArenaAllocator.init(gpa);
        defer arena.deinit();
        var bag = diag.Bag.init(arena.allocator());
        var output = std.Io.Writer.Allocating.init(arena.allocator());
        try root.run(arena.allocator(),
            \\module m; reg [8*10:1] s; integer n, a, st, j, i; real r;
            \\initial begin
            \\  $sformat(s, "%0d-%h", 12, 8'hab); n = $sscanf("7 2.5", "%d %f", a, r);
            \\  $q_initialize(1, 1, 2, st); $q_add(1, 3, 4, st); $q_remove(1, j, i, st);
            \\  $display("%s %0d %0d %g %0d %0d %0d", s, n, a, r, st, j, i);
            \\end endmodule
        , .{}, &bag, &output.writer);
        try std.testing.expectEqualStrings("12-ab 2 7 2.5 0 3 4\n", output.written());
    }

    test "allocation failure anywhere in $sformat, $sscanf, the queues and $display cleans up" {
        try std.testing.checkAllAllocationFailures(std.testing.allocator, runSystemTasks, .{});
    }

    test "§12.7 one expression read from two instances resolves per scope through the slot memo" {
        // `v` in `c` is one ExprId seen from two scopes; a memo keyed on the
        // expression alone would print 1 twice.
        try expectRun(
            \\module c; parameter P = 0; reg [3:0] v; initial begin v = P; #1 $display("%0d %0d", v, t.b.v); end endmodule
            \\module t; c #(1) a(); c #(2) b(); endmodule
        , "1 2\n2 2\n");
    }
};

pub const codegen_tests = struct {
    //! Codegen self-checks: a small Verilog-A source in, device.zig text out,
    //! asserted by shape; the fixture suite checks behaviour. Also runs the
    //! device-runtime kernels directly.
    //! LRM §3.4, §4.5, §4.6, §5.4.3, §5.6, §9.4, §9.5, §9.13, §9.17.3, §9.21.

    const std = @import("std");
    const codegen = @import("device").codegen;
    const gen_kernel_text = codegen.kernel_text;
    const Harness = codegen.Harness;
    const Ast = @import("frontend").Ast;
    const Preprocessor = @import("frontend").Preprocessor;
    const Lexer = @import("frontend").Lexer;
    const Parser = @import("frontend").Parser;
    const ifconv = @import("prove").ifconv;
    const Mir = @import("ir").Mir;
    const Lower = @import("analog").Lower;
    const Lowered = @import("ir").Lowered;
    const proof = @import("prove").proof;
    const diag = @import("diag");
    const assert = std.debug.assert;
    const Output = codegen.Output;
    const generate = codegen.generate;

    // ---------------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------------

    test "codegen: an unused integer remainder keeps its artifact-specific zero check" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module m(p, n);
            \\  inout p, n; electrical p, n;
            \\  integer d, unused;
            \\  analog begin
            \\    d = V(p,n);
            \\    unused = 11 % d;
            \\    I(p,n) <+ V(p,n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const device = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, device, "zm_b == 0) { @trap();") != null);
        try std.testing.expect(std.mem.find(u8, device, "error[E0601]") == null);
        const executable = try h.genDisplay(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, executable, "error[E0601]") != null);
        try std.testing.expect(std.mem.find(u8, executable, "std.process.exit(1)") != null);
    }

    test "codegen: a discarded remainder inside a display argument stays in the display phase" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module m(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog function integer f;
            \\    input d; integer d, unused;
            \\    begin unused = 11 % d; f = 7; end
            \\  endfunction
            \\  analog begin
            \\    $strobe("%d", f($rtoi(V(p,n))));
            \\    I(p,n) <+ V(p,n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        try std.testing.expectEqual(Mir.Value.f_zero, h.lowered.table_effect);
        const device = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, device, "fn zm_f") == null);
        const executable = try h.genDisplay(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, executable, "error[E0601]") != null);
    }

    const resistor_va =
        \\module res(p, n);
        \\  inout p, n;
        \\  electrical p, n;
        \\  parameter real r = 1000.0 from (0:inf);
        \\  analog I(p, n) <+ V(p, n) / r;
        \\endmodule
    ;

    test "codegen: --jac-f32 adds a permission decl and changes not one other byte" {
        // `eval` reaches S only through primitives that take and return f64
        // (`con`, `scale`, `addC`, `val`), so the derivative width inside S is the
        // host's choice and no emitted arithmetic depends on it. Any other byte
        // the flag moves means that genericity broke.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h);
        defer h.deinit();

        const v = try proof.proveOpts(std.testing.allocator, &h.mir, &h.lowered, .{}, &h.bag);
        defer v.deinit(std.testing.allocator);
        var fatal = false;
        const a = h.arena_state.allocator();
        const off = (try generate(a, a, &h.mir, &h.lowered, v, &fatal, .{})).text;
        const on = (try generate(a, a, &h.mir, &h.lowered, v, &fatal, .{ .jac_f32 = true })).text;

        try std.testing.expect(std.mem.find(u8, off, "jac_f32") == null);
        const decl = "pub const jac_f32 = true;\n\n";
        const at = std.mem.find(u8, on, decl) orelse return error.NoPermissionDecl;
        // Excise the block the flag added (comment header included) and what is
        // left has to be the default output byte for byte.
        const hdr = std.mem.findLast(u8, on[0..at], "/// This device permits").?;
        const stripped = try std.mem.concat(a, u8, &.{ on[0..hdr], on[at + decl.len ..] });
        try std.testing.expectEqualStrings(off, stripped);

        // `--jac-f32-host` is the stronger request and emits the permission too:
        // a host width without the permission is the one combination
        // `lib/contract.zig` rejects, so codegen must never produce it.
        const host = (try generate(a, a, &h.mir, &h.lowered, v, &fatal, .{ .jac_f32_host = true })).text;
        try std.testing.expect(std.mem.find(u8, host, decl) != null);
        try std.testing.expect(std.mem.find(u8, host, "pub const jac_f32_host = true;") != null);
    }

    test "codegen: the family text types each merge by its unknowns" {
        // a = 0, c = 1, b = 2: the `if` merges exp(V(a,c)), lanes {a, c}, with
        // V(b), lane {b}, so the slot both arms write and the field are 0x7.
        const src =
            \\module d(a, c, b);
            \\  inout a, c, b;
            \\  electrical a, c, b;
            \\  real i;
            \\  analog begin
            \\    if (V(a, c) > 0.5) i = exp(V(a, c)); else i = V(b);
            \\    I(a, c) <+ i;
            \\  end
            \\endmodule
        ;
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator, src, &h);
        defer h.deinit();
        const v = try proof.proveOpts(std.testing.allocator, &h.mir, &h.lowered, .{}, &h.bag);
        defer v.deinit(std.testing.allocator);
        var fatal = false;
        const a = h.arena_state.allocator();
        const on = (try generate(a, a, &h.mir, &h.lowered, v, &fatal, .{})).text;
        for ([_][]const u8{
            "fn d__common__core(comptime S: type, x: anytype, ",
            "    f0: zOf(S, 0x7),\n",
            "    var h0: [1]zOf(S, 0x7) = undefined;\n",
            "h0[0] = zTo(S, 0x7, x[@intFromEnum(U.b)]);",
            "        .f0 = zTo(S, 0x7, t",
            "res[@intFromEnum(U.a)] = zRow(S, .a, res[@intFromEnum(U.a)].add(c));",
            "pub fn eval(comptime S: type, x: *const [n_u]S.V, model: *const Model, inst: InstancePtr, sim: contract.SimState) contract.Rows(Self, S) {",
            "pub const lane_masks = [_]contract.LaneUse{",
            "    .{ .mask = 0x7, .uses = ",
        }) |s| if (std.mem.find(u8, on, s) == null) {
            std.debug.print("missing from the family text: {s}\n", .{s});
            return error.TestExpectedEqual;
        };
    }

    test "codegen: a core reads time and analysis from its SimState argument, and names it only then" {
        // The resistor's core reads none of it, so its `sim` is discarded.
        {
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator, resistor_va, &h);
            defer h.deinit();
            const src = try h.gen(std.testing.allocator);
            try std.testing.expect(std.mem.find(u8, src, ", _  : contract.SimState) struct {") != null);
            try std.testing.expect(std.mem.find(u8, src, "core_reads_simstate") == null);
        }
        {
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator,
                \\module ak(p, n);
                \\  inout p, n;
                \\  electrical p, n;
                \\  analog I(p, n) <+ V(p, n) * (analysis("tran") ? 2.0 : 1.0) + 1e-3 * V(p, n) * $abstime;
                \\endmodule
            , &h);
            defer h.deinit();
            const src = try h.gen(std.testing.allocator);
            try std.testing.expect(std.mem.find(u8, src, "InstancePtr, sim: contract.SimState) struct {") != null);
            try std.testing.expect(std.mem.find(u8, src, "(sim.kind == .tran or sim.kind == .ic)") != null);
            try std.testing.expect(std.mem.find(u8, src, "S.con(sim.t)") != null);
            try std.testing.expect(std.mem.find(u8, src, "analysis_kind") == null);
        }
    }

    test "codegen: `constant` is declared exactly for a Jacobian no x can move" {
        const cases = [_]struct { body: []const u8, want: ?[]const u8 }{
            // V/r with r from the card; a capacitor; an inductor.
            .{ .body = "I(p, n) <+ V(p, n) / r;", .want = ".{ .g = true, .c = false }" },
            .{ .body = "I(p, n) <+ ddt(1e-12 * V(p, n));", .want = ".{ .g = true, .c = true }" },
            .{ .body = "V(p, n) <+ 1e-9 * ddt(I(p, n));", .want = ".{ .g = true, .c = true }" },
            // A partial that moves with x, with time, or with the branch x took.
            .{ .body = "I(p, n) <+ exp(V(p, n));", .want = null },
            .{ .body = "I(p, n) <+ 1e-3 * V(p, n) * $abstime;", .want = null },
            .{ .body = "if (V(p, n) > 0) I(p, n) <+ V(p, n) / r; else I(p, n) <+ 2.0 * V(p, n);", .want = null },
        };
        for (cases) |c| {
            const src = try std.testing.allocator.print(
                \\module k(p, n);
                \\  inout p, n;
                \\  electrical p, n;
                \\  parameter real r = 1000.0 from (0:inf);
                \\  analog {s}
                \\endmodule
            , .{c.body});
            defer std.testing.allocator.free(src);
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator, src, &h);
            defer h.deinit();
            const out = try h.gen(std.testing.allocator);
            const at = std.mem.find(u8, out, "pub const constant: contract.Constant = ");
            if (c.want) |w| {
                try std.testing.expect(std.mem.startsWith(u8, out[at.? + "pub const constant: contract.Constant = ".len ..], w));
            } else try std.testing.expect(at == null);
        }
    }

    test "codegen: State.t_prev exists only for a reader, and state_class is declared" {
        // A constant-td `absdelay` pushes its ring on `sim.t` and never
        // reads `t_prev`; `idtmod` integrates over `dt = abstime - t_prev`. A
        // nonlinear `ddt` lowers to the §5.6.1.2 path latches alone.
        const cases = [_]struct { src: []const u8, t_prev: bool, class: []const u8 }{
            .{ .src =
            \\module d(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog I(p, n) <+ absdelay(V(p, n), 1e-9);
            \\endmodule
            , .t_prev = false, .class = ".history" },
            .{ .src =
            \\module l(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog I(p, n) <+ idtmod(V(p, n), 0.0, 1.0);
            \\endmodule
            , .t_prev = true, .class = ".history" },
            .{ .src =
            \\module c(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog I(p, n) <+ V(p, n) * ddt(V(p, n));
            \\endmodule
            , .t_prev = false, .class = ".path_latch" },
        };
        for (cases) |c| {
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator, c.src, &h);
            defer h.deinit();
            const src = try h.gen(std.testing.allocator);
            try std.testing.expectEqual(c.t_prev, std.mem.find(u8, src, "t_prev: f64") != null);
            try std.testing.expectEqual(c.t_prev, std.mem.find(u8, src, "state.t_prev = sim.t;") != null);
            const decl = try h.arena_state.allocator().print("pub const state_class: contract.StateClass = {s};", .{c.class});
            try std.testing.expect(std.mem.find(u8, src, decl) != null);
        }
    }

    test "codegen: a vera_interp = 2 absdelay site publishes exactly a linear site's state and delays" {
        // The host finds delay state by the `__absdelay__` field infix and sizes
        // its breakpoints from `delays`: the attribute may change the kernel only.
        const srcs = [2][]const u8{
            \\module d(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog I(p, n) <+ absdelay(V(p, n), 1e-9) + absdelay(V(p, n), 2e-9);
            \\endmodule
            ,
            \\module d(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog I(p, n) <+ absdelay(V(p, n), 1e-9) + absdelay (* vera_interp = 2 *) (V(p, n), 2e-9);
            \\endmodule
        };
        var out: [2][]const u8 = undefined;
        var hs: [2]Harness = undefined;
        for (srcs, &out, &hs) |s, *o, *h| {
            try Harness.run(std.testing.allocator, s, h);
            o.* = try h.gen(std.testing.allocator);
        }
        defer for (&hs) |*h| h.deinit();
        try std.testing.expect(std.mem.find(u8, out[0], "zAbsdelayQ(") == null);
        try std.testing.expect(std.mem.find(u8, out[1], "zAbsdelayQ(zL(S,") != null);
        try std.testing.expectEqual(std.mem.count(u8, out[0], "d__analog_op__absdelay__"), std.mem.count(u8, out[1], "d__analog_op__absdelay__"));
        try std.testing.expect(std.mem.find(u8, out[1], "Z24") == null);
        const delays = "pub fn delays(_: *const Model) [2]f64 {\n    return .{ 0.000000001, 0.000000002 };\n}";
        for (out) |o| try std.testing.expect(std.mem.find(u8, o, delays) != null);
    }

    test "codegen: acceptQ is q and updateState off ONE core evaluation" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module c(p, n);
            \\  inout p, n; electrical p, n;
            \\  analog I(p, n) <+ V(p, n) * ddt(V(p, n));
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        const at = std.mem.find(u8, src, "pub fn acceptQ(comptime S: type,") orelse return error.NoAcceptQ;
        const body = src[at..][0 .. std.mem.find(u8, src[at..], "\n}\n") orelse return error.NoEnd];
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, body, "@call(.always_inline, core,"));
        try std.testing.expect(std.mem.find(u8, body, "state.wq__0 = m.f") != null);
        try std.testing.expect(std.mem.find(u8, body, "return qq;") != null);
    }

    test "codegen: §5.10 eval skips a held-array store only updateState reads, and never copies the array" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module hh(p, n);
            \\  inout p, n; electrical p, n;
            \\  real hist[0:3]; integer k, nh;
            \\  analog begin
            \\    @(initial_step) begin
            \\      nh = 0;
            \\      for (k = 0; k < 4; k = k + 1) hist[k] = 0.0;
            \\    end
            \\    I(p, n) <+ V(p, n) * hist[0];
            \\    if (nh < 4) begin
            \\      hist[nh] = V(p, n);
            \\      hist[0] = hist[nh] * 2.0;
            \\      nh = nh + 1;
            \\    end
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "inst: InstancePtr, sim: contract.SimState, comptime held: bool) struct {") != null);
        // The append and the store that reads it back are skippable; the
        // initial-step zeroing is read by the residual in the same evaluation.
        // Both appear twice: in the core, and in `updateState`'s slice of it.
        try std.testing.expectEqual(@as(usize, 4), std.mem.count(u8, src, "if (held) zArrSt("));
        try std.testing.expect(std.mem.find(u8, src, "p0 = &inst.") != null);
        try std.testing.expect(std.mem.find(u8, src, "core, .{ S, xs, model, inst, sim, false })") != null);
        try std.testing.expect(std.mem.find(u8, src, "core__state(S, zVals(S, &x), model, inst, sim, true)") != null);
        // The read-back carries V's derivative, but into nothing eval returns,
        // so the storage stays plain.
        try std.testing.expect(std.mem.find(u8, src, "var a0: [4]f64 = undefined;") != null);
        // `updateState`'s slice stores in place (`state.inPlaceArrays`): a
        // mutable pointer at the field, no copy-in, no array field to return and
        // no write-back.
        try std.testing.expect(std.mem.find(u8, src, "var p0: *[4]f64 = undefined;") != null);
        try std.testing.expect(std.mem.find(u8, src, "if (held) zArrSt(f64, p0, ") != null);
        try std.testing.expect(std.mem.find(u8, src, "inst.hh__held__hist = m.f") == null);
    }

    test "codegen: §5.10 stateCtl copies only the written range of a long in-place held array" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module dr(p, n);
            \\  inout p, n; electrical p, n;
            \\  real hist[0:99], few[0:3]; integer k, nh;
            \\  analog begin
            \\    @(initial_step) begin
            \\      nh = 0;
            \\      for (k = 0; k < 100; k = k + 1) hist[k] = 0.0;
            \\      for (k = 0; k < 4; k = k + 1) few[k] = 0.0;
            \\    end
            \\    I(p, n) <+ V(p, n) * hist[0] + few[1];
            \\    if (nh < 100) begin
            \\      hist[nh] = V(p, n);
            \\      few[nh % 4] = V(p, n);
            \\      nh = nh + 1;
            \\    end
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // The 100-element history carries a range; the 4-element one is copied
        // whole (`file.dirty_min_len`).
        try std.testing.expect(std.mem.find(u8, src, "dr__held__hist__dirty: [2]i64 = .{ 0, 99 },") != null);
        try std.testing.expect(std.mem.find(u8, src, "dr__held__few__dirty") == null);
        try std.testing.expect(std.mem.find(u8, src, "zArrStD(f64, p") != null);
        try std.testing.expect(std.mem.find(u8, src, "zArrSync(f64, &state.dr__held__hist, &inst.dr__held__hist, &inst.dr__held__hist__dirty);") != null);
        try std.testing.expect(std.mem.find(u8, src, "zArrSync(f64, &inst.dr__held__hist, &state.dr__held__hist, &inst.dr__held__hist__dirty);") != null);
        try std.testing.expect(std.mem.find(u8, src, "state.dr__held__few = inst.dr__held__few;") != null);
        // A fresh `State` matches `inst` nowhere in particular: the whole range.
        try std.testing.expect(std.mem.find(u8, src, "    inst.dr__held__hist__dirty = .{ 0, 99 };\n    return .{};") != null);
    }

    test "codegen: §3.2 a memory-backed array starts each evaluation with @memset" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module zf(p, n);
            \\  inout p, n; electrical p, n;
            \\  integer sp;
            \\  (* vera_scratch *) real st[0:31];
            \\  analog begin
            \\    sp = ($abstime < 0.5) ? 1 : 2;
            \\    st[sp] = V(p, n);
            \\    I(p, n) <+ st[sp] + st[sp - 1];
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "@memset(&a") != null);
    }

    test "codegen: one stably-named declaration for the model, thin dispatcher" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        try std.testing.expect(std.mem.find(u8, src, "pub const U = enum(u8) {") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub const num_ports: usize = 2;") != null);
        try std.testing.expect(std.mem.find(u8, src, "r: f64 = 1000.0,") != null);
        // The declaration name is `ir/names.zig`'s structural key, not a MIR index,
        // and there is one per model. The per-contribution keys (`ir/names.zig`,
        // proof.zig, the `Instance` state fields) name no declaration.
        try std.testing.expect(std.mem.find(u8, src, "fn res__common__core(comptime S: type,") != null);
        try std.testing.expect(std.mem.find(u8, src, "return zResidual(S, xs, @call(.always_inline, core, .{ S, xs, model, inst, sim }));") != null);
        try std.testing.expect(std.mem.find(u8, src, "const c = m.f0;") != null);
        try std.testing.expect(std.mem.find(u8, src, "contract.validate(Self)") != null);
        // no reactive part ⇒ no q()
        try std.testing.expect(std.mem.find(u8, src, "pub fn q(") == null);
        // NEVER a global MIR value index in a name
        try std.testing.expect(std.mem.find(u8, src, "v12") == null);
    }

    const shared_va =
        \\module sh(p, n);
        \\  inout p, n;
        \\  electrical p, n, m;
        \\  parameter real r = 1000.0 from (0:inf);
        \\  real g;
        \\  analog begin
        \\    g = exp(V(p, n) / r) * V(p, m);
        \\    I(p, m) <+ g * 2.0;
        \\    I(m, n) <+ g * 3.0;
        \\  end
        \\endmodule
    ;

    test "codegen: two contributions sharing a subexpression evaluate it ONCE" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator, shared_va, &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // One declaration, named structurally, with no MIR index anywhere in it.
        try std.testing.expect(std.mem.find(u8, src, "fn sh__common__core(comptime S: type,") != null);
        // One call for the whole residual, not one per contribution. LLVM does
        // not CSE repeated calls to a body this size (see `plan_core.plan`), so
        // the count is the number of core runs per Newton iteration.
        try std.testing.expectEqual(
            @as(usize, 1),
            std.mem.count(u8, src, "return zResidual(S, xs, @call(.always_inline, core, .{ S, xs, model, inst, sim }));"),
        );
        try std.testing.expect(std.mem.find(u8, src, "const c = m.f0;") != null);
        // The costly `exp` is emitted once. Counted past the file-scope helpers,
        // several of which spell `.exp()` themselves.
        const decls = src[std.mem.find(u8, src, "// ---- the model, in one declaration ----").?..];
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, decls, ".exp()"));

        // §4.3: `exp` of an unbounded probe is not provably finite, so both units
        // are `.strict` and the declaration they share must be too: compiling it
        // `.optimized` would assert `ninf` on behalf of a unit that never had it.
        const at = std.mem.find(u8, src, "fn sh__common__core").?;
        try std.testing.expect(std.mem.find(u8, src[at..], "@setFloatMode(.strict);") != null);
    }

    test "codegen: one declaration even for a single contribution" {
        // No threshold: one contribution gets the same shape as fifty, because
        // `eval` reads its targets out of one struct. The extra call is free; LLVM
        // inlines a core this small.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "fn res__common__core(") != null);
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, src, "return zResidual(S, xs, @call(.always_inline, core, .{ S, xs, model, inst, sim }));"));
    }

    test "codegen: the unit ranges tile the emission and each names its own decl" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module res(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real r = 1000.0 from (0:inf);
            \\  parameter real c = 1e-12;
            \\  analog begin
            \\    I(p, n) <+ V(p, n) / r;
            \\    I(p, n) <+ ddt(c * V(p, n));
            \\    V(p, n) <+ laplace_nd(V(p, n), '{1.0}, '{1.0, 1.0});
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const o = try h.genOut(std.testing.allocator);

        // The merged core and `updateState`'s slice of it: every shape
        // `emitUnits` can still produce for a model with no §9.4 display unit.
        // The §4.5.11 `__sec` coefficient reader is not a unit file: it stays in
        // the prologue (below), where every unit file reaches it through `dev`.
        try std.testing.expectEqual(@as(usize, 2), o.names.len);
        for (o.names, o.unit_lo, o.unit_hi, 0..) |name, lo, hi, i| {
            // Tiling: `Output`'s invariant, and what lets the writer rebuild
            // device.zig as prologue ++ imports ++ tail with nothing dropped.
            if (i != 0) try std.testing.expectEqual(o.unit_hi[i - 1], lo);
            const decl = try std.testing.allocator.print("fn {s}(", .{name});
            defer std.testing.allocator.free(decl);
            // The range holds the declaration it is named for, and `unit_fn` points
            // at that declaration's keyword, where the writer splices `pub `,
            // without which `@import("u/<key>.zig").<key>` does not resolve.
            try std.testing.expect(std.mem.find(u8, o.text[lo..hi], decl) != null);
            try std.testing.expect(lo <= o.unit_fn[i] and o.unit_fn[i] < hi);
            const at = o.text[o.unit_fn[i]..];
            try std.testing.expect(std.mem.startsWith(u8, at, decl) or
                std.mem.startsWith(u8, at, "pub fn "));
        }
        // The tail after the last unit is the dispatcher, not more units.
        try std.testing.expect(std.mem.find(u8, o.text[o.unit_hi[o.unit_hi.len - 1]..], "pub fn eval(") != null);
        // The prologue before the first unit carries the types a unit file aliases.
        try std.testing.expect(std.mem.find(u8, o.text[0..o.unit_lo[0]], "pub const Model = struct {") != null);
        try std.testing.expect(std.mem.find(u8, o.text[0..o.unit_lo[0]], "__sec(") != null);
    }

    test "codegen: the unit prologue aliases the helper API and not its internals" {
        // `appendAliases` reads the same text `publish` does, so every helper is
        // aliased by construction. The `z` + uppercase clause is what keeps a
        // kernel file's private names out of the prologue; pin both sides.
        const gpa = std.testing.allocator;
        const has = std.mem.find;
        var str: std.ArrayList(u8) = .empty;
        defer str.deinit(gpa);
        try gen_kernel_text.appendAliases(&str, gpa, gen_kernel_text.str_txt);
        var file: std.ArrayList(u8) = .empty;
        defer file.deinit(gpa);
        try gen_kernel_text.appendAliases(&file, gpa, gen_kernel_text.file_txt);
        try std.testing.expect(has(u8, str.items, "const zScan = zh.zScan;\n") != null);
        try std.testing.expect(has(u8, file.items, "const zFOpen = zh.zFOpen;\n") != null);
        // str_kernels.zig's `pub const ZScan` and `const zstd`, file_kernels.zig's
        // `fn zfIo` and `const zf_max`: public in h.zig, never named by an emitted
        // body, so aliasing them would be legal, unreferenced, and pure noise.
        try std.testing.expect(has(u8, str.items, "ZScan") == null);
        try std.testing.expect(has(u8, str.items, "zstd") == null);
        try std.testing.expect(has(u8, file.items, "zfIo") == null);
        try std.testing.expect(has(u8, file.items, "zf_max") == null);
    }

    test "codegen: every split unit file passes AstGen, hoist arrays included" {
        // A `u/<key>.zig` is the prelude ++ its unit, so a body local that shares a
        // prelude name is a shadowing error in the split (`--emit-so`) form alone.
        // `ln` keeps the diamond out of ifconv, so `y` is a two-assignment phi and
        // lands in the hoist array.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module hoist(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real k = 2.0;
            \\  real y;
            \\  analog begin
            \\    if (V(p, n) > 0.0)
            \\      y = ln(V(p, n) * k);
            \\    else
            \\      y = -V(p, n);
            \\    I(p, n) <+ y * y;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const o = try h.genOut(std.testing.allocator);
        const gpa = std.testing.allocator;
        try std.testing.expect(o.names.len != 0);
        try std.testing.expect(std.mem.find(u8, o.text, "var h0: [") != null);
        for (o.unit_lo, o.unit_fn, o.unit_hi) |lo, fn_at, hi| {
            // `orchestrator.writeTree`'s unit file.
            const file = try std.mem.concatWithSentinel(gpa, u8, &.{ o.prelude, o.text[lo..fn_at], "pub ", o.text[fn_at..hi] }, 0);
            defer gpa.free(file);
            var tree = try std.zig.Ast.parse(gpa, file, .{ .mode = .zig });
            defer tree.deinit(gpa);
            var zir = try std.zig.AstGen.generate(gpa, tree);
            defer zir.deinit(gpa);
            if (zir.hasCompileErrors()) std.debug.print("{s}\n", .{file});
            try std.testing.expect(!zir.hasCompileErrors());
        }
    }

    test "codegen: a laplace device's split unit files reach its __sec reader" {
        // ESPice's `.hdl` loader builds split: the core called `<unit>__sec`, a
        // unit file of its own, with no declaration in the core's file
        // ("use of undeclared identifier", GeneratedDeviceDoesNotCompile). The
        // reader now sits in device.zig's prologue, public, and every unit file
        // aliases it from `dev`; AstGen resolves every identifier, so it fails
        // on a unit file that names one it does not declare.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module vl2(p, n, cp, cn);
            \\  inout p, n, cp, cn;
            \\  electrical p, n, cp, cn;
            \\  parameter real num[0:2] = '{1.0, 0.0, 0.0};
            \\  parameter real den[0:2] = '{1.0, 1e-9, 0.0};
            \\  analog V(p, n) <+ laplace_nd(V(cp, cn), num, den);
            \\endmodule
        , &h);
        defer h.deinit();
        const o = try h.genOut(std.testing.allocator);
        const gpa = std.testing.allocator;
        try std.testing.expect(o.names.len != 0);
        const sec = "vl2__analog_op__laplace_nd__sec";
        // In device.zig's prologue, public, and no unit file of its own.
        try std.testing.expect(std.mem.find(u8, o.text[0..o.unit_lo[0]], "pub fn " ++ sec ++ "(") != null);
        for (o.names) |nm| try std.testing.expect(!std.mem.endsWith(u8, nm, "__sec"));
        try std.testing.expect(std.mem.find(u8, o.prelude, "const " ++ sec ++ " = dev." ++ sec ++ ";\n") != null);
        var named = false;
        for (o.unit_lo, o.unit_fn, o.unit_hi) |lo, fn_at, hi| {
            named = named or std.mem.find(u8, o.text[lo..hi], sec ++ "(model)") != null;
            const file = try std.mem.concatWithSentinel(gpa, u8, &.{ o.prelude, o.text[lo..fn_at], "pub ", o.text[fn_at..hi] }, 0);
            defer gpa.free(file);
            var tree = try std.zig.Ast.parse(gpa, file, .{ .mode = .zig });
            defer tree.deinit(gpa);
            var zir = try std.zig.AstGen.generate(gpa, tree);
            defer zir.deinit(gpa);
            if (zir.hasCompileErrors()) std.debug.print("{s}\n", .{file});
            try std.testing.expect(!zir.hasCompileErrors());
        }
        // The core reads the reader, so the split form exercised the alias.
        try std.testing.expect(named);
    }

    test "codegen: identical MIR yields a byte-identical file (determinism)" {
        var h1: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h1);
        defer h1.deinit();
        var h2: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h2);
        defer h2.deinit();
        try std.testing.expectEqualStrings(try h1.gen(std.testing.allocator), try h2.gen(std.testing.allocator));
    }

    test "codegen: adding a contribution appends to the core, it does not renumber" {
        var h1: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h1);
        defer h1.deinit();
        var h2: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module res(p, n);
            \\  inout p, n;
            \\  electrical p, n, m;
            \\  parameter real r = 1000.0 from (0:inf);
            \\  analog begin
            \\    I(p, n) <+ V(p, n) / r;
            \\    I(m, n) <+ V(m, n) / r;
            \\  end
            \\endmodule
        , &h2);
        defer h2.deinit();

        const a = try h1.gen(std.testing.allocator);
        const b2 = try h2.gen(std.testing.allocator);
        // The first contribution is still `f0` and `eval` still stamps it from
        // `m.f0`. That is what `plan_core.plan`'s job-order numbering buys: the field
        // index of an existing target is insert-tolerant in the same sense
        // `ir/names.zig` makes a declaration name insert-tolerant, so `zig`'s
        // `TrackedInst` for the dispatcher does not churn on an unrelated edit.
        try std.testing.expect(std.mem.find(u8, a, "const c = m.f0;") != null);
        try std.testing.expect(std.mem.find(u8, b2, "const c = m.f0;") != null);
        const ka = a[std.mem.find(u8, a, "inline fn zResidual(").?..];
        const kb = b2[std.mem.find(u8, b2, "inline fn zResidual(").?..];
        const na = std.mem.find(u8, ka, "    }\n").? + 6;
        const nb = std.mem.find(u8, kb, "    }\n").? + 6;
        try std.testing.expectEqualStrings(ka[0..na], kb[0..nb]);
    }

    test "codegen: §5.6.1.2 reactive split emits q(), §4.2.12 select stays lazy" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module cap(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real c = 1e-12 from (0:inf);
            \\  parameter real vmin = 1.0 from (0:inf);
            \\  analog begin
            \\    I(p, n) <+ c * ddt(V(p, n));
            \\    I(p, n) <+ V(p, n) > vmin ? ln(V(p, n)) : 0.0;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "pub fn q(comptime S: type") != null);
        // The reactive half is a SECOND field of the same core, reached by `q`:
        // the split survives the merge as two targets, not two declarations.
        try std.testing.expect(std.mem.find(u8, src, "fn cap__common__core(") != null);
        // §4.2.3/§4.2.12 laziness (proof.zig's CODEGEN OBLIGATION): the `ln` must
        // sit INSIDE the arm, never in a preceding `const`. Matching a bare `if (`
        // is deliberate: `?:` lowers to a CFG diamond (`lowerTernary`) and a
        // `select` renders as the expression `(if (c) a else b)`, and BOTH satisfy
        // the obligation. What must never happen is `.log()` ahead of the guard.
        const unit = src[std.mem.find(u8, src, "fn cap__common__core(").?..];
        const body = unit[0..std.mem.find(u8, unit, "\n}\n").?];
        const guard = std.mem.find(u8, body, "if (").?;
        const lg = std.mem.find(u8, body, "zLnD(").?;
        try std.testing.expect(lg > guard);
    }

    test "codegen: evalQ fuses both residuals onto ONE core call" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module cap(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real c = 1e-12 from (0:inf);
            \\  parameter real r = 1e3 from (0:inf);
            \\  analog begin
            \\    I(p, n) <+ c * ddt(V(p, n));
            \\    I(p, n) <+ V(p, n) / r;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // `eval` and `q` survive untouched; the fusion is additive.
        try std.testing.expect(std.mem.find(u8, src, "pub fn eval(comptime S: type") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub fn q(comptime S: type") != null);
        const at = std.mem.find(u8, src, "pub fn evalQ(comptime S: type").?;
        const fused = src[at..][0..std.mem.find(u8, src[at..], "\n}\n").?];

        // The whole point: ONE core call for both halves. Two would make `evalQ`
        // exactly the `eval` + `q` it exists to replace.
        try std.testing.expect(std.mem.count(u8, fused, "@call(.always_inline, core, .{ S, xs, model, inst, sim })") == 1);
        // ...and it is hoisted ABOVE both halves: the resistive rows are `eval`'s
        // own `zResidual`, handed this core result.
        try std.testing.expect(std.mem.find(u8, fused, "@call(.always_inline, core, .{ S, xs, model, inst, sim })").? <
            std.mem.find(u8, fused, "zResidual(S, xs, m)").?);
        try std.testing.expect(std.mem.find(u8, fused, "struct { res: contract.Rows(Self, S), q: contract.Sites(Self, S) }") != null);
        // §5.6.1.2 the reactive half is the charge sites, read off the same core.
        try std.testing.expect(std.mem.find(u8, fused, "return .{ .res = zResidual(S, xs, m), .q = @as(contract.Sites(Self, S), .{ m.f") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub fn eval(comptime S: type, x: *const [n_u]S.V, model: *const Model, inst: InstancePtr, sim: contract.SimState) contract.Rows(Self, S) {\n    const xs = zProbe(S, x);\n    return zResidual(S, xs, @call(") != null);
        // The one `ddt` site stamps +p and −n (§1.3.1.2).
        try std.testing.expect(std.mem.find(u8, src, "pub const n_q: usize = 1;") != null);
        try std.testing.expect(std.mem.find(u8, src, ".{ .site = 0, .row = .p, .sign = 1.0 },\n    .{ .site = 0, .row = .n, .sign = -1.0 },") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub const q_lte = [n_q]bool{ true };") != null);
    }

    test "codegen: a device with no reactive half gets no evalQ" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module res(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real r = 1e3 from (0:inf);
            \\  analog I(p, n) <+ V(p, n) / r;
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // Pairs with `q`: the contract rejects `evalQ` without one, so codegen
        // must not emit a fused entry point there is nothing to fuse.
        try std.testing.expect(std.mem.find(u8, src, "pub fn q(") == null);
        try std.testing.expect(std.mem.find(u8, src, "pub fn evalQ(") == null);
    }

    test "codegen: §5.8 control flow reconstructs into structured Zig" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module sw(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real ron = 1.0 from (0:inf);
            \\  parameter real roff = 1e9 from (0:inf);
            \\  analog begin : body
            \\    real g;
            \\    g = 0.0;
            \\    if (V(p, n) > 0.5) g = 1.0 / ron; else g = 1.0 / roff;
            \\    I(p, n) <+ g * V(p, n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "if (") != null);
        try std.testing.expect(std.mem.find(u8, src, "} else {") != null);
        try std.testing.expect(std.mem.find(u8, src, "break :B") != null);
    }

    test "codegen: minmax tie derivatives use source-defined mask selection" {
        for ([_][]const u8{ "min", "$min", "max", "$max" }) |name| {
            const input = try std.testing.allocator.print(
                "module m(p,q); inout p,q; electrical p,q; analog I(p) <+ {s}(V(p),V(q)); endmodule",
                .{name},
            );
            defer std.testing.allocator.free(input);
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator, input, &h);
            defer h.deinit();
            const src = try h.gen(std.testing.allocator);
            const call = if (std.mem.endsWith(u8, name, "min")) "zMin(zL(S, " else "zMax(zL(S, ";
            try std.testing.expect(std.mem.find(u8, src, call) != null);
            try std.testing.expect(std.mem.find(u8, src, "return a.lt(b).sel(a, b);") != null);
            try std.testing.expect(std.mem.find(u8, src, "return b.lt(a).sel(a, b);") != null);
        }
    }

    test "codegen: if-converted diamond emits an eager mask select in a strict unit" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module mix(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin : body
            \\    real g;
            \\    if (V(p, n) > 0.5) g = 2.0 * V(p, n); else g = 0.5 * V(p, n);
            \\    I(p, n) <+ g * exp(V(p, n));
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        // root.zig runs this between lower and prove; the harness does the same.
        // The MIR is arena-owned, so the pass must append with the same arena.
        const n = try ifconv.run(h.arena_state.allocator(), &h.mir);
        try std.testing.expect(n >= 1);
        const src = try h.gen(std.testing.allocator);
        // exp(unbounded V) forfeits finiteness, so the unit is .strict, the
        // eager-sel license. Arms are plain arithmetic: mask form, no branch.
        try std.testing.expect(std.mem.find(u8, src, ".sel(") != null);
        // Lane-true mask: `V > 0.5` renders in S space as the swapped `lt`, not
        // as a `.val()` i64 round-trip.
        try std.testing.expect(std.mem.find(u8, src, ".lt(") != null);
        // The diamond is gone: nothing left for the relooper to label.
        try std.testing.expect(std.mem.find(u8, src, "break :B") == null);
    }

    test "codegen: a value shared by select arms is computed once, not once per use" {
        var h: Harness = undefined;
        // bsim2's vgeff shape: `e` is computed before the `if`, and after
        // conversion its only readers are select arms. Inlined per arm position
        // it would be four `exp` calls for the source's one.
        try Harness.run(std.testing.allocator,
            \\module sh(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin : body
            \\    real e, g;
            \\    e = exp(V(p, n));
            \\    if (V(p, n) > 0.5) g = e * e + e; else g = 0.5 * e;
            \\    I(p, n) <+ g;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        try std.testing.expect(try ifconv.run(h.arena_state.allocator(), &h.mir) >= 1);
        const src = try h.gen(std.testing.allocator);
        const unit = src[std.mem.find(u8, src, "fn sh__").?..];
        const body = unit[0..std.mem.find(u8, unit, "\n}\n").?];
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, body, ".exp()"));
    }

    test "codegen: a domain-guarded arm stays lazy through if-conversion" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module lg(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real vmin = 1.0 from (0:inf);
            \\  analog I(p, n) <+ V(p, n) > vmin ? ln(V(p, n)) : 0.0;
            \\endmodule
        , &h);
        defer h.deinit();
        _ = try ifconv.run(h.arena_state.allocator(), &h.mir);
        const src = try h.gen(std.testing.allocator);
        // What this protects is §4.2.12 laziness, not a spelling: `ln` runs only
        // on the path `V > vmin` selects. The guard may come out as a lazy
        // `(if (c) a else b)` or as the CFG `if (c) { ... } else { ... }` that
        // ifconv keeps for a domain-restricted arm. Both pass; an eager `.sel(`
        // or a `.log()` outside the then-arm fails.
        // Scoped to the unit body: the emitted math prelude also spells `.log()`.
        const unit = src[std.mem.find(u8, src, "fn lg__").?..];
        const body = unit[0..std.mem.find(u8, unit, "\n}\n").?];
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, body, "zLnD("));
        const lg2 = std.mem.find(u8, body, "zLnD(").?;
        // The nearest `if (` before the `.log()` opens the arm holding it, and no
        // `else` between them makes that the THEN arm, the one `V > vmin` takes.
        const guard = std.mem.findLast(u8, body[0..lg2], "if (").?;
        try std.testing.expect(std.mem.find(u8, body[guard..lg2], "else") == null);
        try std.testing.expect(std.mem.find(u8, body[0..lg2], "model.vmin") != null);
        try std.testing.expect(std.mem.find(u8, body, ".sel(") == null);
        // And the proof accepted `ln` UNDER that guard: without it V <= 0 is
        // reachable and the unit would drop to `.strict`.
        try std.testing.expect(std.mem.find(u8, body, "@setFloatMode(.optimized)") != null);
    }

    test "codegen: a multi-use domain op under a guard keeps its CFG diamond" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module ml(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin : body
            \\    real y;
            \\    y = 0.0;
            \\    if (V(p, n) > 0.0) begin : arm
            \\      real t;
            \\      t = ln(V(p, n));
            \\      y = t + 2.0 * t; // t shared: markSelectArms could not guard it
            \\    end
            \\    I(p, n) <+ y * 1.0e-3;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        // The guard's evidence only survives conversion on exclusively-owned
        // slices; a shared `ln` result must refuse, or the model silently drops
        // to `.strict` (and an integer `/` in the same shape turns REJECTED).
        const n = try ifconv.run(h.arena_state.allocator(), &h.mir);
        try std.testing.expectEqual(@as(u32, 0), n);
        // Still compiles and proves through the CFG dominance path.
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "zLnD(") != null);
    }

    test "codegen: a speculated domain op runs on its safe argument off its guard (#81)" {
        // The same shape after `.speculate` (src/Compilation.zig runs it after a proof
        // that left the reads `.strict`): the branch is gone, and the checked ln
        // reads `V` only while `V > 0` holds, else ln's safe argument 1, so the
        // §4.3.2 report never fires from the arm the source did not run.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module ml(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin : body
            \\    real y;
            \\    y = 0.0;
            \\    if (V(p, n) > 0.0) begin : arm
            \\      real t;
            \\      t = ln(V(p, n));
            \\      y = t + 2.0 * t;
            \\    end
            \\    I(p, n) <+ y * 1.0e-3;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        _ = try ifconv.run(h.arena_state.allocator(), &h.mir);
        try std.testing.expectEqual(@as(u32, 1), try ifconv.runMode(h.arena_state.allocator(), &h.mir, .speculate, null));
        const src = try h.gen(std.testing.allocator);
        const unit = src[std.mem.find(u8, src, "fn ml__").?..];
        const body = unit[0..std.mem.find(u8, unit, "\n}\n").?];
        const lg = std.mem.find(u8, body, "zLnD(S, zPick(").?;
        // The guard is the branch's condition, and the fallback is `S.con(1.0)`.
        const guard_end = std.mem.find(u8, body[lg..], "S.con(1.0)").?;
        try std.testing.expect(std.mem.find(u8, body[lg..][0..guard_end], "zCmp(S, .lt, S.con(0.0)") != null or
            std.mem.find(u8, body[lg..][0..guard_end], "!= 0") != null);
        try std.testing.expect(std.mem.find(u8, body, "if (") == null or std.mem.find(u8, body, "} else {") == null);
    }

    test "codegen: a §5.6 potential contribution gets its own branch-current unknown" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module vs(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real dc = 1.0;
            \\  analog V(p, n) <+ dc;
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // lowering only allocates `flow(a,b)` where the model PROBES I(a,b), so
        // codegen appends the unknown AFTER `nodes`, so existing indices hold.
        try std.testing.expect(std.mem.find(u8, src, "flowZ28pZ2cnZ29, // branch flow") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub const u_kinds") != null);
        try std.testing.expect(std.mem.find(u8, src, ".sub(c));") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub const num_ports: usize = 2;") != null);
    }

    test "codegen: §4.6.4 two noise sources on one branch export TWO generators" {
        var h: Harness = undefined;
        // The clause's own shape: "multiple noise contributions to a single branch
        // are combined" (as `combined/noise_temperature_analysis.va` writes it).
        // Neither statement may overwrite the other's generator.
        try Harness.run(std.testing.allocator,
            \\module rnoise(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real rs = 1000.0;
            \\  analog begin
            \\    I(p, n) <+ V(p, n) / rs;
            \\    I(p, n) <+ white_noise(1.6e-23 / rs, "thermal");
            \\    I(p, n) <+ flicker_noise(1e-20, 1.0, "flicker");
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // §4.6.4.6 each CALL is one generator, so the two rows carry distinct
        // dense `source` ids: two independent sources, not one shared.
        // §4.6.4.1/.2 the trailing `name` argument is a LABEL and rides out with
        // the row. Two calls sharing one name would still be two sources (the
        // clause combines them in the host's summary, not in the table), which is
        // why `source` is distinct here while `name` is free to repeat.
        try std.testing.expect(std.mem.find(u8, src, ".kind = .thermal, .source = 0, .name = \"thermal\" }") != null);
        try std.testing.expect(std.mem.find(u8, src, ".kind = .flicker, .source = 1, .name = \"flicker\" }") != null);
        // §4.6.4.1 before §4.6.4.2: the sources append in statement order, so the
        // table is stable across builds and a host may index it positionally.
        try std.testing.expect(
            std.mem.find(u8, src, ".kind = .thermal").? <
                std.mem.find(u8, src, ".kind = .flicker").?,
        );
    }

    test "codegen: §4.6.4 noisePsd is the model's own PSD, and a guarded one reads zero" {
        var h: Harness = undefined;
        // The shape EVERY series resistance in a real model card writes: the
        // generator lives inside `if (r > 0)`, and its power divides by that very
        // `r`. Computing `4kT/r` unconditionally evaluates it at r == 0: an
        // infinity that becomes a NaN the instant the collapsed branch gives it a
        // zero adjoint gain. It has to stay a core live-out, which `probeBody`
        // seeds `S.con(0.0)` and only the taken branch assigns.
        try Harness.run(std.testing.allocator,
            \\module rn(p, n, m);
            \\  inout p, n, m;
            \\  electrical p, n, m;
            \\  parameter real rs = 0.0;
            \\  parameter real ich = 1e-3;
            \\  analog begin
            \\    I(p, n) <+ white_noise(2.0 * 1.602176634e-19 * abs(ich), "shot");
            \\    if (rs > 0.0) begin
            \\      I(n, m) <+ V(n, m) / rs;
            \\      I(n, m) <+ white_noise(1.6e-23 / rs, "rs");
            \\    end else begin
            \\      V(n, m) <+ 0.0;
            \\    end
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // The hook exists and is positional against `noise_gens`.
        const at = std.mem.find(u8, src, "pub fn noisePsd(").?;
        try std.testing.expect(std.mem.find(u8, src, "pub const noise_gens").? < at);
        // Both powers come out of the core, NOT off a Jacobian and NOT inline:
        // §4.6.4.1 states the density as the call's argument, so the shot row is
        // `2q|I|` and the thermal row is `4kT/rs`: the same call, different
        // arguments, and only the model knows which.
        const body = src[at..];
        const ret = std.mem.find(u8, body, "return .{").?;
        try std.testing.expect(std.mem.find(u8, body[0..ret], "rn__common__core__noise(S, zVals(S, &x), model, inst, sim)") != null);
        try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, body[ret .. ret + 120], ".white = m.f"));
        // Both powers are solve-invariant, so the core returns them as `setup`
        // roots, and `setup` divides by rs only on the `rs > 0` arm, leaving the
        // root at its zero seed otherwise: a guarded generator still reads zero.
        var k: usize = ret;
        while (std.mem.findPos(u8, body, k, ".white = m.f")) |i| {
            const f = body[i + ".white = m.f".len ..];
            const end = std.mem.findScalar(u8, f, '.').?;
            const decl = try std.testing.allocator.print("    .f{s} = zTo(S, 0x0, S.con(model.su.r[", .{f[0..end]});
            defer std.testing.allocator.free(decl);
            try std.testing.expect(std.mem.find(u8, src, decl) != null);
            k = i + 1;
            if (k > ret + 120) break;
        }
        const su = src[std.mem.find(u8, src, "pub fn setup(").?..];
        const div = std.mem.find(u8, su, "/ (model.rs)").?;
        try std.testing.expect(std.mem.findLast(u8, su[0..div], "if (").? < div);
        try std.testing.expect(std.mem.find(u8, su[0..div], "} else {") == null);
    }

    test "codegen: §4.6.4.3/.4 a noise table is exported sorted, with its own interpolation" {
        var h: Harness = undefined;
        // The two clauses' arguments are IDENTICAL in shape ("the meaning and
        // restrictions on the input are the same as for noise_table()"), and they
        // differ only in how the points are joined, so the difference has to be in
        // the exported table and nowhere else. Written descending, because
        // §4.6.4.3 makes sorting the simulator's job.
        try Harness.run(std.testing.allocator,
            \\module ntab(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin
            \\    I(p, n) <+ noise_table('{1e6, 1e-24, 1.0, 1e-18});
            \\    I(p, n) <+ noise_table_log('{1.0, 1e-18, 1e6, 1e-24});
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // Ascending, whichever order the model wrote them in, and each table keeps
        // the interpolation of the FUNCTION that declared it. The literals are
        // `fmtF64`'s, which is every other constant in the emitted device too.
        const p18 = "0.000000000000000001"; // 1e-18
        const p24 = "0.000000000000000000000001"; // 1e-24
        try std.testing.expect(std.mem.find(u8, src, ".{ .interp = .linear, .points = &.{ .{ 1.0, " ++ p18 ++ " }, .{ 1000000.0, " ++ p24 ++ " } } }") != null);
        try std.testing.expect(std.mem.find(u8, src, ".{ .interp = .log, .points = &.{ .{ 1.0, " ++ p18 ++ " }, .{ 1000000.0, " ++ p24 ++ " } } }") != null);
        // One exported kind for both clauses, each row naming its own table, and
        // both independent generators (§4.6.4.6: two calls, two sources).
        try std.testing.expect(std.mem.find(u8, src, ".kind = .table, .source = 0, .table = 0 }") != null);
        try std.testing.expect(std.mem.find(u8, src, ".kind = .table, .source = 1, .table = 1 }") != null);
        // `noise_tables` is read by `noise_gens`, so it has to be declared first.
        try std.testing.expect(
            std.mem.find(u8, src, "pub const noise_tables").? <
                std.mem.find(u8, src, "pub const noise_gens").?,
        );
        // The parametric half of a table row is ZERO, or a host that adds
        // `white + flicker/f^ef` to the table's answer would double-count.
        // §4.6.4.6's coefficient is 1 on both: each table is contributed with no
        // factor, so the row scales its own spectrum by exactly one.
        const at = std.mem.find(u8, src, "pub fn noisePsd(").?;
        try std.testing.expectEqual(
            @as(usize, 2),
            std.mem.count(u8, src[at..], ".{ .white = 0, .coeff = 1 }, // noise_tables["),
        );
    }

    test "codegen: §4.6.4.3 an array-parameter table exports the card's knots, a literal one does not" {
        // A.8.2's `noise_table_input_arg` names `parameter_identifier` FIRST, and
        // §3.4 makes a parameter's value the model card's. So the comptime
        // `noise_tables` can only be the DECLARED DEFAULT and the card's answer is
        // the extra hook, which must not appear on a device that has no
        // parameter in any table, or every host of every such device would be
        // obliged to read something `noise_tables` already told it.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module nparam(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real tbl[0:3] = '{1e6, 1e-24, 1.0, 1e-18};
            \\  analog I(p, n) <+ noise_table(tbl);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // Sorted at compile time on the DEFAULTS, so `noise_tables` keeps the
        // invariant `contract.validate` enforces...
        try std.testing.expect(std.mem.find(u8, src, ".points = &.{ .{ 1.0, 0.000000000000000001 }, .{ 1000000.0, 0.000000000000000000000001 } }") != null);
        // ...and the hook returns the same two knots in the same order, reading
        // the card, with the run-time sort a reordering card would need.
        const at = std.mem.find(u8, src, "pub fn noiseTablePoints(model: *const Model) [2][2]f64 {").?;
        const end = std.mem.findPos(u8, src, at, "\n}\n").?;
        const body = src[at..end];
        try std.testing.expect(std.mem.find(u8, body, ".{ model.tblZ5b2Z5d, model.tblZ5b3Z5d }") != null);
        try std.testing.expect(std.mem.find(u8, body, ".{ model.tblZ5b0Z5d, model.tblZ5b1Z5d }") != null);
        try std.testing.expect(std.mem.find(u8, body, "contract.sortNoiseTable(pts[0..2]);") != null);
        // The default's order is the EXPORT's order: `noise_tables[k]` and the
        // hook's k-th pair are the same knot, so the sort permuted both.
        try std.testing.expect(std.mem.find(u8, body, ".{ model.tblZ5b2Z5d, model.tblZ5b3Z5d }").? <
            std.mem.find(u8, body, ".{ model.tblZ5b0Z5d, model.tblZ5b1Z5d }").?);
        // The row carries its own sorted copy (`contract.noiseTable`, ESPice #9):
        // the declared defaults until `derive`, which refreshes it after the card.
        try std.testing.expect(std.mem.find(u8, src, "noise_table_points__: [2][2]f64 = .{ .{ 1.0, 0.000000000000000001 }, .{ 1000000.0, 0.000000000000000000000001 } },") != null);
        try std.testing.expect(std.mem.find(u8, src, "    model.noise_table_points__ = noiseTablePoints(model);\n") != null);

        var h2: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module nlit(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ noise_table('{1.0, 1e-18, 1e6, 1e-24});
            \\endmodule
        , &h2);
        defer h2.deinit();
        const lit = try h2.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, lit, "noiseTablePoints") == null);
        try std.testing.expect(std.mem.find(u8, lit, "noise_table_points__") == null);
    }

    test "codegen: §4.6.4.6 each use of a shared generator exports its own coefficient" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module shared(a, b, c, d);
            \\  inout a, b, c, d;
            \\  electrical a, b, c, d;
            \\  parameter real pwr = 1e-18;
            \\  real nz;
            \\  analog begin
            \\    nz = white_noise(pwr, "shared");
            \\    V(a, b) <+ 2.0 * nz;
            \\    V(d, c) <+ 3.0 * nz;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // ONE generator (both rows carry `.source = 0`) with TWO coefficients.
        // Without them both rows report the raw 1e-18 and a host computes this
        // module's output noise 4x and 9x low.
        const at = std.mem.find(u8, src, "pub fn noisePsd(").?;
        try std.testing.expect(std.mem.find(u8, src[at..], ".coeff = 2") != null);
        // §1.3.1.2: `V(d,c)` drives the same branch as `V(c,d)` with the sign
        // flipped, and the SIGN is what separates correlation from
        // anti-correlation, so it has to survive into the export.
        try std.testing.expect(std.mem.find(u8, src[at..], ".coeff = -3") != null);
    }

    test "codegen: §4.6.4.6 a generator no single factor describes keeps coefficient 1" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module sq(a, b);
            \\  inout a, b;
            \\  electrical a, b;
            \\  real nz;
            \\  analog begin
            \\    nz = white_noise(1e-18);
            \\    I(a, b) <+ nz * nz;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // A generator squared is not a linear source, so there is no coefficient
        // to report and the row keeps 1 rather than inventing one.
        const at = std.mem.find(u8, src, "pub fn noisePsd(").?;
        try std.testing.expect(std.mem.find(u8, src[at..], ".coeff = 1") != null);
    }

    test "codegen: §4.6.4.6 one tabulated source on two branches is one table" {
        var h: Harness = undefined;
        // The clause's Example 1 shape with a §4.6.4.4 source: "Perfectly
        // correlated noise is generated by using the output of one noise function
        // for more than one noise source." One call is one generator, so the two
        // rows share a `source` and must share the TABLE too, or the export
        // describes one generator with two copies of its own spectrum.
        try Harness.run(std.testing.allocator,
            \\module nshare(a, b, c);
            \\  inout a, b, c;
            \\  electrical a, b, c;
            \\  real nt;
            \\  analog begin
            \\    nt = noise_table_log('{1.0, 1e-18, 1e6, 1e-24});
            \\    I(a, b) <+ nt;
            \\    I(b, c) <+ 2.0 * nt;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, src, ".interp = ."));
        try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, src, ".source = 0, .table = 0 }"));
    }

    test "codegen: §4.6.3 an ac_stim exports its phasor and no noise generator" {
        var h: Harness = undefined;
        // The whole of the export in one module: the stimulus reaches the
        // contribution through a VARIABLE (which is how every fixture writes it),
        // the phase is a quadrature one where `mag*cos(phase)` is 6.1e-17, and the
        // model also declares a real noise generator so the two tables are
        // observably separate.
        try Harness.run(std.testing.allocator,
            \\module stim(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real amp = 2.0;
            \\  real s;
            \\  analog begin
            \\    s = ac_stim("xf", amp, 1.5707963267948966);
            \\    I(p, n) <+ V(p, n) * 1e-3 + 3.0 * s;
            \\    I(p, n) <+ white_noise(1e-18);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // §4.6.3 is not §4.6.4: the stimulus has its own table and puts no row in
        // `noise_gens`, which would be a generator the model never declared.
        try std.testing.expect(std.mem.find(u8, src, ".name = \"xf\" }") != null);
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, src, "contract.NoiseGen(Self){"));
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, src, "contract.AcGen(Self){"));
        // One call is one source: the variable reaching two places (the value and
        // the contribution) must not become two rows.
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, src, ".name = \"xf\" }"));
        // The magnitude is a PARAMETER, so it cannot be comptime data: `acStim`
        // reads the card. And §4.6.4.6's per-use factor folds into it (a phasor
        // scales exactly), or a host is low by 3 on this source.
        const at = std.mem.find(u8, src, "pub fn acStim(").?;
        try std.testing.expect(std.mem.find(u8, src[at..], "(model.amp) * (3") != null);
        // Polar, not rectangular: `cos(π/2)` is 6.1e-17 and a stimulus that has
        // been through a complex conversion here is that far out of quadrature
        // before the host has done anything.
        try std.testing.expect(std.mem.find(u8, src[at..], ".phase = 1.5707963267948966") != null);
        // "xf" is no Table 4-21 small-signal kind, so the residual's stimulus is
        // live in a small-signal analysis the host labels "xf" (VD-109), read
        // through the GPU-safe Table 9-28 channel the Model row now carries.
        try std.testing.expect(std.mem.find(u8, src, "    analysis_name_idx__: u32 = 0,") != null);
        try std.testing.expect(std.mem.find(u8, src, "((sim.kind == .ac or sim.kind == .noise) and std.mem.eql(u8, contract.hostString(model.analysis_name_idx__, inst.analysis_name), \"xf\"))") != null);
    }

    test "codegen: §4.6.4 a generator VerA cannot export refuses the device" {
        // Both halves of the same rule: a `noise_gens` row that cannot be written
        // must take the DECL with it. Silently dropping the row would tell a host
        // the model declares no such noise, which is a PSD it can never ask for;
        // and `@compileError` is how codegen refuses (see `f64Expr`/E0515).
        const cases = [_][]const u8{
            // §1.3.1.1 a ground-ground branch has no row and no column (E0520).
            \\module ngnd(p);
            \\  inout p;
            \\  electrical p;
            \\  ground g;
            \\  electrical g;
            \\  analog begin
            \\    I(p) <+ V(p) * 1e-3;
            \\    I(g, g) <+ white_noise(1e-20);
            \\  end
            \\endmodule
            ,
            // §4.6.4.3 "Each frequency value must be unique" (E0519).
            \\module ndup(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ noise_table('{1.0, 1e-18, 1.0, 1e-24});
            \\endmodule
            ,
            // §4.6.4.3 pairs, not an odd tail (E0519).
            \\module nodd(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ noise_table('{1.0, 1e-18, 10.0});
            \\endmodule
            ,
            // NOT here: §4.6.4.3's FILE form. Its name "shall be constant", so
            // `Lower.readNoiseTableFile` reads the pairs at compile time and the
            // table it produces is indistinguishable from the vector form's. A
            // file that cannot be read is a lowering error on the .va, which never
            // reaches codegen at all.
            //
            // Nor an array parameter: `noise_tables` carries its defaults and
            // `noiseTablePoints` the card (the test after this one).
            // §4.6.4.4 interpolates log(power), and log(0) is not on the line.
            \\module nlog0(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ noise_table_log('{1.0, 0.0, 1e6, 1e-24});
            \\endmodule
            ,
        };
        for (cases) |case| {
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator, case, &h);
            defer h.deinit();
            const src = try h.gen(std.testing.allocator);
            try std.testing.expect(std.mem.find(u8, src, "pub const noise_gens = @compileError(\"LRM 4.6.4:") != null);
            // And no half-written table beside it.
            try std.testing.expect(std.mem.find(u8, src, "pub const noise_tables") == null);
            try std.testing.expect(std.mem.find(u8, src, "pub fn noisePsd(") == null);
        }
    }

    test "codegen: §5.6.7 indirect contribution is a nullor row, ASYMMETRIC-safe" {
        var h: Harness = undefined;
        // Deliberately asymmetric: probe − equation = V(pin,nin) − 2*V(out).
        // The mirrored row (equation − probe) is invisible on the textbook opamp
        // (`V(pin,nin) == 0`), so the fixture that pins the sign has to be one
        // whose two sides differ.
        try Harness.run(std.testing.allocator,
            \\module amp(out, pin, nin);
            \\  inout out, pin, nin;
            \\  electrical out, pin, nin;
            \\  analog V(out) : V(pin, nin) == 2.0 * V(out);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // The source current is a solver unknown; the KCL stamps are its only
        // occurrence outside its own row (a nullor).
        try std.testing.expect(std.mem.find(u8, src, "flowZ28outZ2cgndZ29, // branch flow") != null);
        try std.testing.expect(std.mem.find(u8, src, "res[@intFromEnum(U.flowZ28outZ2cgndZ29)] = zRow(S, .flowZ28outZ2cgndZ29, c);\n") != null);
        // ... and NOT the direct-contribution row `V(hi,lo) − c`.
        try std.testing.expect(std.mem.find(u8, src, ".sub(c));") == null);

        // THE trap: the row must be a function of `x`, or the host's dual-number
        // Jacobian has a zero column and Newton can never move the source.
        const key = "fn amp__common__core(comptime S: type, x: anytype";
        try std.testing.expect(std.mem.find(u8, src, key) != null);
        const unit = src[std.mem.find(u8, src, key).?..];
        const body = unit[0..std.mem.find(u8, unit, "\n}\n").?];
        // probe − equation, in that order.
        const probe_at = std.mem.find(u8, body, "U.pin").?;
        // `2.0 * V(out)` reaches the constant through `scale`, not through a
        // second dual: the derivative-free side of a product never becomes an S.
        const eqn_at = std.mem.find(u8, body, "scale(2.0)").?;
        try std.testing.expect(std.mem.find(u8, body, ".sub(") != null);
        try std.testing.expect(probe_at < eqn_at);
    }

    test "codegen: §5.6.7.1 two indirect contributions to one branch get one source each" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module two(p, n, c1, c2);
            \\  inout p, n, c1, c2;
            \\  electrical p, n, c1, c2;
            \\  analog begin
            \\    V(p, n) : V(c1) == V(p, n);
            \\    V(p, n) : V(c2) == 2.0 * V(p, n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // Two sources ⇒ two currents ⇒ two DISTINCT U members (a shared name would
        // be a duplicate enum field, which the Zig parser cannot catch).
        try std.testing.expect(std.mem.find(u8, src, "flowZ28pZ2cnZ29, // branch flow") != null);
        try std.testing.expect(std.mem.find(u8, src, "flowZ28pZ2cnZ29Z231, // branch flow") != null);
        // Two targets ⇒ two distinct core fields ⇒ two rows in `eval`. (`ir/names.zig`'s
        // group-local ordinal keys the second unit's §4.5 state and proof verdict.)
        try std.testing.expect(std.mem.find(u8, src, "const c = m.f0;") != null);
        try std.testing.expect(std.mem.find(u8, src, "const c = m.f1;") != null);
    }

    test "codegen: §5.10.5 only a `timer` module gets a nextBreakpoint hook" {
        // The hook is OPTIONAL in lib/contract.zig, and emitting it
        // for a module with no timer would claim a schedule that does not exist:
        // the host reads "no breakpoints ever" and stops asking. `transition` is the
        // trap case: it is stateful and discontinuity-adjacent, but nothing about it
        // says WHERE a timepoint goes, only how fast the value moves.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module tr(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ transition(V(p, n), 0.0, 1e-9);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "pub fn updateState(") != null);
        try std.testing.expect(std.mem.find(u8, src, "nextBreakpoint") == null);
    }

    test "codegen: §5.10.5 a timer whose start is a solved quantity emits NO hook" {
        // `nextBreakpoint` gets `*const Model` and no `Instance`, so the schedule
        // has to be a function of the parameters. A start_time read off the solution
        // is not, and there is no honest answer to give: a guessed one either hangs
        // the transient walk (an answer at or before `t`) or moves an edge. Silence
        // degrades to LTE step control, which is where every device is today.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module tv(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  integer fired;
            \\  analog begin
            \\    @(timer(V(p, n), 1e-9)) fired = fired + 1;
            \\    I(p, n) <+ fired;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "__next") != null); // the timer IS compiled
        try std.testing.expect(std.mem.find(u8, src, "nextBreakpoint") == null);
        // §5.10.3.3 but the LIVE schedule is: `updateState` re-arms `__next` from
        // the start_time, so an Instance-reading hook can answer what this cannot.
        try std.testing.expect(std.mem.find(u8, src, "pub fn pendingBreakpoint(inst: *const Instance, t: f64) ?f64") != null);
    }

    test "codegen: §4.5 operator state is keyed to the stable unit id" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module tr(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real td = 1e-9 from (0:inf);
            \\  analog I(p, n) <+ transition(V(p, n), 0.0, td, td);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "tr__analog_op__transition__from: f64 = 0.0") != null);
        try std.testing.expect(std.mem.find(u8, src, "tr__analog_op__transition__t0: f64 = 0.0") != null);
        // The operator's input is a core field, not a declaration of its own; the
        // state field carries `ir/names.zig`'s key.
        try std.testing.expect(std.mem.find(u8, src, "zTransition(zL(S, ") != null);
        try std.testing.expect(std.mem.find(u8, src, "const m = tr__common__core__state(S, zVals(S, &x), model, inst, sim);") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub fn updateState(") != null);
        // `updateState`'s slice returns the operator input alone: the residual
        // stays in the core, and the accepted step never pays for it.
        const at = std.mem.find(u8, src, "fn tr__common__core__state(").?;
        const sig = src[at..std.mem.findPos(u8, src, at, "} {").?];
        try std.testing.expect(std.mem.find(u8, sig, "f0:") != null);
        try std.testing.expect(std.mem.find(u8, sig, "f1:") == null);
        try std.testing.expect(std.mem.find(u8, src, "pub const State = struct {") != null);
    }

    test "codegen: §4.5.11 laplace_nd emits a real filter, not a compile error" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module lp(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ laplace_nd(V(p, n), '{1.0}, '{1.0, 1.0});
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "@compileError") == null);
        try std.testing.expect(std.mem.find(u8, src, "laplace_nd") != null);
        try std.testing.expect(std.mem.find(u8, src, "pub fn updateState(") != null);
        // The cascade's `__sec(model)` call is the only Model read in this module,
        // so the unit's parameter must stay named, not `_`.
        try std.testing.expect(std.mem.find(u8, src, "__sec(model)") != null);
        try std.testing.expect(std.mem.find(u8, src, "core(comptime S: type, x: anytype, model: *const Model") != null);
    }

    test "codegen: a non-const analog-operator control argument is a LOUD compile error" {
        // Unsupported constructs must be loud, never a silent substitute value
        // (a silent 0 corrupts the residual). §4.5.14 requires control arguments
        // to be constant.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module tv(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog I(p, n) <+ transition(V(p, n), 0.0, V(p, n), 1e-9);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "@compileError") != null);
    }

    test "codegen: §5.4.3 I(<p>) is a solver unknown pinned to the KCL sum at p" {
        var h: Harness = undefined;
        // §5.4.3's own diode example shape: the probed port also carries a `ddt`
        // contribution, so a DC-only port current would be silently wrong in tran.
        try Harness.run(std.testing.allocator,
            \\module d(a, c);
            \\  inout a, c;
            \\  electrical a, c;
            \\  parameter real cj = 1e-12;
            \\  real m;
            \\  analog begin
            \\    I(a, c) <+ 1e-3 * V(a, c) + ddt(cj * V(a, c));
            \\    m = I(<a>);
            \\    I(a, c) <+ 1e-9 * m;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // Its own unknown, appended after the ports so `num_ports` is untouched,
        // and classified a CURRENT by the existing `flow(` predicate.
        try std.testing.expect(std.mem.find(u8, src, "pub const num_ports: usize = 2;") != null);
        try std.testing.expect(std.mem.find(u8, src, "flowZ28Z3caZ3eZ29, // branch flow") != null);

        // SIGN: `I(p,n) <+ c` stamps `+c` at hi, so res[a] is the current leaving
        // node a INTO the module, which is exactly §5.4.3's "flow into a port".
        // Hence `x − res[a]`, not `x + res[a]`.
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "res[@intFromEnum(U.flowZ28Z3caZ3eZ29)] = zRow(S, .flowZ28Z3caZ3eZ29, x[@intFromEnum(U.flowZ28Z3caZ3eZ29)].sub(res[@intFromEnum(U.a)]));",
        ) != null);
        // THE REACTIVE HALF: the one charge site stamps `−q_a` on the same row,
        // so the total residual is x − (I_dc + d/dt q_a).
        try std.testing.expect(std.mem.find(
            u8,
            src,
            ".{ .site = 0, .row = .flowZ28Z3caZ3eZ29, .sign = -1.0 },",
        ) != null);
        // The row is emitted AFTER the contribution stamps it reads.
        const stamp_at = std.mem.find(u8, src, "res[@intFromEnum(U.a)].add(c)").?;
        const row_at = std.mem.find(u8, src, "= zRow(S, .flowZ28Z3caZ3eZ29, x[@intFromEnum(U.flowZ28Z3caZ3eZ29)].sub(").?;
        try std.testing.expect(stamp_at < row_at);
    }

    test "codegen: a port whose only branch goes to ground still gets its unknown" {
        var h: Harness = undefined;
        // The self-referential form: I(p) <+ I(<p>) + V(p). Nothing else drives p.
        try Harness.run(std.testing.allocator,
            \\module g(p);
            \\  inout p;
            \\  electrical p;
            \\  analog I(p) <+ I(<p>) + V(p);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "flowZ28Z3cpZ3eZ29, // branch flow") != null);
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "res[@intFromEnum(U.flowZ28Z3cpZ3eZ29)] = zRow(S, .flowZ28Z3cpZ3eZ29, x[@intFromEnum(U.flowZ28Z3cpZ3eZ29)].sub(res[@intFromEnum(U.p)]));",
        ) != null);
        // No reactive part anywhere ⇒ no q() at all, so no port row is missing.
        try std.testing.expect(std.mem.find(u8, src, "pub fn q(") == null);
    }

    test "codegen: the `U` block is the SPELLING contract — all four name kinds, verbatim" {
        var h: Harness = undefined;
        // `node_voltages` is one string key space over four different kinds of name,
        // and only one of them has a source spelling. The KEY is lowering's private
        // business, but the spelling is not: it reaches the user three times over:
        // as an emitted `U` member (here), as the identifier a `//! bias`/`//! sweep`
        // line has to write (tb.zig's `unknownName`, pinned in its own test), and as
        // the name every diagnostic over an unknown prints. So it is pinned as the
        // whole block, byte for byte, and not one `indexOf` per kind: an insertion,
        // a reorder or a re-escape is a change to the host's ABI and to every
        // fixture that biases an unknown, and each of those is invisible to a
        // substring search.
        //
        // Ports first, then §3.6.3 internal nets, then §5.4.2/§5.4.3 flows: the
        // order `emitTopology` documents, which is also `num_ports`' meaning.
        // `naming.sanitize` is what makes `b[0]` and `flow(p,n)` legal Zig, and
        // `isValidId` leaves `p` and `n` alone.
        try Harness.run(std.testing.allocator,
            \\module m(p, b);
            \\  inout p;
            \\  inout [0:1] b;
            \\  electrical p, n;
            \\  electrical [0:1] b;
            \\  real x;
            \\  analog begin
            \\    x = I(p, n);
            \\    I(p, n) <+ x + I(<p>);
            \\    I(b[0], b[1]) <+ V(b[0], b[1]);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src,
            \\pub const U = enum(u8) {
            \\    p, // port
            \\    bZ5b0Z5d, // port
            \\    bZ5b1Z5d, // port
            \\    n, // internal
            \\    flowZ28pZ2cnZ29, // branch flow
            \\    flowZ28Z3cpZ3eZ29, // branch flow
            \\};
        ) != null);
    }

    test "codegen: §5.9 a loop the unit re-runs is not read out of the shared core" {
        var h: Harness = undefined;
        // Two units both slice the loop, so `plan_core.plan` wants to hoist it, but
        // each also has private values inside it, so each re-materializes the loop.
        // Reading the hoisted counter and exit condition there is reading their
        // FINAL values, and the re-materialized loop then runs zero times.
        try Harness.run(std.testing.allocator,
            \\module l(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  integer i;
            \\  real a, b;
            \\  analog begin
            \\    a = 0.0;
            \\    b = 0.0;
            \\    for (i = 1; i <= 5; i = i + 1) begin
            \\      a = a + i;
            \\      b = b + i * 2;
            \\    end
            \\    I(p, n) <+ a * V(p, n);
            \\    I(p) <+ b * V(p);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        // `genDisplay`, not `gen`: the core emits the loop where its values are
        // computed, so only §9.4 `display`, which opens with `const c = core(...)`,
        // consumes the §5.9 `loop_recompute` fixpoint.
        const src = try h.genDisplay(std.testing.allocator);
        // A `while (true)` body must not read `c.f<N>`: that is the exit state.
        var rest = src;
        while (std.mem.find(u8, rest, "L")) |_| {
            const at = std.mem.find(u8, rest, ": while (true)") orelse break;
            const end = std.mem.findPos(u8, rest, at, "\n    }") orelse rest.len;
            try std.testing.expect(std.mem.find(u8, rest[at..end], "c.f") == null);
            rest = rest[end..];
        }
        // The residual half of the guarantee, stated structurally: the merged core
        // reads no cache, so a `c.f` cannot appear in it anywhere, in or out of a
        // loop. This is what makes the hazard impossible rather than merely absent.
        const core_at = std.mem.find(u8, src, "fn l__common__core(").?;
        const core_end = std.mem.findPos(u8, src, core_at, "\n}\n").?;
        try std.testing.expect(std.mem.find(u8, src[core_at..core_end], "c.f") == null);
    }

    test "codegen: §9.4 display tasks are void by default and print on request" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module d(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real g = 2.0;
            \\  analog begin
            \\    $strobe("g=%g n=%5d s=%s", g, 42, "x");
            \\    $write("no newline");
            \\    $error("bad");
            \\    I(p, n) <+ g * V(p, n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();

        // A DEVICE never prints: no sink, nothing that blocks a GPU backend.
        const dev = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, dev, "std.debug.print") == null);
        try std.testing.expect(std.mem.find(u8, dev, "pub fn display(") == null);

        // The EXECUTABLE does, with §9.4.3 conversions translated and the operands
        // sliced in (a missing slice renders every one of them as `S.con(0.0)`).
        const exe = try h.genDisplay(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, exe, "pub fn display(") != null);
        // `%g` is a §9.4.3 Table 9-23 REAL conversion, so it composes its own
        // field through `str_kernels.zCReal` and arrives as `{s}`; `%5d` is the
        // documented zPadInt detour and `%s` is Zig's own verb.
        try std.testing.expect(std.mem.find(u8, exe, "g={s} n={s:>5} s={s}\\n") != null);
        try std.testing.expect(std.mem.find(u8, exe, "zCReal(&zb0, (S.con(model.g)).val(), 'g', 0, 0, -1)") != null);
        // §9.4.1 `$write` is the one that does not end the line.
        try std.testing.expect(std.mem.find(u8, exe, "\"no newline\"") != null);
        // §9.7.3 the severity is a prefix, not something a reader must infer,
        // and the moment (`zWhen`) sits between it and the message.
        try std.testing.expect(std.mem.find(u8, exe, "\"ERROR: \", .{}); zWhen(sim.t, 1); std.debug.print(\" bad") != null);
        // No `$debug`/`$fdebug`: one pass, no `pass` parameter.
        try std.testing.expect(std.mem.find(u8, exe, "SayPass") == null);
    }

    test "codegen: §9.5.9 `$fdebug` and `$debug` run on every pass but the accepted one" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module fd(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  integer f, g;
            \\  analog initial f = $fopen("a.log", "w");
            \\  analog begin
            \\    $fdebug(f, "x=%g", V(p, n));
            \\    $debug("x=%g", V(p, n));
            \\    $fwrite(f, "y");
            \\    g = $fopen("b.log", "r");
            \\    $strobe("s");
            \\    I(p, n) <+ V(p, n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const exe = try h.genDisplay(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, exe, "pub fn displayPass(") != null);
        try std.testing.expect(std.mem.find(u8, exe, "displayPass(S, x, model, inst, sim, .all);") != null);
        try std.testing.expect(std.mem.find(u8, exe, ", comptime pass: contract.SayPass)") != null);
        // §5.2.1 the analog initial block's open runs once, at the first iterate.
        try std.testing.expect(std.mem.find(u8, exe, "(if (zFinish == 0 and (pass == .all or (pass == .iteration and sim.iteration == 1))) zFKeep(") != null);
        // `$fdebug` and `$debug`, then `$fwrite`, the main block's `$fopen` (its
        // latch otherwise) and `$strobe`.
        try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, exe, "(if (zFinish == 0 and (pass != .accepted)) "));
        try std.testing.expectEqual(@as(usize, 3), std.mem.count(u8, exe, "(if (zFinish == 0 and (pass != .iteration)) "));
        try std.testing.expect(std.mem.find(u8, exe, " else zFRes(") != null);
        // A device drops every §9.5 call: no passes.
        const dev = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, dev, "displayPass") == null);
    }

    test "codegen: §9.4.6 a display task under an `if` prints inside its arm" {
        // A guarded display call does not dominate the end-of-block chain root,
        // and an unchained call is dead code the unit slice drops. Lowering carries
        // it through an SSA place written in the arm, so the call keeps its CFG
        // position and the phi keeps it live.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module c(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin
            \\    if (V(p, n) > 0.5) $strobe("hi");
            \\    else $strobe("lo");
            \\    $strobe("always");
            \\    I(p, n) <+ V(p, n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();

        const exe = try h.genDisplay(std.testing.allocator);
        const at = std.mem.find(u8, exe, "fn c__display__tasks(").?;
        const body = exe[at..std.mem.findPos(u8, exe, at, "\n}\n").?];
        // All three reach the output...
        for ([_][]const u8{ "\"hi\\n\"", "\"lo\\n\"", "\"always\\n\"" }) |lit|
            try std.testing.expect(std.mem.find(u8, body, lit) != null);
        // ...and the two guarded ones are still GUARDED: each sits after an `if`
        // and before the unconditional one, which is emitted at the block's end.
        const hi = std.mem.find(u8, body, "\"hi\\n\"").?;
        try std.testing.expect(std.mem.findLast(u8, body[0..hi], "if (") != null);
        try std.testing.expect(hi < std.mem.find(u8, body, "\"always\\n\"").?);
        // A DEVICE still prints nothing at all (W0850 covers the whole family).
        const dev = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, dev, "std.debug.print") == null);
    }

    test "codegen: §9.5 a descriptor is an i64 in the DEVICE too, not only in the executable" {
        // `callee.ty` types the descriptor-returning §9.5 calls `.int`, so
        // in a device their slot is `i64` and `emitFileCallDropped` must write an
        // integer zero, not `S.con(0.0)`; otherwise the host's build fails on
        // generated Zig. `fd` feeds the residual on purpose: an unread descriptor
        // gets no slot. The suite compiles every fixture with `.display = .emit`,
        // so only this test reaches the `.drop` path.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module fdev(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  integer fd;
            \\  analog begin
            \\    fd = $fopen("nope.txt");
            \\    I(p, n) <+ V(p, n) * (fd + 1);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();

        // §9.5.1 "a zero is returned for the mcd or fd" as an INTEGER. A device has
        // no host file table, so zero is the answer and not a stub.
        const dev = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, dev, ": i64 = @as(i64, 0);") != null);
        try std.testing.expect(std.mem.find(u8, dev, ": i64 = S.con(") == null);
        // No kernel came with it: `buildPrelude` gates the descriptor table on
        // `display == .emit`, and a call to `zFOpen` here would not resolve.
        try std.testing.expect(std.mem.find(u8, dev, "zFOpen") == null);

        // The printing artifact opens the file for real, in the display unit, and
        // latches the descriptor; the core's `fd` (the one the residual and
        // `updateState` see) is that latch, not the device's zero.
        const exe = try h.genDisplay(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, exe, "zFKeep(") != null);
        try std.testing.expect(std.mem.find(u8, exe, ": i64 = zFRes(") != null);
    }

    test "codegen: §9.4 a display unit that reads an operator input opens the cache" {
        // The display unit is the one unit not folded into the core, and an
        // operator's input is not a `mark`ed operand, so a `c.f*` rendered for it
        // needs its own `const c = core(...)` above it. Same shape for
        // ddt/transition/slew/laplace.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module dop(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin
            \\    $strobe("y=%g", transition(V(p, n), 0.0, 1n, 1n));
            \\    I(p, n) <+ V(p, n);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const exe = try h.genDisplay(std.testing.allocator);
        const at = std.mem.find(u8, exe, "zLw(S, 0x3, c.f").?;
        const open = std.mem.findLast(u8, exe[0..at], "const c = @call(.always_inline, core, .{ S, x, model, inst, sim });");
        const head = std.mem.findLast(u8, exe[0..at], "\nfn ") orelse 0;
        try std.testing.expect(open != null and open.? > head);
    }

    test "codegen: §2.6.1 an integer literal keeps all 64 bits" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module big(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  integer k;
            \\  analog begin
            \\    k = 4607182418800017408;
            \\    I(p, n) <+ V(p, n) * k;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // The integer side of the product carries no derivative, so it folds and
        // arrives as the f64 the multiply needs. `fmtF64` is `{d}`, which is the
        // shortest representation that ROUND-TRIPS: 4607182418800017400.0 parses
        // back to exactly 4607182418800017408, and every literal in every emitted
        // device already rests on that. What must not happen is the value changing.
        try std.testing.expect(std.mem.find(u8, src, "scale(4607182418800017400.0)") != null);
        try std.testing.expectEqual(
            @as(f64, 4607182418800017408),
            try std.fmt.parseFloat(f64, "4607182418800017400.0"),
        );
        // `0.0 * k` would fold the contribution away entirely, which is why the
        // multiplicand here is a probe: the literal has to reach the device.
    }

    test "codegen: §3.2 the three sites that impose the 32-bit integer width agree" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module w(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter integer big = 2147483647 + 1;
            \\  parameter integer chained = big + 1;
            \\  localparam integer sh = 1 << 31;
            \\  analog begin
            \\    I(p, n) <+ V(p, n) * (big + 1);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        // Site 1, `fold.binary`: a §4.2 constant expression, folded before the
        // Model field is written. 2^31 is one step past the top of §3.2's range.
        try std.testing.expect(std.mem.find(u8, src, "big: i64 = -2147483648") != null);
        // §4.2.11 `<<` at the same width: `1 << 31` is the sign bit, not 2^31.
        try std.testing.expect(std.mem.find(u8, src, "sh: i64 = -2147483648") != null);
        // Site 2, `analysis.foldConst`: a §6.3.4 default over another parameter,
        // folded for the field initializer and re-emitted in `derive` for the
        // overridden case. -2^31 + 1, so the two folds have to agree on -2^31 first.
        try std.testing.expect(std.mem.find(u8, src, "chained: i64 = -2147483647") != null);
        try std.testing.expect(std.mem.find(u8, src, "model.chained = @as(i32, @truncate(") != null);
        // Site 3, `codegen.intBin32`: the device. `+%` is the 64-bit wrap that keeps
        // the add from panicking; the truncation is §3.2's width. The left operand
        // is a PARAMETER, so neither fold can reach it and the wrap has to survive
        // as emitted code, which is the site this half of the test is about.
        try std.testing.expect(std.mem.find(u8, src, "@as(i32, @truncate(((@as(i64, model.big)) +% (@as(i64, 1)))))") != null);
    }

    test "codegen: a unit whose target is defined in one arm returns a VALUE, not undefined" {
        var h: Harness = undefined;
        // §4.5 the operator's input unit is sliced from the argument, which here is
        // only defined on the taken arm. Returning `undefined` from the other one is
        // undefined behavior in the device AND silently corrupts the operator's
        // history, because `updateState` pushes whatever comes back.
        // The condition is a §3.4 PARAMETER, which §5.8.1 licenses (a `constant_
        // primary` cannot move mid-analysis, so the operator never misses a step)
        // while `elabConst` still refuses to fold it away (a model card overrides
        // it). So the diamond is real and the operator is legal. A probe condition
        // here would be E0514.
        try Harness.run(std.testing.allocator,
            \\module g(p, n, c);
            \\  inout p, n, c;
            \\  electrical p, n, c;
            \\  parameter real en = 1.0;
            \\  analog begin
            \\    if (en > 0.5)
            \\      I(p, n) <+ transition(V(p, n), 0, 1n, 1n);
            \\    else
            \\      I(p, n) <+ 0.0;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        const at = std.mem.find(u8, src, "fn g__common__core(").?;
        // `"\n}\n"`, not `"\n}"`: the core's return type is an anonymous struct
        // written into the signature, and it closes with `\n} {`.
        const end = std.mem.findPos(u8, src, at, "\n}\n").?;
        const body = src[at..end];
        // Hoisted slots of one mask share one `var h0: [n]zOf(...) = undefined`, so
        // the guarantee is two facts: the array is exactly as long as the number of
        // zero-seeds, and every seed writes `S.con(0.0)`. The only hoists are the
        // two returned fields (the one-arm operator input and the contribution
        // phi); every other slot is a `const` at its definition (`probeBody`).
        try std.testing.expect(std.mem.find(u8, body, "    var h0: [2]zOf(S, 0x3) = undefined;") != null);
        var hoists: usize = 0;
        var it = std.mem.splitScalar(u8, body, '\n');
        while (it.next()) |line| {
            if (!std.mem.startsWith(u8, line, "    h0[")) continue;
            hoists += 1;
            try std.testing.expect(std.mem.endsWith(u8, line, "= zTo(S, 0x3, S.con(0.0));"));
        }
        try std.testing.expectEqual(@as(usize, 2), hoists);
    }

    test "codegen: §4.5.8/§4.5.9 an omitted rate argument copies the one that was given" {
        // §4.5.8: "If only a positive rise_time value is specified, the simulator
        // uses it for both rise and fall times." §4.5.9: max_neg_slew_rate "defaults
        // to the opposite of the max_pos_slew_rate."
        //
        // A neutral default (`fall = 0.0`, `max_neg = 1e300`) would make the short
        // spelling of each operator differ from the long one with the same number.
        //
        // Asserted on the emitted call rather than by diffing the two spellings,
        // because `slew(x, 2e8, -2e8)` renders `@abs(-2e8)` and the short form
        // renders `@abs(2e8)`: the same limit, different text.
        const cases = [_]struct { call: []const u8, want: []const u8 }{
            .{
                // §4.5.8 passes rise and fall separately, so the copy is the same
                // number in the last two argument positions.
                //
                // `0.0000000022`, not `0.0000000022000000000000003`: `2.2n` is one
                // `parseFloat` of `2.2e-9`, not `2.2 * 1e-9` (1 ulp apart; see
                // lexer.zig's "§2.6.2 a scale factor rounds ONCE" test).
                .call = "transition(V(p, n), 0, 2.2n)",
                .want = "0.0000000022, 0.0000000022)",
            },
            .{
                .call = "slew(V(p, n), 2e8)",
                .want = "sim.dt, 200000000.0, @abs(200000000.0))",
            },
        };
        for (cases) |c| {
            const src = try std.testing.allocator.print(
                \\module m(p, n);
                \\  inout p, n;
                \\  electrical p, n;
                \\  analog I(p, n) <+ {s};
                \\endmodule
            , .{c.call});
            defer std.testing.allocator.free(src);

            var h: Harness = undefined;
            try Harness.run(std.testing.allocator, src, &h);
            defer h.deinit();
            const out = try h.gen(std.testing.allocator);

            std.testing.expect(std.mem.find(u8, out, c.want) != null) catch |e| {
                std.debug.print("{s}: expected to emit `{s}`\n", .{ c.call, c.want });
                return e;
            };
        }
    }

    test "codegen: §5.9.1 a short-circuit loop condition still reaches the loop's branch" {
        // §4.2.7 `&&` splits its expression across blocks, so after lowering a
        // `while` condition the current block is the short-circuit join, not the
        // loop header. A loop branch placed in the header strands the rhs and join
        // blocks: their slots are declared but never assigned, and the loop
        // branches on an `undefined` local.
        //
        // Asserted structurally, not on one temporary's name: every declared slot
        // must be written somewhere in the body.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module w(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  analog begin : body
            \\    real x, y; integer i;
            \\    x = 1e6; y = V(p, n); i = 0;
            \\    while ((i <= 4) && (abs(y - x) > 1e-12)) begin
            \\      x = y;
            \\      y = 2.0 * y + 1.0;
            \\      i = i + 1;
            \\    end
            \\    I(p, n) <+ y;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        // The rhs of the `&&` is emitted.
        try std.testing.expect(std.mem.find(u8, src, "zAbs(S, ") != null);

        // The model's own slots, past the file-scope helpers.
        var it = std.mem.splitScalar(u8, src[std.mem.find(u8, src, "// ---- the model, in one declaration ----").?..], '\n');
        while (it.next()) |line| {
            const decl = std.mem.trimStart(u8, line, " ");
            if (!std.mem.startsWith(u8, decl, "var t")) continue;
            const name = decl[4 .. std.mem.findScalar(u8, decl, ':') orelse continue];
            var buf: [32]u8 = undefined;
            const store = try std.mem.print(&buf, "{s} = ", .{name});
            std.testing.expect(std.mem.find(u8, src, store) != null) catch |e| {
                std.debug.print("slot `{s}` is declared but never assigned\n", .{name});
                return e;
            };
        }
    }

    test "codegen: §4.5.7 a delay computed from parameters renders as an expression over `model`" {
        // `td = len * sqrt(l * c)` is how every transmission line in the wild
        // spells its delay (devices/models/lossy_tline.va:135,
        // coupled_tlines.va:110). It is neither a literal nor a bare parameter, so
        // `f64Expr` must render it as an expression, never an `@compileError`
        // pasted into one.
        //
        // §4.5.7 permits it: `absdelay(input, td [, maxdelay])` takes td as an
        // analog_expression, and with no maxdelay "the value of td when the
        // absdelay() is first evaluated shall be used", which for an expression
        // over parameters is its value at every evaluation.
        //
        // Also pins the ASSIGNMENT: `td` is a `real` variable, not a parameter, so
        // this only works because the walk runs on SSA values rather than on names.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module tl(p, n);
            \\  inout p, n;
            \\  electrical p, n;
            \\  parameter real len = 1.0 from (0:inf);
            \\  parameter real l = 250e-9 from (0:inf);
            \\  parameter real c = 100e-12 from (0:inf);
            \\  real td;
            \\  analog begin
            \\    td = len * sqrt(l * c);
            \\    I(p, n) <+ absdelay(V(p, n), td);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        try std.testing.expect(std.mem.find(
            u8,
            src,
            "sim.dt, (model.len) * (@sqrt((model.l) * (model.c))))",
        ) != null);
        try std.testing.expect(std.mem.find(u8, src, "@compileError") == null);
    }

    test "codegen: §5.6.5 a zero-short switch branch emits a collapse hook" {
        // diode.va's access-resistance idiom: rs > 0 selects a real resistor,
        // rs == 0 a retained 0 V short that ngspice would collapse at setup
        // (DIOsetup: posPrimeNode = posNode).
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module d(a, c);
            \\  inout a, c;
            \\  electrical a, c, ai;
            \\  parameter real rs = 0.0 from [0:inf);
            \\  branch (a, ai) rsb;
            \\  analog begin
            \\    I(ai, c) <+ 1e-3 * V(ai, c);
            \\    if (rs > 0.0) I(rsb) <+ V(rsb) / rs;
            \\    else          V(rsb) <+ 0.0;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "pub fn collapse(comptime S: type, model: *const Model, inst: *const Instance) [n_u]?u8",
        ) != null);
        // The internal node AND the branch-flow unknown both alias onto the port,
        // so the pair's stamps land on one slot and cancel.
        //
        // Asserted through the union-find emission, which handles chained shorts
        // (BSIM4 rgateMod=0 retains V(g,gm) and V(gm,gi), sharing gm; see
        // `collapse`'s doc comment). `ai` is resolved by the `if (r != u)` loop
        // over every unknown, so it is not written by name; the branch-flow row
        // is, because it is not a union member.
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "zCollapseUnion(&parent, @intFromEnum(U.ai), @intFromEnum(U.a));",
        ) != null);
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "out[@intFromEnum(U.flowZ28aZ2caiZ29)] = zCollapseRoot(&parent, @intFromEnum(U.a));",
        ) != null);
        // Min-index root, so `a` (a port at index 0) is the target and never a
        // mover. That ordering is what lets the host resolve aliases ascending.
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "if (ra < rb) parent[rb] = ra else parent[ra] = rb;",
        ) != null);
    }

    test "codegen: table capture is isolated from topology queries" {
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module d(a, c);
            \\  inout a, c; electrical a, c, ai;
            \\  parameter real rs = 0.0 from [0:inf);
            \\  branch (a, ai) rsb;
            \\  real xs[0:1], ys[0:1];
            \\  analog begin
            \\    if (rs > 0.0) I(rsb) <+ V(rsb) / rs;
            \\    else V(rsb) <+ 0.0;
            \\    xs[0]=0; xs[1]=1; ys[0]=$abstime; ys[1]=$abstime+2;
            \\    I(ai, c) <+ $table_model(0.5,xs,ys);
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        const collapse = src[std.mem.find(u8, src, "pub fn collapse(") orelse return error.NoCollapse ..];
        try std.testing.expect(std.mem.find(u8, collapse, "var pin = inst.*;") != null);
        try std.testing.expect(std.mem.find(u8, collapse, "core(S, xr, model, &pin, .{})") != null);
    }

    test "codegen: no collapse hook without the zero-short pattern" {
        // An unconditional resistor has nothing to collapse.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator, resistor_va, &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "pub fn collapse") == null);
    }

    test "codegen: a zero short still collapses after if-conversion makes its join a select" {
        // The diode idiom again, through ifconv as root.zig runs it. Both arms
        // are pure, so the diamond converts and the retention flag and the
        // potential accumulator become `select`s: `select(rs > 0, 0, 1)` and
        // `select(rs > 0, 0, 0)`. `zeroOnEveryPath` must see through them, or
        // whether a model collapses would hang on whether ifconv converted it.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module d(a, c);
            \\  inout a, c;
            \\  electrical a, c, ai;
            \\  parameter real rs = 0.0 from [0:inf);
            \\  branch (a, ai) rsb;
            \\  analog begin
            \\    I(ai, c) <+ 1e-3 * V(ai, c);
            \\    if (rs > 0.0) I(rsb) <+ V(rsb) / rs;
            \\    else          V(rsb) <+ 0.0;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        try std.testing.expect(try ifconv.run(h.arena_state.allocator(), &h.mir) >= 1);
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "pub fn collapse(") != null);
        try std.testing.expect(std.mem.find(
            u8,
            src,
            "zCollapseUnion(&parent, @intFromEnum(U.ai), @intFromEnum(U.a));",
        ) != null);
    }

    test "codegen: an OBSERVED zero short is not collapsed" {
        // §5.4.2 `I(rsb)` reads the branch-flow unknown, which `collapse` would
        // alias onto a node voltage: the model would read V(a), not its current.
        // Here the arm holds `sqrt`, so ifconv keeps the phi form.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module d(a, c);
            \\  inout a, c;
            \\  electrical a, c, ai;
            \\  parameter real rs = 0.0 from [0:inf);
            \\  branch (a, ai) rsb;
            \\  real seen;
            \\  analog begin
            \\    seen = I(rsb);
            \\    I(ai, c) <+ 1e-3 * V(ai, c) + 0.0 * seen;
            \\    if (rs > 0.0) I(rsb) <+ V(rsb) / rs + 0.0 * sqrt(rs);
            \\    else          V(rsb) <+ 0.0;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "pub fn collapse") == null);
    }

    test "codegen: an x-steered zero short is NOT collapsed" {
        // The guard reads a probe, so which arm is retained changes per
        // evaluation; a build-time alias would be a lie. `buildFree` refuses it.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module d(a, c);
            \\  inout a, c;
            \\  electrical a, c, ai;
            \\  analog begin
            \\    I(ai, c) <+ 1e-3 * V(ai, c);
            \\    if (V(a, c) > 1.0) I(a, ai) <+ 1e3 * V(a, ai);
            \\    else               V(a, ai) <+ 0.0;
            \\  end
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);
        try std.testing.expect(std.mem.find(u8, src, "pub fn collapse") == null);
    }

    test "codegen: §4.5 a control argument that is a solve result is E0515, not generated Zig" {
        // The other half: a control argument the CLAUSE makes constant and that
        // genuinely cannot be resolved must be a diagnostic at the `.va` line. An
        // `@compileError` pasted into an expression is not one: it reads as an
        // engine bug in generated code.
        //
        // §4.5.8's rise_time, not §4.5.7's td: Table 4-20 lists every one of
        // `transition`'s times among the CONSTANT expression arguments and
        // `absdelay`'s td among the DYNAMIC ones, so `absdelay(V(p,n), V(c))` is
        // legal and compiled (see `isDynCtrlArg` and
        // ch04_expressions/absdelay_td_frozen_without_maxdelay.va).
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module bad(p, n, c);
            \\  inout p, n, c;
            \\  electrical p, n, c;
            \\  analog I(p, n) <+ transition(V(p, n), 0, V(c));
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        var found = false;
        for (0..h.bag.count()) |i| {
            const e = h.bag.at(i);
            if (e.code != .E0515) continue;
            found = true;
            try std.testing.expectEqual(diag.Stage.codegen, e.stage);
            // A node probe has no instruction of its own to point at, which is what
            // `ctrl_tok`'s fallback to the operator call exists for.
            try std.testing.expect(e.span.end > e.span.start);
        }
        try std.testing.expect(found);
        // Refused as a whole unit: an `@compileError` statement that replaces the
        // body, never one pasted into the middle of an expression.
        try std.testing.expect(std.mem.find(u8, src, "\n    @compileError(\"LRM 4.5") != null);
        try std.testing.expect(std.mem.find(u8, src, "(@compileError") == null);
    }

    test "codegen: metadata control failure stays fatal with and without diagnostics" {
        // §4.5.14 permits first-use capture of a nonliteral constant argument.
        // A dynamic transition rise_time is unsupported, not invalid source.
        // Whatever its diagnostic, callers must never receive a success flag
        // because a later unit reset the per-body `fatal` field.
        for ([_]bool{ false, true }) |with_diags| {
            var h: Harness = undefined;
            try Harness.run(std.testing.allocator,
                \\module sampled(p, n, c);
                \\  inout p, n, c;
                \\  electrical p, n, c;
                \\  analog I(p,n) <+ transition(V(p,n), 0, V(c));
                \\endmodule
            , &h);
            defer h.deinit();
            const v = try proof.proveOpts(std.testing.allocator, &h.mir, &h.lowered, .{}, &h.bag);
            defer v.deinit(std.testing.allocator);
            try std.testing.expect(!h.bag.failed());
            const a = h.arena_state.allocator();
            var fatal = false;
            _ = try generate(a, a, &h.mir, &h.lowered, v, &fatal, .{
                .diags = if (with_diags) &h.bag else null,
            });
            try std.testing.expect(fatal);
            try std.testing.expectEqual(with_diags, h.bag.failed());
        }
    }

    test "codegen: §12.32.3 an unregistered system function is W0852 and a host call, not a refusal" {
        // The other side of the test above, and the distinction the whole W0852
        // ruling rests on: an unregistered `$name` has no value the LRM fixes, so
        // the unit must still compile, but not silently. §12.32.3's own sampnhold
        // listing, which is what puts one of these in a contribution.
        var h: Harness = undefined;
        try Harness.run(std.testing.allocator,
            \\module sampnhold(out, in);
            \\  inout out, in;
            \\  electrical out, in;
            \\  parameter real period = 1e-3;
            \\  analog V(out) <+ $sampler(V(in), period);
            \\endmodule
        , &h);
        defer h.deinit();
        const src = try h.gen(std.testing.allocator);

        var found = false;
        for (0..h.bag.count()) |i| {
            const e = h.bag.at(i);
            if (e.code != .W0852) continue;
            found = true;
            try std.testing.expectEqual(diag.Stage.codegen, e.stage);
            try std.testing.expect(e.span.end > e.span.start); // the call, not the file
        }
        try std.testing.expect(found);
        // Compiles: a refusal here would reject legal source (§2.8.3).
        try std.testing.expect(std.mem.find(u8, src, "@compileError") == null);

        // §2.8.3/§12.32: the name is exported for a host to bind, not answered
        // here with a substitute value.
        try std.testing.expect(std.mem.find(u8, src, "pub const systf_calls") != null);
        try std.testing.expect(std.mem.find(u8, src, ".{ .name = \"$sampler\", .tok = ") != null);
        try std.testing.expect(std.mem.find(u8, src, "inst.systf.?") != null);
    }

    test "codegen: Instance carries a `systf` slot only when a `$name` is left to the host" {
        // The slot is 8 bytes on every instance, so a device that resolves
