    test "§12.11: a continuous assignment's delays, derived where not written, and the counts refused" {
        var h: run.Harness = undefined;
        try h.init(
            \\`timescale 1ns/1ns
            \\module d;
            \\  reg a;
            \\  wire w;
            \\  assign #(2, 7) w = a;
            \\endmodule
        );
        defer h.deinit();
        const assigns = vpi_iterate(code.vpiContAssign, vpi_handle_by_name("d", null));
        const ca = vpi_scan(assigns) orelse return error.TestUnexpectedResult;
        _ = vpi_free_object(assigns);
        var da: [3]callback.Time = undefined;
        var dl: delays.Delay = .{ .da = &da, .no_of_delays = 3, .time_type = callback.vpiScaledRealTime, .mtm_flag = 0, .append_flag = 0, .pulsere_flag = 0 };
        delays.vpi_get_delays(ca, &dl);
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
        // Rise and fall as written; turn-off is IEEE 1364 §7.14's min(rise, fall).
        for (da, [_]f64{ 2, 7, 2 }) |t, want| try std.testing.expectEqual(want, t.real);
        for ([_]c_int{ 0, 4 }) |n| {
            dl.no_of_delays = n;
            delays.vpi_get_delays(ca, &dl);
            try std.testing.expectEqual(vpiError, vpi_chk_error(null));
        }
    }

    test "§12.29: vpi_put_delays reaches the engine driver of a gate in a generated instance" {
        // The instance's model scope (1) is not its engine scope: the loop
        // iteration `b[0]` is an engine scope of its own between it and `top`.
        var h: run.Harness = undefined;
        try h.init(
            \\`timescale 1ns/1ns
            \\module leaf; reg a; wire y; buf g(y, a); endmodule
            \\module top;
            \\  genvar i;
            \\  generate for (i = 0; i < 1; i = i + 1) begin : b
            \\    leaf u();
            \\  end endgenerate
            \\endmodule
        );
        defer h.deinit();
        const g = vpi_handle_by_name("top.b[0].u.g", null) orelse return error.TestUnexpectedResult;
        var da = [2]callback.Time{
            .{ .type = callback.vpiSimTime, .high = 0, .low = 3, .real = 0 },
            .{ .type = callback.vpiSimTime, .high = 0, .low = 4, .real = 0 },
        };
        var dl: delays.Delay = .{ .da = &da, .no_of_delays = 2, .time_type = callback.vpiSimTime, .mtm_flag = 0, .append_flag = 0, .pulsere_flag = 0 };
        delays.vpi_put_delays(g, &dl);
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
        // The one driver the gate became: rise 3, fall 4, turn-off min(3, 4).
        const tok = (asObj(g) orelse return error.TestUnexpectedResult).src_tok;
        var hits: usize = 0;
        for (h.run.drivers) |drv| {
            if (drv.tok != tok) continue;
            hits += 1;
            try std.testing.expect(drv.delay.present);
            try std.testing.expectEqual(@as(u64, 3), drv.delay.rise);
            try std.testing.expectEqual(@as(u64, 4), drv.delay.fall);
            try std.testing.expectEqual(@as(u64, 3), drv.delay.off);
        }
        try std.testing.expectEqual(@as(usize, 1), hits);
    }

    test "§12.30/IEEE 1364 §19.8: a scaled time is in the unit of the object's own module, past a generate" {
        // `leaf` is in microseconds, `top` in nanoseconds, and the tick is the
        // finest precision, 1 ns. `u`'s model scope (1) is the engine's loop
        // iteration `b[0]`, a scope of `top`'s, so only the engine scope finds
        // `leaf`'s unit: 2 us is 2000 ticks, where `top`'s unit would make it 2.
        var h: run.Harness = undefined;
        try h.init(
            \\`timescale 1us/1ns
            \\module leaf; reg a; endmodule
            \\`timescale 1ns/1ns
            \\module top;
            \\  genvar i;
            \\  generate for (i = 0; i < 1; i = i + 1) begin : b
            \\    leaf u();
            \\  end endgenerate
            \\endmodule
        );
        defer h.deinit();
        const a = vpi_handle_by_name("top.b[0].u.a", null) orelse return error.TestUnexpectedResult;
        const two: callback.Time = .{ .type = callback.vpiScaledRealTime, .high = 0, .low = 0, .real = 2 };
        try std.testing.expectEqual(@as(?u64, 2000), run.ticksOf(two, a));
    }

    /// The message of the error the previous call recorded; "" for none.
    fn lastMessage() []const u8 {
        var info: ErrorInfo = undefined;
        if (vpi_chk_error(&info) == 0) return "";
        return std.mem.span(info.message);
    }

    /// The port of instance `inst` named `name`, or null.
    fn portNamed(inst: vpiHandle, name: []const u8) vpiHandle {
        const itr = vpi_iterate(vpiPort, inst);
        var found: vpiHandle = null;
        while (vpi_scan(itr)) |p| {
            if (found == null and std.mem.eql(u8, std.mem.span(vpi_get_str(vpiName, p)), name)) found = p;
        }
        return found;
    }

    test "IEEE 1364-2005 §1.7 Annex G: a name VerA does not answer is refused by that name" {
        var h: run.Harness = undefined;
        try h.init(
            \\module m(a);
            \\  input a;
            \\  wire w;
            \\endmodule
        );
        defer h.deinit();
        const m = vpi_handle_by_name("m", null) orelse return error.TestUnexpectedResult;
        const a = portNamed(m, "a") orelse return error.TestUnexpectedResult;
        // A property (vpi_get and vpi_get_str), an object or relationship
        // (vpi_handle and vpi_iterate) and a callback reason, each Annex G's.
        try std.testing.expectEqual(vpiUndefined, vpi_get(8, m));
        try std.testing.expect(std.mem.find(u8, lastMessage(), "vpiCellInstance") != null);
        try std.testing.expect(vpi_get_str(15, m) == null);
        try std.testing.expect(std.mem.find(u8, lastMessage(), "vpiDefFile") != null);
        try std.testing.expect(vpi_handle(80, a) == null);
        try std.testing.expect(std.mem.find(u8, lastMessage(), "vpiLowConn") != null);
        try std.testing.expect(vpi_iterate(127, m) == null);
        try std.testing.expect(std.mem.find(u8, lastMessage(), "vpiTaskFunc") != null);
        const save: callback.CbData = .{ .reason = 15, .cb_rtn = noCb, .obj = null, .time = null, .value = null, .index = 0, .user_data = null };
        try std.testing.expect(callback.vpi_register_cb(&save) == null);
        try std.testing.expect(std.mem.find(u8, lastMessage(), "cbStartOfSave") != null);
        // The legal neighbours on the same objects answer, with no error.
        try std.testing.expectEqual(@as(c_int, 1), vpi_get(vpiTopModule, m));
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
        try std.testing.expect(vpi_iterate(code.vpiTask, m) == null);
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
    }

    fn noCb(_: *callback.CbData) callconv(.c) c_int {
        return 0;
    }

    test "§12.22: vpi_handle_multi(vpiInterModPath) is one path per port pair, holding its delays" {
        var h: run.Harness = undefined;
        try h.init(
            \\`timescale 1ns/1ns
            \\module gate(a, y, w);
            \\  input a; output y; input [1:0] w;
            \\  buf (y, a);
            \\endmodule
            \\module top;
            \\  reg r; wire n, z; wire [1:0] v;
            \\  gate u1(r, n, v);
            \\  gate u2(n, z, v);
            \\endmodule
        );
        defer h.deinit();
        const y1 = portNamed(vpi_handle_by_name("top.u1", null), "y") orelse return error.TestUnexpectedResult;
        const a2 = portNamed(vpi_handle_by_name("top.u2", null), "a") orelse return error.TestUnexpectedResult;
        const w2 = portNamed(vpi_handle_by_name("top.u2", null), "w") orelse return error.TestUnexpectedResult;
        const multi = systf.vpi_handle_multi;
        const imp = systf.vpiInterModPath;

        const p = multi(imp, y1, a2) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
        try std.testing.expectEqual(imp, vpi_get(vpiType, p));
        try std.testing.expectEqualStrings("vpiInterModPath", std.mem.span(vpi_get_str(vpiType, p)));
        try std.testing.expectEqual(@as(c_int, 1), vpi_compare_objects(p, multi(imp, y1, a2)));
        // IEEE 1364-2005 §26.6.16: ->> its ports, the output first.
        const itr = vpi_iterate(vpiPort, p);
        try std.testing.expectEqual(@as(c_int, 1), vpi_compare_objects(vpi_scan(itr), y1));
        try std.testing.expectEqual(@as(c_int, 1), vpi_compare_objects(vpi_scan(itr), a2));
        try std.testing.expect(vpi_scan(itr) == null);
        try std.testing.expect(vpi_handle(vpiModule, p) == null);
        try std.testing.expectEqual(vpiError, vpi_chk_error(null));

        // No put yet: no delay. Then two, turn-off §7.14's min(rise, fall).
        var da: [9]callback.Time = undefined;
        var dl: delays.Delay = .{ .da = &da, .no_of_delays = 3, .time_type = callback.vpiScaledRealTime, .mtm_flag = 0, .append_flag = 0, .pulsere_flag = 0 };
        delays.vpi_get_delays(p, &dl);
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
        for (da[0..3]) |t| try std.testing.expectEqual(@as(f64, 0), t.real);
        const before = h.bag.count();
        da[0] = .{ .type = callback.vpiScaledRealTime, .high = 0, .low = 0, .real = 4 };
        da[1] = .{ .type = callback.vpiScaledRealTime, .high = 0, .low = 0, .real = 2 };
        dl.no_of_delays = 2;
        delays.vpi_put_delays(p, &dl);
        try std.testing.expectEqual(@as(c_int, 0), vpi_chk_error(null));
        dl.no_of_delays = 3;
        delays.vpi_get_delays(p, &dl);
        for (da[0..3], [_]f64{ 4, 2, 2 }) |t, want| try std.testing.expectEqual(want, t.real);
        // The put is not silent: the run's diagnostics say no simulation applies it.
        try std.testing.expectEqual(before + 1, h.bag.count());
        try std.testing.expectEqual(vera.diag.Code.W0251, h.bag.at(before).code);
        // Read in ticks: 4 ns is 4 ticks of the 1 ns precision.
        dl.time_type = callback.vpiSimTime;
        delays.vpi_get_delays(p, &dl);
        try std.testing.expectEqual(@as(c_uint, 4), da[0].low);
        // Pulse limits other than the delay are refused, not dropped.
        dl.time_type = callback.vpiScaledRealTime;
        dl.pulsere_flag = 1;
        for (&da, 0..) |*t, k| t.* = .{ .type = callback.vpiScaledRealTime, .high = 0, .low = 0, .real = @floatFromInt(k) };
        delays.vpi_put_delays(p, &dl);
        try std.testing.expectEqual(vpiError, vpi_chk_error(null));

        // Not a path: an input first, one port twice, two sizes, a non-port.
        try std.testing.expect(multi(imp, a2, y1) == null);
        try std.testing.expect(std.mem.find(u8, lastMessage(), "not an output or inout port") != null);
        try std.testing.expect(multi(imp, y1, y1) == null);
        try std.testing.expectEqual(vpiError, vpi_chk_error(null));
        try std.testing.expect(multi(imp, y1, w2) == null);
        try std.testing.expect(std.mem.find(u8, lastMessage(), "same size") != null);
        try std.testing.expect(multi(imp, vpi_handle_by_name("top.n", null), a2) == null);
        try std.testing.expectEqual(vpiError, vpi_chk_error(null));
    }

    /// True for a decl name spelled as a vpi_user.h constant: `vpi*`, `cb*` or
    /// VerA's `acb*`, with no underscore (that is `vpi_get` and the routines).
    fn isHeaderSpelling(comptime name: []const u8) bool {
        const prefixed = std.mem.startsWith(u8, name, "vpi") or std.mem.startsWith(u8, name, "cb") or
            std.mem.startsWith(u8, name, "acb");
        return prefixed and std.mem.findScalar(u8, name, '_') == null;
    }

    test "every vpi_user.h constant the Zig side spells has the header's value" {
        // The header's integer macros: `#define NAME <int>`, decimal or `0x` hex,
        // signed, at most one pair of parentheses. Aliases (`vpiSysFuncInt`),
        // include guards and the `PLI_*` macros are not integers and are skipped.
        const gpa = std.testing.allocator;
        var macros: std.StringHashMapUnmanaged(c_int) = .empty;
        defer macros.deinit(gpa);
        const header = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, @import("repo_options").repo_root ++ "/src/vpi/vpi_user.h", gpa, .unlimited);
        defer gpa.free(header);
        var lines = std.mem.splitScalar(u8, header, '\n');
        while (lines.next()) |line| {
            var words = std.mem.tokenizeAny(u8, line, " \t\r");
            if (!std.mem.eql(u8, words.next() orelse continue, "#define")) continue;
            const name = words.next() orelse continue;
            const text = std.mem.trim(u8, words.next() orelse continue, "()");
            const v = std.fmt.parseInt(c_int, text, 0) catch continue;
            const gop = try macros.getOrPut(gpa, name);
            // One name, one number: a second `#define` must agree with the first.
            if (gop.found_existing) try std.testing.expectEqual(gop.value_ptr.*, v);
            gop.value_ptr.* = v;
        }
        // The parser, against values read off the header by hand: line 124
        // `vpiModule 32`, line 449 `vpiUndefined -1`, line 606 `vpiSupplyDrive
        // 0x80` = 128, and Annex G's edge masks, whose unions are the header's own
        // `vpiPosedge 0x0D` and `vpiNegedge 0x32` = 50.
        try std.testing.expectEqual(@as(?c_int, 32), macros.get("vpiModule"));
        try std.testing.expectEqual(@as(?c_int, -1), macros.get("vpiUndefined"));
        try std.testing.expectEqual(@as(?c_int, 128), macros.get("vpiSupplyDrive"));
        try std.testing.expectEqual(macros.get("vpiPosedge").?, macros.get("vpiEdge01").? | macros.get("vpiEdge0x").? | macros.get("vpiEdgex1").?);
        try std.testing.expectEqual(@as(?c_int, 50), macros.get("vpiNegedge"));
        try std.testing.expectEqual(macros.get("vpiNegedge").?, macros.get("vpiEdge10").? | macros.get("vpiEdge1x").? | macros.get("vpiEdgex0").?);

        // Every `pub` c_int the routines spell as a header name (Zig 0.17
        // reflection sees `pub` decls only). A `vpi*`/`cb*` name the header does
        // not define is an error too: VerA's own numbers in that namespace
        // (`vpiQuantity`, `vpiExpStrVal`) are in the header. The `acb*` analog
        // reasons are not: tests/fixtures/ch12_vpi_routines/p03_vpi_analog.h
        // defines them, outside this module's directory.
        @setEvalBranchQuota(100_000);
        var checked: usize = 0;
        inline for (.{ root, code, callback, value, systf, run, property }) |file| {
            inline for (comptime std.meta.declarations(file)) |name| {
                if (comptime !isHeaderSpelling(name)) continue;
                if (comptime @TypeOf(@field(file, name)) != c_int) continue;
                if (macros.get(name)) |want| {
                    std.testing.expectEqual(want, @field(file, name)) catch |e| {
                        std.debug.print("{s}: vpi_user.h says {d}\n", .{ name, want });
                        return e;
                    };
                    checked += 1;
                } else if (comptime !std.mem.startsWith(u8, name, "acb")) {
                    std.debug.print("{s} is not a vpi_user.h integer macro\n", .{name});
                    return error.TestUnexpectedResult;
                }
            }
        }
        // 2026-10-17: 345 (the seven files' 351 top-level `pub` c_int decls less
        // the six `acb*`). A floor, so a reflection that finds nothing cannot pass.
        try std.testing.expect(checked >= 345);
    }

    // ---------------------------------------------------------------------------
    // Corner cases of root.zig's error status and delays.zig's puts, over
    // digital designs run through `run.Harness`.
    // ---------------------------------------------------------------------------

    const Time = callback.Time;

    fn scaled(v: f64) Time {
        return .{ .type = callback.vpiScaledRealTime, .high = 0, .low = 0, .real = v };
    }

    fn ticks(n: u32) Time {
        return .{ .type = callback.vpiSimTime, .high = 0, .low = n, .real = 0 };
    }

    fn delayOf(da: []Time, n: c_int, time_type: c_int) delays.Delay {
        return .{ .da = da.ptr, .no_of_delays = n, .time_type = time_type, .mtm_flag = 0, .append_flag = 0, .pulsere_flag = 0 };
    }

    test "§12.2: a message past Figure 12-1's buffer is truncated and still NUL-terminated" {
        root.close();
        const long: [600]u8 = @splat('x');
        root.fail("LONG", "{s}", .{&long});
        var info: root.ErrorInfo = undefined;
        try std.testing.expectEqual(root.vpiError, root.vpi_chk_error(&info));
        try std.testing.expectEqual(@as(usize, 511), std.mem.span(info.message).len);
        try std.testing.expectEqualStrings("LONG", std.mem.span(info.code));
        // vpi_chk_error leaves the status; the next routine clears it.
        try std.testing.expectEqual(root.vpiError, root.vpi_chk_error(null));
        try std.testing.expectEqual(@as(c_int, 0), root.vpi_compare_objects(null, null));
        try std.testing.expectEqual(root.vpiError, root.vpi_chk_error(&info));
        try std.testing.expectEqualStrings("BADHANDLE", std.mem.span(info.code));
        root.clearError();
        try std.testing.expectEqual(@as(c_int, 0), root.vpi_chk_error(&info));
        try std.testing.expect(info.message == null and info.code == null);
    }

    test "§12.29: a delay put in ticks reads back in the module's time unit" {
        var h: run.Harness = undefined;
        try h.init(
            \\`timescale 1us/1ns
            \\module top; reg a; wire y; buf g(y, a); endmodule
        );
        defer h.deinit();
        const g = handle.vpi_handle_by_name("top.g", null) orelse return error.TestUnexpectedResult;
        // 2000 and 3000 ticks of the 1 ns precision: 2 and 3 us.
        var da = [3]Time{ ticks(2000), ticks(3000), ticks(0) };
        var dl = delayOf(&da, 2, callback.vpiSimTime);
        delays.vpi_put_delays(g, &dl);
        try std.testing.expectEqual(@as(c_int, 0), root.vpi_chk_error(null));
        dl = delayOf(&da, 3, callback.vpiScaledRealTime);
        delays.vpi_get_delays(g, &dl);
        try std.testing.expectEqual(@as(c_int, 0), root.vpi_chk_error(null));
        for (da, [_]f64{ 2, 3, 2 }) |t, want| try std.testing.expectEqual(want, t.real);
    }

    /// The `n`th object (from 0) `vpi_iterate(tag, scope)` yields.
    fn nth(tag: c_int, scope: root.vpiHandle, n: usize) ?*anyopaque {
        const itr = iterate.vpi_iterate(tag, scope);
        defer _ = root.vpi_free_object(itr);
        for (0..n) |_| _ = iterate.vpi_scan(itr);
        return iterate.vpi_scan(itr);
    }

    test "§12.29: a delay that is NaN, infinite or negative is refused, and the held one stays" {
        var h: run.Harness = undefined;
        try h.init(
            \\`timescale 1ns/1ns
            \\module leaf(a, y); input a; output y; buf (y, a);
            \\  specify (a => y) = 5; endspecify
            \\endmodule
            \\module top; reg r; wire n, z; leaf first_cell(r, n); leaf second_cell(n, z); endmodule
        );
        defer h.deinit();
        const first_cell = handle.vpi_handle_by_name("top.first_cell", null);
        const second_cell = handle.vpi_handle_by_name("top.second_cell", null);
        const path = nth(code.vpiModPath, first_cell, 0) orelse return error.TestUnexpectedResult;
        // first_cell's output `y` into second_cell's input `a`.
        const imp = systf.vpi_handle_multi(systf.vpiInterModPath, nth(root.vpiPort, first_cell, 1), nth(root.vpiPort, second_cell, 0)) orelse return error.TestUnexpectedResult;
        var da: [3]Time = undefined;
        for ([_]f64{ std.math.nan(f64), std.math.inf(f64), -1 }) |bad| {
            // A module path: one delay. An inter-module path: two.
            da = .{ scaled(bad), scaled(bad), scaled(bad) };
            var dl = delayOf(&da, 1, callback.vpiScaledRealTime);
            delays.vpi_put_delays(path, &dl);
            try std.testing.expectEqual(root.vpiError, root.vpi_chk_error(null));
            dl.no_of_delays = 2;
            delays.vpi_put_delays(imp, &dl);
            try std.testing.expectEqual(root.vpiError, root.vpi_chk_error(null));
        }
        var dl = delayOf(&da, 1, callback.vpiScaledRealTime);
        delays.vpi_get_delays(path, &dl);
        try std.testing.expectEqual(@as(f64, 5), da[0].real);
        dl.no_of_delays = 2;
        delays.vpi_get_delays(imp, &dl);
        try std.testing.expectEqual(@as(f64, 0), da[0].real);
    }
};

pub const exhaustive_tests = struct {
    //! Stage-boundary exhaustiveness guard: lib/ and src/ sources -> a failure for
    //! every `else =>` over a boundary enum whose line lacks `// else: <reason>`.
    //!
    //! It parses the real source with `std.zig.Ast`, because only the prong labels
    //! say which enum a switch is over.
    //!
    //! The portability guard is its sibling: lib/ and src/ ->
    //! a failure for every direct OS API (`os_apis`) outside `os_allowed` whose
    //! line lacks `// os: <reason>`. VerA builds for every target because no
    //! code, compiled or emitted, calls an OS but through `std`.

    const std = @import("std");
    const Io = std.Io;
    const ZigAst = std.zig.Ast;
    const Ast = @import("frontend").Ast;
    const Mir = @import("ir").Mir;
    const op = @import("ir").op;
    const repo_root = @import("repo_options").repo_root;

    /// The boundary enums, read from the real types so the registry cannot drift.
    /// A switch is attributed to the FIRST entry whose fields cover all its prong
    /// labels, so an enum whose names overlap an earlier one's comes after it.
    /// `token.Tag` (lexer to parser) is last: its `plus`/`int_literal` overlap
    /// UnaryOp and ExprTag, which keep those switches.
    const registry = [_]struct { name: []const u8, fields: []const []const u8 }{
        .{ .name = "Ast.ExprTag", .fields = @typeInfo(Ast.ExprTag).@"enum".field_names },
        .{ .name = "Ast.Stmt", .fields = @typeInfo(Ast.Stmt).@"union".field_names },
        .{ .name = "Ast.BinaryOp", .fields = @typeInfo(Ast.BinaryOp).@"enum".field_names },
        .{ .name = "Ast.UnaryOp", .fields = @typeInfo(Ast.UnaryOp).@"enum".field_names },
        .{ .name = "Ast.NetKind", .fields = @typeInfo(Ast.NetKind).@"enum".field_names },
        .{ .name = "Ast.GateKind", .fields = @typeInfo(Ast.GateKind).@"enum".field_names },
        .{ .name = "Ast.Direction", .fields = @typeInfo(Ast.Direction).@"enum".field_names },
        .{ .name = "Ast.Type", .fields = @typeInfo(Ast.Type).@"enum".field_names },
        .{ .name = "Mir.Opcode", .fields = @typeInfo(Mir.Opcode).@"enum".field_names },
        .{ .name = "Mir.OpClass", .fields = @typeInfo(Mir.OpClass).@"enum".field_names },
        .{ .name = "Mir.DefKind", .fields = @typeInfo(Mir.DefKind).@"enum".field_names },
        .{ .name = "op.OpKind", .fields = @typeInfo(op.OpKind).@"enum".field_names },
        // After OpKind: its `ddt`/`cross` overlap OpKind, which keeps those switches.
        .{ .name = "Mir.Callee", .fields = @typeInfo(Mir.Callee).@"enum".field_names },
        .{ .name = "Preprocessor.Directive", .fields = @typeInfo(@import("frontend").Preprocessor.Directive).@"enum".field_names },
        .{ .name = "token.Tag", .fields = @typeInfo(@import("frontend").token.Tag).@"enum".field_names },
    };

    fn has(fields: []const []const u8, s: []const u8) bool {
        for (fields) |f| if (std.mem.eql(u8, f, s)) return true;
        return false;
    }

    /// Prints every unannotated `else` on a boundary enum in one file, outside
    /// `test` blocks, and returns how many.
    fn scan(arena: std.mem.Allocator, path: []const u8, src: [:0]const u8) !usize {
        var tree = try ZigAst.parse(arena, src, .{ .mode = .zig });
        if (tree.errors.len != 0) {
            std.debug.print("{s}: does not parse\n", .{path});
            return error.ParseFailed;
        }
        // Enclosing scopes as token spans; the innermost fn names the site.
        const Span = struct { first: u32, last: u32, name: ?[]const u8 };
        var spans: std.ArrayList(Span) = .empty;
        var n_found: usize = 0;
        for (0..tree.nodes.len) |i| {
            const n: ZigAst.Node.Index = @fromBackingInt(@intCast(i));
            switch (tree.nodeTag(n)) {
                .fn_decl => {
                    var buf: [1]ZigAst.Node.Index = undefined;
                    const tok = tree.fullFnProto(&buf, n).?.name_token orelse continue;
                    try spans.append(arena, .{ .first = tree.firstToken(n), .last = tree.lastToken(n), .name = tree.tokenSlice(tok) });
                },
                .test_decl => try spans.append(arena, .{ .first = tree.firstToken(n), .last = tree.lastToken(n), .name = null }),
                else => {}, // else: only fn and test scopes name a site
            }
        }
        for (0..tree.nodes.len) |i| {
            const sw = tree.fullSwitch(@fromBackingInt(@intCast(i))) orelse continue;
            var else_tok: ?ZigAst.TokenIndex = null;
            var labels: std.ArrayList([]const u8) = .empty;
            for (sw.ast.cases) |c| {
                const case = tree.fullSwitchCase(c).?;
                if (case.ast.values.len == 0) else_tok = case.ast.arrow_token;
                for (case.ast.values) |v| if (tree.nodeTag(v) == .enum_literal)
                    try labels.append(arena, tree.tokenSlice(tree.nodeMainToken(v)));
            }
            const et = else_tok orelse continue;
            if (labels.items.len == 0) continue;
            const hit = for (registry) |r| {
                const all = for (labels.items) |l| {
                    if (!has(r.fields, l)) break false;
                } else true;
                if (all) break r.name;
            } else continue;
            const loc = tree.tokenLocation(0, et);
            if (std.mem.find(u8, src[loc.line_start..loc.line_end], "// else:") != null) continue;

            var in_test = false;
            var best: ?Span = null;
            for (spans.items) |s| {
                if (et < s.first or et > s.last) continue;
                if (s.name == null) in_test = true;
                if (s.name != null and (best == null or s.last - s.first < best.?.last - best.?.first)) best = s;
            }
            if (in_test) continue;
            const fn_name = if (best) |b| b.name.? else "-";
            std.debug.print(
                "{s}:{d}: `else =>` over {s} in {s}\n    fix: write the prongs out so the compiler checks them, " ++
                    "or put `// else: <reason>` on the else line\n",
                .{ path, loc.line + 1, hit, fn_name },
            );
            n_found += 1;
        }
        return n_found;
    }

    test "every `else` over a boundary enum is written out or annotated" {
        var arena_state: std.heap.ArenaAllocator = .init(std.heap.page_allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const io = std.testing.io;

        // One file's source, AST and scratch at a time: `scan` prints what it
        // finds before it returns, so nothing outlives the file.
        var file_state: std.heap.ArenaAllocator = .init(std.heap.page_allocator);
        defer file_state.deinit();
        var found: usize = 0;
        for ([_][]const u8{ "lib", "src" }) |sub| {
            const abs = try std.fs.path.join(arena, &.{ repo_root, sub });
            var dir = try Io.Dir.cwd().openDir(io, abs, .{ .iterate = true });
            defer dir.close(io);
            var w = try dir.walk(arena);
            while (try w.next(io)) |e| {
                if (e.kind != .file or !std.mem.endsWith(u8, e.path, ".zig")) continue;
                _ = file_state.reset(.retain_capacity);
                const fa = file_state.allocator();
                const src = try dir.readFileAllocOptions(io, e.path, fa, .limited(1 << 24), .of(u8), 0);
                found += try scan(fa, try std.fs.path.join(fa, &.{ sub, e.path }), src);
            }
        }
        if (found != 0) {
            std.debug.print("exhaustive guard: {d} unannotated `else =>`\n", .{found});
            return error.ExhaustiveGuard;
        }
    }

    /// Spellings that reach an OS, or a C ABI's varargs, past `std`'s portable
    /// layer. Matched as text, so a `\\` line of emitted device code counts too.
    const os_apis = [_][]const u8{
        "std.posix", "std.os.",   "std.c.",  "@cImport", "std.DynLib",
        "@cVaStart", "@cVaArg",   "@cVaEnd", "@cVaCopy", "std.lang.VaList",
        ".os.tag",   "extern \"", "\"/tmp",  "\"/dev/",
    };

    /// The files that may name one: each says why in its header.
    const os_allowed = [_][]const u8{"src/dynlib.zig"};

    /// Counts every line of `src` naming an `os_apis` entry without `// os:`,
    /// comment lines aside, printing each when `report`.
    fn scanOs(path: []const u8, src: []const u8, report: bool) usize {
        var n: usize = 0;
        var lines = std.mem.splitScalar(u8, src, '\n');
        var line_no: usize = 0;
        while (lines.next()) |line| {
            line_no += 1;
            if (std.mem.startsWith(u8, std.mem.trimStart(u8, line, " \t"), "//")) continue;
            if (std.mem.find(u8, line, "// os:") != null) continue;
            for (os_apis) |api| if (std.mem.find(u8, line, api) != null) {
                if (report) std.debug.print(
                    "{s}:{d}: `{s}` is an OS API\n    fix: use the portable `std` API, move it to {s}, " ++
                        "or put `// os: <why every target still builds>` on the line\n",
                    .{ path, line_no, api, os_allowed[0] },
                );
                n += 1;
                break;
            };
        }
        return n;
    }

    test "no OS API outside the allowlisted module" {
        var arena_state: std.heap.ArenaAllocator = .init(std.heap.page_allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const io = std.testing.io;

        var found: usize = 0;
        const root = try Io.Dir.cwd().openDir(io, repo_root, .{});
        for ([_][]const u8{ "lib", "src" }) |sub| {
            var dir = try root.openDir(io, sub, .{ .iterate = true });
            defer dir.close(io);
            var w = try dir.walk(arena);
            while (try w.next(io)) |e| {
                if (e.kind != .file or !std.mem.endsWith(u8, e.path, ".zig")) continue;
                // `/`, whatever the host's separator, so the allowlist matches.
                const rel = try std.mem.concat(arena, u8, &.{ sub, "/", e.path });
                std.mem.replaceScalar(u8, rel, '\\', '/');
                if (for (os_allowed) |a| {
                    if (std.mem.eql(u8, a, rel)) break true;
                } else false) continue;
                found += scanOs(rel, try dir.readFileAlloc(io, e.path, arena, .limited(1 << 24)), true);
            }
        }
        if (found != 0) {
            std.debug.print("portability guard: {d} OS API use(s)\n", .{found});
            return error.PortabilityGuard;
        }
    }

    test "the portability guard sees what it is for" {
        try std.testing.expectEqual(@as(usize, 1), scanOs("x.zig", "const p = std.posix.getpid();", false));
        try std.testing.expectEqual(@as(usize, 1), scanOs("x.zig", "    \\\\    var ap = @cVaStart();", false));
        try std.testing.expectEqual(@as(usize, 0), scanOs("x.zig", "/// std.posix in prose", false));
        try std.testing.expectEqual(@as(usize, 0), scanOs("x.zig", "const t = std.os.tag; // os: a reason", false));
        try std.testing.expectEqual(@as(usize, 0), scanOs("x.zig", "const io = std.Io.Threaded;", false));
    }
};

pub const citations_tests = struct {
    //! Every diagnostic's `.lrm` citation against the clauses that exist: the
    //! headings of `specification/*.html` (the Verilog-AMS LRM 2023) and the rows of
    //! `tests/fixtures/ieee1364/CLAUSES.tsv` (IEEE 1364-2005, whose PDF is not in
    //! git), both read at test time from `repo_options.repo_root` as
    //! `exhaustive.zig` reads source. In: `diag.info(c).lrm` for every code. Out:
    //! pass, or one line per citation that names no clause.
    //!
    //! No LRM clause: this checks VerA's own catalogue (#68). E0501 cited a
    //! §3.6.1.4 the 2023 LRM does not have (#62); its §3.6.1 has subclauses 1-3.

    const std = @import("std");
    const Io = std.Io;
    const diag = @import("diag");
    const repo_root = @import("repo_options").repo_root;

    const Clauses = std.StringHashMapUnmanaged(void);

    /// `1`, `3.6.1.2`, `A`, `A.1.2`: a number or annex letter, then `.number`s.
    fn isClause(s: []const u8) bool {
        if (s.len == 0) return false;
        var parts = std.mem.splitScalar(u8, s, '.');
        const first = parts.first();
        const annex = first.len == 1 and first[0] >= 'A' and first[0] <= 'H';
        if (!annex and !allDigits(first)) return false;
        while (parts.next()) |p| if (!allDigits(p)) return false;
        return true;
    }

    fn allDigits(s: []const u8) bool {
        if (s.len == 0) return false;
        for (s) |c| if (!std.ascii.isDigit(c)) return false;
        return true;
    }

    /// Adds the clause number that opens each `<h1>`..`<h6>`: "3.6.1.2 Attributes",
    /// "10. Compiler directives", "Annex A (normative) ...". Keys borrow `html`.
    fn addHeadings(gpa: std.mem.Allocator, set: *Clauses, html: []const u8) !void {
        var i: usize = 0;
        while (std.mem.findPos(u8, html, i, "<h")) |at| {
            i = at + 2;
            if (i >= html.len or html[i] < '1' or html[i] > '6') continue;
            const gt = std.mem.findScalarPos(u8, html, i, '>') orelse return;
            var text = html[gt + 1 ..];
            text = text[0 .. std.mem.findScalar(u8, text, '<') orelse text.len];
            if (std.mem.startsWith(u8, text, "Annex ")) text = text["Annex ".len..];
            var tok = text[0 .. std.mem.findScalar(u8, text, ' ') orelse text.len];
            if (std.mem.endsWith(u8, tok, ".")) tok = tok[0 .. tok.len - 1];
            if (isClause(tok)) try set.put(gpa, tok, {});
        }
    }

    test "every diagnostic cites a clause that exists" {
        var arena_state: std.heap.ArenaAllocator = .init(std.heap.page_allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const io = std.testing.io;

        const root = try Io.Dir.cwd().openDir(io, repo_root, .{});
        defer root.close(io);
        var lrm: Clauses = .empty;
        var spec = try root.openDir(io, "specification", .{ .iterate = true });
        defer spec.close(io);
        var it = spec.iterate();
        while (try it.next(io)) |e| {
            if (e.kind != .file or !std.mem.endsWith(u8, e.name, ".html")) continue;
            try addHeadings(arena, &lrm, try spec.readFileAlloc(io, e.name, arena, .limited(1 << 24)));
        }
        // The heading reader found a deep clause and an annex subclause, so a
        // miss below is the citation's, not the reader's.
        try std.testing.expect(lrm.contains("3.6.1.2") and lrm.contains("A.1.2"));

        var ieee: Clauses = .empty;
        const tsv = try root.readFileAlloc(io, "tests/fixtures/ieee1364/CLAUSES.tsv", arena, .limited(1 << 24));
        var lines = std.mem.splitScalar(u8, tsv, '\n');
        while (lines.next()) |line| {
            if (line.len == 0 or line[0] == '#') continue;
            try ieee.put(arena, line[0 .. std.mem.findScalar(u8, line, '\t') orelse line.len], {});
        }

        var missing: usize = 0;
        for (0..@typeInfo(diag.Code).@"enum".field_names.len) |i| {
            const c: diag.Code = @fromBackingInt(@intCast(i));
            const cite = diag.info(c).lrm;
            if (cite.len == 0) continue;
            // `6.3.3 / 3.4.7`: one rule stated in two places.
            var parts = std.mem.splitSequence(u8, cite, " / ");
            while (parts.next()) |p| {
                const ok = if (std.mem.startsWith(u8, p, "IEEE 1364-2005 "))
                    ieee.contains(p["IEEE 1364-2005 ".len..])
                else
                    lrm.contains(p);
                if (ok) continue;
                std.debug.print("{t} cites `{s}`, which is no clause heading\n", .{ c, p });
                missing += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, 0), missing);
    }
};

pub const oom_tests = struct {
    //! L10 fault injection: `checkAllAllocationFailures` over
    //! `compileSourceOpts`, `.lint` on one small positive fixture per chapter and
    //! annex directory, `.build` through codegen on two. Each test fails the n-th
    //! allocation for every n the clean compile makes, over an allocator that
    //! never grows a block in place (`no_grow`), so the count is the same every
    //! run. `BigArena` takes its small blocks from the gpa in chunks, so a
    //! failure lands on whichever allocation grew the arena.
    //!
    //! Oracle: the induced failure surfaces as `error.OutOfMemory` (a success is
    //! `SwallowedOutOfMemoryError`, a diagnostic turned refusal escapes as
    //! `CompileFailed`), the failed compile frees everything it allocated
    //! (`MemoryLeakDetected`), and no other error escapes. No file is written:
    //! these run in-process, so "no partial file" is the CLI's half of L10.

    const std = @import("std");
    const vera = @import("vera");

    /// `check.vh` lives here; every fixture below includes nothing else but the
    /// built-in annex D files.
    const include_dirs: []const []const u8 = &.{@import("repo_options").repo_root ++ "/tests/fixtures"};

    fn compileOne(gpa: std.mem.Allocator, src: []const u8, target: vera.Target) !void {
        var bag: vera.diag.Bag = .init(gpa);
        defer bag.deinit(gpa);
        var res = try vera.compileSourceOpts(gpa, src, target, .{
            .include_dirs = include_dirs,
            .diags = &bag,
            // `.emit` is the fixture testbench's mode, so `.build` reaches display codegen too.
            .display = if (target == .build) .emit else .drop,
        });
        defer res.deinit();
        if (target == .build) {
            _ = try res.generateDevice();
            if (res.device_has_compile_error) return error.CodegenRefused;
        }
    }

    /// `std.testing.allocator` with every in-place growth refused. An arena grows
    /// its block in place when the pages after it happen to be free (the backing
    /// allocator's `rawResize`; on Linux an `mremap` without MAYMOVE), so whether
    /// a compile allocates 19 or 20 times depended on the address space
    /// (2026-10-08: {19, 20, 19} over three clean compiles of one fixture).
    /// Refused, every growth allocates, and the count is the same every run.
    const no_grow: std.mem.Allocator = .{ .ptr = undefined, .vtable = &.{
        .alloc = struct {
            fn f(_: *anyopaque, n: usize, a: std.mem.Alignment, ra: usize) ?[*]u8 {
                return std.testing.allocator.rawAlloc(n, a, ra);
            }
        }.f,
        .resize = struct {
            fn f(_: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) bool {
                return n <= m.len and std.testing.allocator.rawResize(m, a, n, ra);
            }
        }.f,
        .remap = struct {
            fn f(_: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) ?[*]u8 {
                return if (n <= m.len) std.testing.allocator.rawRemap(m, a, n, ra) else null;
            }
        }.f,
        .free = struct {
            fn f(_: *anyopaque, m: []u8, a: std.mem.Alignment, ra: usize) void {
                std.testing.allocator.rawFree(m, a, ra);
            }
        }.f,
    } };

    fn oom(comptime path: []const u8, target: vera.Target) !void {
        const src = @embedFile("fixtures/" ++ path);
        // The sweep assumes every clean compile makes the same allocations; say
        // so by count when one does not, rather than as std's bare
        // NondeterministicMemoryUsage.
        var counts: [3]usize = undefined;
        for (&counts) |*c| {
            var fa: std.testing.FailingAllocator = .init(no_grow, .{});
            try compileOne(fa.allocator(), src, target);
            c.* = fa.alloc_index;
        }
        if (counts[0] != counts[1] or counts[1] != counts[2]) {
            std.debug.print("oom {s}: three clean compiles allocate {any} times\n", .{ path, counts });
            return error.NondeterministicMemoryUsage;
        }
        try std.testing.checkAllAllocationFailures(no_grow, compileOne, .{ src, target });
    }

    test "OOM .lint ch01_intro" {
        try oom("ch01_intro/reference_ground.va", .lint);
    }
    test "OOM .lint ch02_lexical" {
        try oom("ch02_lexical/operator_arity.va", .lint);
    }
    test "OOM .lint ch03_data_types" {
        try oom("ch03_data_types/nature_compatibility_rules.va", .lint);
    }
    test "OOM .lint ch04_expressions" {
        try oom("ch04_expressions/parameter_reduction_and_arithmetic_shift.va", .lint);
    }
    test "OOM .lint ch05_analog_behavior" {
        try oom("ch05_analog_behavior/port_flow_includes_the_reactive_part.va", .lint);
    }
    test "OOM .lint ch06_hierarchy" {
        try oom("ch06_hierarchy/paramset_selected_after_generate.va", .lint);
    }
    test "OOM .lint ch07_mixed_signal" {
        try oom("ch07_mixed_signal/mixed_signal_smallest_abstol.va", .lint);
    }
    test "OOM .lint ch08_scheduling" {
        try oom("ch08_scheduling/shared_conservative_node.va", .lint);
    }
    test "OOM .lint ch09_system_tasks" {
        try oom("ch09_system_tasks/control_default_filling.va", .lint);
    }
    test "OOM .lint ch10_directives" {
        try oom("ch10_directives/default_transition_ramp.va", .lint);
    }
    test "OOM .lint ch11_vpi" {
        try oom("ch11_vpi/vpi_design.va", .lint);
    }
    test "OOM .lint ch12_vpi_routines" {
        try oom("ch12_vpi_routines/rc_ac.va", .lint);
    }
    test "OOM .lint annex_a_syntax" {
        try oom("annex_a_syntax/expression_primaries.va", .lint);
    }
    test "OOM .lint annex_b_keywords" {
        try oom("annex_b_keywords/escaped_keyword_port.va", .lint);
    }
    test "OOM .lint annex_c_analog_subset" {
        try oom("annex_c_analog_subset/compiler_directives.va", .lint);
    }
    test "OOM .lint annex_d_standard_definitions" {
        try oom("annex_d_standard_definitions/thermal_definitions.va", .lint);
    }
    test "OOM .lint annex_e_spice" {
        try oom("annex_e_spice/primitive_mesfet.va", .lint);
    }
    test "OOM .lint annex_f_resolution" {
        try oom("annex_f_resolution/resolveto_resolution.va", .lint);
    }
    test "OOM .lint annex_g_change_history" {
        try oom("annex_g_change_history/transition_fall_time_binding.va", .lint);
    }
    test "OOM .lint annex_h_glossary" {
        try oom("annex_h_glossary/node_port_terminal.va", .lint);
    }
    test "OOM .build ch05_analog_behavior (codegen)" {
        try oom("ch05_analog_behavior/port_flow_includes_the_reactive_part.va", .build);
    }
    test "OOM .build annex_e_spice (codegen)" {
        try oom("annex_e_spice/primitive_mesfet.va", .build);
    }
};

pub const ulp_tests = struct {
    //! L3 math oracle: every f64 function `contract.gm`
    //! exports, against an f128 reference, in units of the last place of an f64
    //! at the reference's magnitude. In: hard cases (specials, range ends,
    //! reduction seams, subnormals) and seeded random arguments; out: each
    //! function's worst error, asserted against the bound measured on 2026-10-08
    //! and written beside it. The references are compiler_rt's binary128 `@exp`,
    //! `@log`, `@sin`, `@cos`, `@sqrt` and `std.math.atan`/`asin`/`acos`'s
    //! binary128 paths, with a series wherever a difference would cancel; none
    //! of it is `gm`'s code, and pow's and atan2's special cases are C99
    //! F.10.4.4's and F.10.1.4's lists, transcribed here. asin and acos are
    //! `std.math`'s f64 functions, the ones a device and the folder call (#60).
    //!
    //! Host only: `gm`'s GPU branches (the tanh/sinh/cosh/sin/cos ports) are
    //! private and compile only for NVPTX and AMDGCN, so their bound is not
    //! measured here. On the host tanh, sinh, cosh, expm1 and atan are
    //! `std.math`'s and sin/cos the builtins; their rows pin what a device built
    //! for the host gets.

    const std = @import("std");
    const gm = @import("contract").gm;

    const Q = f128;
    const inf = std.math.inf(f64);
    const nan = std.math.nan(f64);

    /// |got - ref| in units of 2^(e-52), where 2^e <= |ref| < 2^(e+1), e clamped
    /// to f64's normal range [-1022, 1023] (so below 2^-1022 the unit is the
    /// least subnormal). An infinite `got` stands for 2^1024, one unit past the
    /// largest double, and is exact when |ref| is at least that. NaN must meet NaN.
    fn ulpErr(got: f64, ref: Q) f64 {
        if (std.math.isNan(ref) or std.math.isNan(got))
            return if (std.math.isNan(ref) and std.math.isNan(got)) 0 else inf;
        const big: Q = 0x1p1024;
        var g: Q = got;
        if (std.math.isInf(got)) {
            if (@abs(ref) >= big and std.math.signbit(got) == std.math.signbit(ref)) return 0;
            g = std.math.copysign(big, @as(Q, got));
        }
        const a = @abs(ref);
        const e: i32 = if (a < 0x1p-1022) -1022 else @min(std.math.ilogb(a), 1023);
        return @floatCast(@abs(g - ref) / std.math.ldexp(@as(Q, 1), e - 52));
    }

    // ---- the references ------------------------------------------------------

    fn expQ(x: f64) Q {
        return @exp(@as(Q, x));
    }
    fn logQ(x: f64) Q {
        return @log(@as(Q, x));
    }
    fn sinQ(x: f64) Q {
        return @sin(@as(Q, x));
    }
    fn cosQ(x: f64) Q {
        return @cos(@as(Q, x));
    }
    fn atanQ(x: f64) Q {
        return std.math.atan(@as(Q, x));
    }

    /// e^x - 1 = Σ x^n/n! (n >= 1), summed: no cancellation near 0.
    fn expm1Series(x: f64) Q {
        const q: Q = x;
        var term = q;
        var sum: Q = 0;
        var n: Q = 1;
        while (n < 40) : (n += 1) {
            sum += term;
            term = term * q / (n + 1);
        }
        return sum;
    }

    /// sinh x = Σ x^n/n! (n odd), summed for the same reason.
    fn sinhSeries(x: f64) Q {
        const q: Q = x;
        var term = q;
        var sum: Q = 0;
        var n: Q = 1;
        while (n < 60) : (n += 2) {
            sum += term;
            term = term * q * q / ((n + 1) * (n + 2));
        }
        return sum;
    }

    fn expm1Q(x: f64) Q {
        if (@abs(x) < 0.25) return expm1Series(x);
        return @exp(@as(Q, x)) - 1;
    }
    fn sinhQ(x: f64) Q {
        if (std.math.isInf(x)) return x;
        if (@abs(x) < 0.25) return sinhSeries(x);
        const e = @exp(@as(Q, x));
        return (e - 1 / e) / 2;
    }
    fn coshQ(x: f64) Q {
        if (std.math.isInf(x)) return inf;
        const e = @exp(@as(Q, x));
        return (e + 1 / e) / 2;
    }
    fn tanhQ(x: f64) Q {
        if (std.math.isInf(x)) return std.math.copysign(@as(Q, 1), @as(Q, x));
        if (@abs(x) > 40) return std.math.copysign(@as(Q, 1), @as(Q, x)) * (1 - 2 * @exp(-2 * @abs(@as(Q, x))));
        return sinhQ(x) / coshQ(x);
    }

    /// The inverse hyperbolics and log10 in binary128, from `@log` and `@sqrt`:
    /// 113 bits leave each formula's cancellation (asinh at x < 0 is taken at
    /// |x|; acosh's x² - 1 as (x - 1)(x + 1), exact near 1) far below an f64
    /// ulp, and below 2^-30 the odd ones are their series.
    fn asinhQ(x: f64) Q {
        if (std.math.isNan(x) or std.math.isInf(x)) return x;
        const a: Q = @abs(@as(Q, x));
        const r = if (a < 0x1p-30) a - a * a * a / 6 else @log(a + @sqrt(a * a + 1));
        return std.math.copysign(r, @as(Q, x));
    }
    fn acoshQ(x: f64) Q {
        if (std.math.isNan(x) or x < 1) return nan;
        if (std.math.isInf(x)) return inf;
        const q: Q = x;
        return @log(q + @sqrt((q - 1) * (q + 1)));
    }
    fn atanhQ(x: f64) Q {
        if (std.math.isNan(x) or @abs(x) > 1) return nan;
        if (@abs(x) == 1) return std.math.copysign(@as(Q, inf), @as(Q, x));
        const a: Q = @abs(@as(Q, x));
        const r = if (a < 0x1p-30) a + a * a * a / 3 else @log((1 + a) / (1 - a)) / 2;
        return std.math.copysign(r, @as(Q, x));
    }
    fn log10Q(x: f64) Q {
        if (std.math.isNan(x) or x < 0) return nan;
        if (x == 0) return -inf;
        if (std.math.isInf(x)) return inf;
        return @log(@as(Q, x)) / @log(@as(Q, 10));
    }
    fn tanQ(x: f64) Q {
        return @sin(@as(Q, x)) / @cos(@as(Q, x));
    }
    /// atan2 by quadrant from `atanQ`, with C99 F.10.1.4's zeros and infinities.
    fn atan2Q(y: f64, x: f64) Q {
        if (std.math.isNan(x) or std.math.isNan(y)) return nan;
        const pi: Q = std.math.pi;
        const yq: Q = y;
        const xq: Q = x;
        if (y == 0) return if (std.math.signbit(x)) std.math.copysign(pi, yq) else yq;
        if (x == 0) return std.math.copysign(pi / 2, yq);
        if (std.math.isInf(x) or std.math.isInf(y)) {
            const a: Q = if (std.math.isInf(x) and std.math.isInf(y)) pi / 4 else if (std.math.isInf(y)) pi / 2 else 0;
            const r = if (x < 0) pi - a else a;
            return std.math.copysign(r, yq);
        }
        const z = std.math.atan(@abs(yq / xq));
        return if (x > 0) std.math.copysign(z, yq) else std.math.copysign(pi - z, yq);
    }

    fn isInt(y: f64) bool {
        return std.math.isFinite(y) and @trunc(y) == y;
    }
    fn isOdd(y: f64) bool {
        return isInt(y) and @abs(y) < 0x1p53 and @mod(y, 2) == 1;
    }

    /// C99 F.10.4.4, row by row; null when x and y are finite, x is not ±0 and
    /// not 1, and the result is an ordinary power.
    fn powSpecial(x: f64, y: f64) ?f64 {
        if (x == 1 or y == 0) return 1; // "even if" the other is a NaN
        if (std.math.isNan(x) or std.math.isNan(y)) return nan;
        if (x == 0) {
            if (y < 0) return if (isOdd(y)) std.math.copysign(inf, x) else inf;
            return if (isOdd(y)) x else 0;
        }
        if (std.math.isInf(y)) {
            if (x == -1) return 1;
            return if ((@abs(x) < 1) == (y < 0)) inf else 0;
        }
        if (std.math.isInf(x)) {
            if (x < 0) {
                if (y < 0) return if (isOdd(y)) -0.0 else 0;
                return if (isOdd(y)) -inf else inf;
            }
            return if (y < 0) 0 else inf;
        }
        if (x < 0 and !isInt(y)) return nan;
        return null;
    }

    fn powQ(x: f64, y: f64) Q {
        if (powSpecial(x, y)) |s| return s;
        const m = @exp(@as(Q, y) * @log(@abs(@as(Q, x))));
        return if (x < 0 and isOdd(y)) -m else m;
    }

    // ---- the functions under test -------------------------------------------

    fn exp(x: f64) f64 {
        return gm.exp(x);
    }
    fn log(x: f64) f64 {
        return gm.log(x);
    }
    fn expm1(x: f64) f64 {
        return gm.expm1(x);
    }
    fn sinh(x: f64) f64 {
        return gm.sinh(x);
    }
    fn cosh(x: f64) f64 {
        return gm.cosh(x);
    }
    fn tanh(x: f64) f64 {
        return gm.tanh(x);
    }
    fn sin(x: f64) f64 {
        return gm.sin(x);
    }
    fn cos(x: f64) f64 {
        return gm.cos(x);
    }
    fn atan(x: f64) f64 {
        return gm.atan(x);
    }
    fn asinh(x: f64) f64 {
        return gm.asinh(x);
    }
    fn acosh(x: f64) f64 {
        return gm.acosh(x);
    }
    fn atanh(x: f64) f64 {
        return gm.atanh(x);
    }
    fn log10(x: f64) f64 {
        return gm.log10(x);
    }
    fn tan(x: f64) f64 {
        return gm.tan(x);
    }
    fn expV(x: @Vector(4, f64)) @Vector(4, f64) {
        return gm.exp(x);
    }
    fn logV(x: @Vector(4, f64)) @Vector(4, f64) {
        return gm.log(x);
    }

    // ---- argument generators -------------------------------------------------

    /// ±2^u·(1 + frac), u uniform in [lo, hi]: every binade equally often.
    fn binade(r: std.Random, lo: i32, hi: i32) f64 {
        const m = 1 + r.float(f64);
        const v = std.math.ldexp(m, r.intRangeAtMost(i32, lo, hi));
        return if (r.boolean()) -v else v;
    }
    fn uniform(r: std.Random, lo: f64, hi: f64) f64 {
        return lo + (hi - lo) * r.float(f64);
    }

    fn genExp(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1 => binade(r, -1074, -1),
            // exp's reduction table has 128 entries per ln 2: land on its seams.
            2 => @as(f64, @floatFromInt(r.intRangeAtMost(i32, -137000, 131000))) * (std.math.ln2 / 128.0) * (1 + uniform(r, -1e-15, 1e-15)),
            else => uniform(r, -745.2, 709.8),
        };
    }
    fn genLog(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1, 2, 3, 4 => @bitCast(r.intRangeAtMost(u64, 1, 0x7fefffffffffffff)),
            5, 6 => 1 + uniform(r, -0x1p-4, 0x1p-4),
            7 => 1 + std.math.ldexp(uniform(r, -1, 1), -r.intRangeAtMost(i32, 5, 60)),
            else => uniform(r, 0.5, 2),
        };
    }
    fn genExpm1(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1, 2 => binade(r, -1074, -2),
            3, 4 => uniform(r, -1, 1),
            else => uniform(r, -40, 709.8),
        };
    }
    fn genHyp(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1 => binade(r, -1074, -2),
            2, 3, 4 => uniform(r, -2, 2),
            else => uniform(r, -710.4, 710.4),
        };
    }
    fn genTanh(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1 => binade(r, -1074, -2),
            2, 3 => uniform(r, -1, 1),
            else => uniform(r, -25, 25),
        };
    }
    fn genTrig(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0 => binade(r, -1074, -2),
            1, 2, 3 => uniform(r, -1e6, 1e6),
            else => uniform(r, -10, 10),
        };
    }
    fn genAtan(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1, 2, 3, 4 => binade(r, -1074, 1023),
            else => uniform(r, -4, 4),
        };
    }

    fn genAsinh(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1, 2, 3 => binade(r, -1074, 1023),
            4, 5 => binade(r, -30, 2),
            else => uniform(r, -4, 4),
        };
    }
    fn genAcosh(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1, 2 => @abs(binade(r, 0, 1023)),
            3, 4, 5 => 1 + std.math.ldexp(r.float(f64), -r.intRangeAtMost(i32, 1, 52)),
            else => uniform(r, 1, 4),
        };
    }
    fn genAtanh(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1, 2 => binade(r, -1074, -1),
            3, 4 => std.math.copysign(1 - std.math.ldexp(r.float(f64), -r.intRangeAtMost(i32, 1, 52)), uniform(r, -1, 1)),
            else => uniform(r, -1, 1),
        };
    }
    fn genUnit(r: std.Random) f64 {
        return switch (r.uintLessThan(u8, 10)) {
            0, 1 => binade(r, -1074, -1),
            2, 3 => std.math.copysign(1 - std.math.ldexp(r.float(f64), -r.intRangeAtMost(i32, 1, 52)), uniform(r, -1, 1)),
            else => uniform(r, -1, 1),
        };
    }
    fn asin(x: f64) f64 {
        return std.math.asin(x);
    }
    fn acos(x: f64) f64 {
        return std.math.acos(x);
    }
    fn asinQ(x: f64) Q {
        if (std.math.isNan(x) or @abs(x) > 1) return nan;
        return std.math.asin(@as(Q, x));
    }
    fn acosQ(x: f64) Q {
        if (std.math.isNan(x) or @abs(x) > 1) return nan;
        return std.math.acos(@as(Q, x));
    }

    // ---- the judge -----------------------------------------------------------

    const Worst = struct {
        ulp: f64 = 0,
        x: f64 = 0,
        y: f64 = 0,

        fn see(w: *Worst, e: f64, x: f64, y: f64) void {
            if (e > w.ulp or std.math.isNan(e)) w.* = .{ .ulp = e, .x = x, .y = y };
        }

        /// Whether the worst case is within `bound`; prints it when not, so
        /// one run reports every function.
        fn within(w: Worst, name: []const u8, limit: f64) bool {
            if (w.ulp <= limit) return true;
            std.debug.print("ulp: {s}: {d:.4} ulp at x = {e} (y = {e}), over the bound {d}\n", .{ name, w.ulp, w.x, w.y, limit });
            return false;
        }
    };

    const n_random = 250_000;

    /// Hard cases every unary function sees besides its own.
    const common = [_]f64{
        0,         -0.0,      inf,                     -inf,         nan,    0x1p-1074,              -0x1p-1074,
        0x1p-1022, 0x1p-1023, 0x1.fffffffffffffp-1023, 1,            -1,     0.5,                    -0.5,
        2,         -2,        std.math.pi,             -std.math.pi, 1e-300, std.math.floatMax(f64), -std.math.floatMax(f64),
    };

    fn judge1(comptime f: fn (f64) f64, comptime ref: fn (f64) Q, hard: []const f64, comptime gen: fn (std.Random) f64, seed: u64) Worst {
        var w: Worst = .{};
        for (common) |x| w.see(ulpErr(f(x), ref(x)), x, 0);
        for (hard) |x| w.see(ulpErr(f(x), ref(x)), x, 0);
        var prng: std.Random.DefaultPrng = .init(seed);
        for (0..n_random) |_| {
            const x = gen(prng.random());
            w.see(ulpErr(f(x), ref(x)), x, 0);
        }
        return w;
    }

    /// The vector form, four random lanes at a time, every lane judged.
    fn judgeV(comptime f: fn (@Vector(4, f64)) @Vector(4, f64), comptime ref: fn (f64) Q, comptime gen: fn (std.Random) f64, seed: u64) Worst {
        var w: Worst = .{};
        var prng: std.Random.DefaultPrng = .init(seed);
        for (0..n_random / 4) |_| {
            var v: @Vector(4, f64) = undefined;
            inline for (0..4) |l| v[l] = gen(prng.random());
            const got = f(v);
            inline for (0..4) |l| w.see(ulpErr(got[l], ref(v[l])), v[l], 0);
        }
        return w;
    }

    /// exp's seams: the overflow and underflow thresholds, and the last
    /// argument whose result is normal.
    const exp_hard = [_]f64{
        0x1.62e42fefa39efp9,  0x1.62e42fefa39f0p9,  -0x1.74910d52d3051p9, -0x1.74910d52d3052p9,
        -0x1.6232bdd7abcd2p9, -0x1.6232bdd7abcd3p9, 709.7,                -708.4,
        -745.0,               1e-17,                -1e-17,               0x1p-53,
    };
    const log_hard = [_]f64{
        0x1.0000000000001p0,  0x1.fffffffffffffp-1, 0x1.0000000000002p0, 0x1.ffffffffffffep-1,
        0x1.6a09e667f3bcdp-1, 0x1.6a09e667f3bccp-1, 0x1p-1060,           1e-310,
        std.math.e,           10,                   0x1p1023,            1.0000001,
    };
    const expm1_hard = [_]f64{
        0x1p-60, -0x1p-60, 0x1p-54, -0x1p-54, 0.3465,  -0.3465, 0.3466, -0.3466, 1.0397, -1.0397,
        1.0398,  -1.0398,  0.25,    -0.25,    -0.2501, 38.8,    -38.8,  38.9,    709.78, 710,
        -745,
    };
    const hyp_hard = [_]f64{ 0.625, -0.625, 0.6249999999999999, 22, -22, 710.4, 710.5, -710.5, 0x1p-28, 20, 40.5 };
    const trig_hard = [_]f64{
        std.math.pi / 2.0, -std.math.pi / 2.0, std.math.pi / 4.0, 3.0 * std.math.pi / 2.0, 1e5, 1.6e6, 1e9, 1e22, 1e300, 0x1p-28,
    };
    const atan_hard = [_]f64{ 0.4375, 0.6875, 1.1875, 2.4375, 0x1p66, -0x1p66, 0x1p-27, 7.0 / 16.0, 39.0 / 16.0 };
    /// The musl branch seams (|x| = 2^-26, 2, 2^26; acosh's 2 and 2^26;
    /// atanh's 2^-32 and 0.5), and #60's values.
    const asinh_hard = [_]f64{ 0x1p-26, -0x1p-26, 0x1.fffffffffffffp-27, 2, -2, 0x1.fffffffffffffp0, 0x1p26, -0x1p26, 1e154, 1e155, -1e8, -1e3, 1e-10, 1e300 };
    const acosh_hard = [_]f64{ 0x1.0000000000001p0, 0x1.0000000000002p0, 1.0000000001, 0x1.fffffffffffffp0, 0x1p26, 0x1.fffffffffffffp25, 1e154, 1e300, 0.5, 0x1.fffffffffffffp-1 };
    const atanh_hard = [_]f64{ 0x1p-32, 0x1.fffffffffffffp-33, 0.5, 0x1.fffffffffffffp-2, -0.5, 0x1.fffffffffffffp-1, -0x1.fffffffffffffp-1, 1e-10, 0.9999999999 };
    const log10_hard = [_]f64{ 1e15, 1e-15, 10, 100, 1e22, 1e-300, 1e300, 0x1.6a09e667f3bcdp-1, 0x1.0000000000001p0, 0x1.fffffffffffffp-1, 0x1p-1060 };

    /// The bounds: each function's worst case on 2026-10-08 with this file's
    /// seeds, rounded up in the third decimal. `gm`'s own promise is "faithful
    /// (< 1 ulp)" for exp, log and pow; a change that moves a bound moves it here.
    const bound = struct {
        const exp = 0.507; // 0.5062 at 163.57479821851769 (vector: 0.5052)
        const log = 0.515; // 0.5142 at 1.0843856890111225, a vector lane (scalar: 0.5112)
        const pow = 0.506; // 0.5059 at (-143136349.3604563, 21), scalar and powV
        // On the host the rest are std.math's and compiler_rt's, which promise
        // no bound; sinh, cosh and tanh are not faithful.
        const expm1 = 0.810; // 0.8094 at 0.35354502149644396
        const sinh = 1.739; // 1.7386 at 0.6943002823977769
        const cosh = 1.200; // 1.1992 at -1.0407498633762968
        const tanh = 2.030; // 2.0294 at 0.2498982405738699
        const sin = 0.747; // 0.7463 at 7.080094367729739
        const cos = 0.733; // 0.7327 at -3.863213591144243
        const atan = 0.751; // 0.7507 at 2.680128387647313
        // #60's rows (asinh, acosh, atanh, log10, atan2, tan: `gm`'s musl ports
        // and sin/cos quotient; asin/acos: `std.math`, what a device calls),
        // measured by this file on 2026-10-18 (ReleaseSafe, x86_64).
        const asinh = 1.524; // 1.5239 at 0.51700870116405
        const acosh = 2.016; // 2.0151 at 1.001887151218172
        const atanh = 1.505; // 1.5049 at -0.12030145777284262
        const log10 = 0.630; // 0.6297 at 1.374951715281116
        const tan = 2.006; // 2.0055 at -145126.64517723466
        const asin = 0.817; // 0.8162 at -0.5042767798999156
        const acos = 0.864; // 0.8632 at -0.5232333655933563
        const atan2 = 1.441; // 1.4405 at y = 0.06365036518777245
    };

    test "L3 ulp: gm.asinh, acosh, atanh, log10 and tan, and std's asin and acos (#60)" {
        var ok = judge1(asinh, asinhQ, &asinh_hard, genAsinh, 13).within("asinh", bound.asinh);
        ok = judge1(acosh, acoshQ, &acosh_hard, genAcosh, 14).within("acosh", bound.acosh) and ok;
        ok = judge1(atanh, atanhQ, &atanh_hard, genAtanh, 15).within("atanh", bound.atanh) and ok;
        ok = judge1(log10, log10Q, &log10_hard, genLog, 16).within("log10", bound.log10) and ok;
        ok = judge1(tan, tanQ, &trig_hard, genTrig, 17).within("tan", bound.tan) and ok;
        ok = judge1(asin, asinQ, &atanh_hard, genUnit, 18).within("asin", bound.asin) and ok;
        ok = judge1(acos, acosQ, &atanh_hard, genUnit, 19).within("acos", bound.acos) and ok;
        try std.testing.expect(ok);
        // C's log10 is exact at every power of ten, and floor(log10(x)) is how
        // a model counts decades: ln(x)/ln(10) gave 14.999999999999998 at 1e15.
        var p: f64 = 1;
        for (0..23) |k| {
            try std.testing.expectEqual(@as(f64, @floatFromInt(k)), gm.log10(p));
            p *= 10;
        }
        // The values #60 found wrong, from mpmath at 50 digits, correctly rounded
        // or within the bound above: asinh(-1e8) cancelled to -inf, asinh and
        // acosh of 1e300 overflowed x², asinh(1e-10) lost 7 digits.
        try std.testing.expectEqual(@as(f64, -19.11382792451231), gm.asinh(-1e8));
        try std.testing.expect(std.math.approxEqRel(f64, gm.asinh(1e300), 691.4686750787737, 3e-16));
        try std.testing.expect(std.math.approxEqRel(f64, gm.acosh(1e300), 691.4686750787737, 3e-16));
        try std.testing.expectEqual(@as(f64, 1e-10), gm.asinh(1e-10));
        try std.testing.expectEqual(@as(f64, 1e-10), gm.atanh(1e-10));
        // The odd ones keep the sign of zero; atanh's poles are infinities.
        inline for (.{ asinh, atanh }) |f| try std.testing.expect(std.math.signbit(f(-0.0)));
        try std.testing.expectEqual(inf, gm.atanh(1.0));
        try std.testing.expectEqual(-inf, gm.atanh(-1.0));
        // A subnormal argument is scaled by 2^54 first; both words of the scaled
        // value must be used (the first run of this file found 3.75e6 ulp at
        // 3.74e-309). References: CPython's math.log10.
        try std.testing.expect(std.math.approxEqRel(f64, gm.log10(3.74288017396525e-309), -308.426794076337, 4e-16));
        try std.testing.expect(std.math.approxEqRel(f64, gm.log10(0x1p-1074), -323.3062153431158, 4e-16));
        try std.testing.expect(std.math.approxEqRel(f64, gm.log10(2.2250738585072009e-308), -307.6526555685888, 4e-16));
        try std.testing.expectEqual(-inf, gm.log10(0.0));
        try std.testing.expect(std.math.isNan(gm.log10(-1.0)));
        try std.testing.expect(std.math.isNan(gm.acosh(0.5)));
    }

    test "L3 ulp: gm.atan2, with C99 F.10.1.4's signed zeros (#60)" {
        var w: Worst = .{};
        var prng: std.Random.DefaultPrng = .init(20);
        const r = prng.random();
        for (0..n_random) |i| {
            const y = if (i % 3 == 0) binade(r, -1074, 1023) else uniform(r, -4, 4);
            const x = if (i % 5 == 0) binade(r, -1074, 1023) else uniform(r, -4, 4);
            w.see(ulpErr(gm.atan2(y, x), atan2Q(y, x)), y, x);
        }
        const sp = [_]f64{ 0, -0.0, 1, -1, 0.5, -2, inf, -inf, nan, 0x1p-1074, 1e300 };
        for (sp) |y| for (sp) |x| {
            const want = atan2Q(y, x);
            const got = gm.atan2(y, x);
            w.see(ulpErr(got, want), y, x);
            // A zero carries its sign, which ulpErr cannot see.
            if (want == 0 and std.math.signbit(got) != std.math.signbit(want)) {
                std.debug.print("ulp: atan2({e}, {e}) = {e}, C99 F.10.1.4 says {e}\n", .{ y, x, got, @as(f64, @floatCast(want)) });
                return error.UlpBound;
            }
        };
        try std.testing.expect(w.within("atan2", bound.atan2));
        // Table 4-15's atan2(0,0) = 0 is C's +0, +0; the others are C's.
        try std.testing.expectEqual(@as(f64, 0), gm.atan2(0.0, 0.0));
        try std.testing.expectEqual(-std.math.pi, gm.atan2(-0.0, -1.0));
        try std.testing.expectEqual(std.math.pi, gm.atan2(0.0, -0.0));
        try std.testing.expectEqual(-std.math.pi, gm.atan2(-0.0, -0.0));
        try std.testing.expectEqual(std.math.pi / 2.0, gm.atan2(1.0, 0.0));
    }

    test "L3 ulp: gm.exp and its vector form stay within the measured bound of an f128 reference" {
        var ok = judge1(exp, expQ, &exp_hard, genExp, 1).within("exp", bound.exp);
        ok = judgeV(expV, expQ, genExp, 2).within("exp (vector)", bound.exp) and ok;
        try std.testing.expect(ok);
    }

    test "L3 ulp: gm.log and its vector form" {
        var ok = judge1(log, logQ, &log_hard, genLog, 3).within("log", bound.log);
        ok = judgeV(logV, logQ, genLog, 4).within("log (vector)", bound.log) and ok;
        try std.testing.expect(ok);
        // The negative half, zero and -inf: NaN and -inf, never a number.
        for ([_]f64{ -1, -0x1p-1074, -inf, -1e300 }) |x| try std.testing.expect(std.math.isNan(gm.log(x)));
        try std.testing.expectEqual(-inf, gm.log(-0.0));
    }

    test "L3 ulp: gm.pow and powV, with C99 F.10.4.4's special cases bit for bit" {
        var w: Worst = .{};
        var wv: Worst = .{};
        var prng: std.Random.DefaultPrng = .init(5);
        const r = prng.random();
        for (0..n_random) |i| {
            var x: f64 = undefined;
            var y: f64 = undefined;
            switch (i % 5) {
                // Any positive base, an exponent whose result lands anywhere
                // from underflow to overflow.
                0, 1 => {
                    x = @abs(binade(r, -1074, 1023));
                    y = uniform(r, -1100, 1100) / std.math.log2(x);
                },
                2 => {
                    x = @abs(binade(r, -20, 20));
                    y = uniform(r, -10, 10);
                },
                // A negative base and an integer exponent.
                3 => {
                    x = -@abs(binade(r, -30, 30));
                    y = @trunc(uniform(r, -40, 40));
                },
                // Near 1, raised far.
                else => {
                    x = 1 + std.math.ldexp(uniform(r, -1, 1), -r.intRangeAtMost(i32, 10, 52));
                    y = binade(r, 0, 60);
                },
            }
            w.see(ulpErr(gm.pow(x, y), powQ(x, y)), x, y);
            const v = gm.powV(@as(@Vector(2, f64), .{ x, -x }), y);
            wv.see(ulpErr(v[0], powQ(x, y)), x, y);
            wv.see(ulpErr(v[1], powQ(-x, y)), -x, y);
        }
        const sp = [_]f64{ 0, -0.0, 1, -1, 0.5, -0.5, 2, -2, 3, -3, 2.5, -2.5, inf, -inf, nan, 0x1p53, -0x1p53, 0x1p-1074 };
        for (sp) |x| for (sp) |y| {
            const want = powQ(x, y);
            const got = gm.pow(x, y);
            w.see(ulpErr(got, want), x, y);
            // A zero or an infinity carries its sign: ulpErr cannot see it.
            if (powSpecial(x, y)) |s| if (!std.math.isNan(s) and std.math.signbit(s) != std.math.signbit(got)) {
                std.debug.print("ulp: pow({e}, {e}) = {e}, C99 F.10.4.4 says {e}\n", .{ x, y, got, s });
                return error.UlpBound;
            };
        };
        const ok = w.within("pow", bound.pow);
        try std.testing.expect(wv.within("powV", bound.pow) and ok);
    }

    test "L3 ulp: gm.expm1, sinh, cosh and tanh" {
        var ok = judge1(expm1, expm1Q, &expm1_hard, genExpm1, 6).within("expm1", bound.expm1);
        ok = judge1(sinh, sinhQ, &hyp_hard, genHyp, 7).within("sinh", bound.sinh) and ok;
        ok = judge1(cosh, coshQ, &hyp_hard, genHyp, 8).within("cosh", bound.cosh) and ok;
        ok = judge1(tanh, tanhQ, &hyp_hard, genTanh, 9).within("tanh", bound.tanh) and ok;
        try std.testing.expect(ok);
    }

    test "L3 ulp: gm.sin, cos and atan" {
        var ok = judge1(sin, sinQ, &trig_hard, genTrig, 10).within("sin", bound.sin);
        ok = judge1(cos, cosQ, &trig_hard, genTrig, 11).within("cos", bound.cos) and ok;
        ok = judge1(atan, atanQ, &atan_hard, genAtan, 12).within("atan", bound.atan) and ok;
        try std.testing.expect(ok);
    }

    test "L3 ulp: the odd functions keep the sign of zero" {
        inline for (.{ sin, tanh, sinh, expm1, atan }) |f| {
            try std.testing.expect(std.math.signbit(f(-0.0)));
            try std.testing.expect(!std.math.signbit(f(0.0)));
        }
    }
};
